    private func bootstrapProductionCaptureDefaultsIfNeeded(arguments: [String]) {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: CaptureDefaults.configured) else { return }
        defaults.set(true, forKey: CaptureDefaults.configured)
        defaults.set(true, forKey: CaptureDefaults.protectedLongWearMigrated)
        defaults.set(true, forKey: CaptureDefaults.strapStepFullProtocolMigrated)
        defaults.set(true, forKey: CaptureDefaults.stableR10TransportMigrated)
        defaults.set(true, forKey: LongWearDefaults.enabled)
        defaults.set(true, forKey: RadioDefaults.standardHROnly)
        defaults.set(true, forKey: OfflineSyncDefaults.enabled)
        if defaults.object(forKey: LongWearDefaults.checkpointInterval) == nil {
            defaults.set(60.0, forKey: LongWearDefaults.checkpointInterval)
        }
        if defaults.object(forKey: LongWearDefaults.diagnosticInterval) == nil {
            defaults.set(15.0, forKey: LongWearDefaults.diagnosticInterval)
        }
        if defaults.object(forKey: LongWearDefaults.workoutAutoSaveInterval) == nil {
            defaults.set(15.0, forKey: LongWearDefaults.workoutAutoSaveInterval)
        }
        if defaults.object(forKey: LongWearDefaults.noDataTimeout) == nil {
            defaults.set(75.0, forKey: LongWearDefaults.noDataTimeout)
        }
        if defaults.object(forKey: LongWearDefaults.noDataCheckInterval) == nil {
            defaults.set(15.0, forKey: LongWearDefaults.noDataCheckInterval)
        }
        if defaults.object(forKey: LongWearDefaults.acceptedHRTimeout) == nil {
            defaults.set(45.0, forKey: LongWearDefaults.acceptedHRTimeout)
        }
        if defaults.string(forKey: LongWearDefaults.label) == nil {
            defaults.set("All-day wear", forKey: LongWearDefaults.label)
        }
        if defaults.string(forKey: CollectionProfileDefaults.profile) == nil {
            defaults.set(CollectionProfile.balanced.rawValue, forKey: CollectionProfileDefaults.profile)
        }
        collectionProfile = CollectionProfile.load(defaults: defaults)
        longWearModeEnabled = true
        updateSessionPointCacheMode()
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        let explicitMode = arguments.contains("--atria-standard-hr-only") || arguments.contains("--atria-long-wear-mode") ? 1 : 0
        recordRadioMode("protected_r10_minimal", reason: "stable_hr_r10_default")
        AtriaDebugLog("ATRIADBG capture_defaults status=enabled mode=protected_r10_minimal long_wear_default=1 strap_steps_background=1 offline_sync_default=1 reason=first_normal_launch explicit_mode_arg=%d checkpoint_interval_s=60 live_workout_interval_s=15 workout_autosave_interval_s=15 no_data_timeout_s=75 accepted_hr_timeout_s=45 hr_continuity_timeout_s=6 recovery_policy=staged_read_reassert_then_fresh_scan",
              explicitMode)
    }

    private func migrateAutomaticLongWearDefaultIfNeeded(arguments: [String]) {
        let defaults = UserDefaults.standard
        guard !arguments.contains("--atria-full-protocol-mode") else { return }
        guard defaults.bool(forKey: CaptureDefaults.configured) else { return }
        guard !defaults.bool(forKey: LongWearDefaults.userSelected) else { return }
        guard !defaults.bool(forKey: CaptureDefaults.protectedLongWearMigrated) else { return }

        defaults.set(true, forKey: CaptureDefaults.protectedLongWearMigrated)
        defaults.set(true, forKey: LongWearDefaults.enabled)
        defaults.set(true, forKey: RadioDefaults.standardHROnly)
        longWearModeEnabled = true
        updateSessionPointCacheMode()
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        forceFreshScanOnRestore = true
        recordRadioMode("protected_r10_minimal", reason: "protected_default_migration")
        AtriaDebugLog("ATRIADBG long_wear_mode status=migrated_default action=enabled reason=protected_background_collection_default")
    }

    /// Continuous strap capture is a product invariant. Older builds let the
    /// user disable it, then later removed that control; preserving the hidden
    /// false value strands the app in foreground-only collection and prevents
    /// sleep/activity evidence from being journaled. Full-protocol diagnostics
    /// remain isolated and never consume the production migration.
    @discardableResult
    nonisolated static func migrateAlwaysOnLongWearIfNeeded(
        defaults: UserDefaults = .standard,
        arguments: [String] = ProcessInfo.processInfo.arguments
    ) -> Bool {
        guard !arguments.contains("--atria-full-protocol-mode") else { return false }
        guard defaults.bool(forKey: CaptureDefaults.configured) else { return false }
        guard !defaults.bool(forKey: CaptureDefaults.alwaysOnLongWearMigrated) else { return false }

        defaults.set(true, forKey: CaptureDefaults.alwaysOnLongWearMigrated)
        defaults.set(true, forKey: LongWearDefaults.enabled)
        // The retired toggle must not continue to block later automatic
        // migrations. This does not change the independent battery-saver/radio
        // preference.
        defaults.set(false, forKey: LongWearDefaults.userSelected)
        return true
    }

    private func migrateOfflineSyncDefaultIfNeeded(arguments: [String]) {
        guard !arguments.contains("--atria-full-protocol-mode") else { return }
        guard UserDefaults.standard.object(forKey: OfflineSyncDefaults.enabled) == nil else { return }
        UserDefaults.standard.set(true, forKey: OfflineSyncDefaults.enabled)
        AtriaDebugLog("ATRIADBG offline_sync status=migrated_default action=enabled reason=stored_session_backfill_default")
    }

    /// Rollbacks written before the history/R10 ownership interlock were
    /// contaminated by historical-recovery reconnects. Clear that obsolete
    /// cooldown exactly once after upgrading so existing users can qualify the
    /// corrected transport immediately instead of keeping frozen steps for up
    /// to six hours. No health, workout, sleep, archive, or calibration data is
    /// touched.
    private func migrateProtectedR10HistoryInterlockIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: Self.protectedR10HistoryInterlockMigrationKey) else { return }
        defaults.set(true, forKey: Self.protectedR10HistoryInterlockMigrationKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(0, forKey: Self.protectedR10RetryCountKey)
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.removeObject(forKey: "atria.protectedR10.rollbackAt")
        defaults.set("history_interlock_migration", forKey: "atria.protectedR10.rollbackReason")
        defaults.set("qualification_pending", forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG protected_r10 status=migrated_history_interlock action=clear_contaminated_rollback_preserve_user_data")
    }

    /// A stream can deliver valid R10 records yet still destabilize the physical
    /// BLE link. If the latest connection repeatedly ended within seconds and a
    /// motion frame was present immediately before that edge, isolate the next
    /// launch onto a fresh HR + standard-battery CoreBluetooth owner. This is a
    /// continuity fuse, not a permanent capability decision: an explicitly
    /// armed calibration run clears it so the transport can be tested again.
    private func isolateRecentProtectedR10DisconnectStormIfNeeded(now: Date = Date()) {
        let defaults = UserDefaults.standard
        let lastDisconnectAt = defaults.double(forKey: "atria.ble.lastDisconnectDiagnosticAt")
        let connectedDuration = defaults.double(forKey: "atria.ble.lastConnectedDuration")
        let lastR10At = defaults.double(forKey: RadioDefaults.passiveR10LastValidAt)
        guard lastDisconnectAt > 0,
              lastR10At > 0,
              Self.shouldIsolateRecentProtectedR10DisconnectStorm(
                alreadySuppressed: defaults.bool(forKey: Self.protectedR10StreamSuppressedKey),
                consecutiveEarlyDisconnects: defaults.integer(
                    forKey: Self.protectedR10EarlyDisconnectsKey
                ),
                lastDisconnectAge: now.timeIntervalSince1970 - lastDisconnectAt,
                connectedDuration: connectedDuration,
                lastR10Age: now.timeIntervalSince1970 - lastR10At
              ) else { return }
        if strapStepCalibrationCaptureUntil != nil {
            AtriaStrapCalibrationArchive.shared.flush()
            defaults.removeObject(
                forKey: AtriaStrapCalibrationArchive.captureUntilDefaultsKey
            )
            strapStepCalibrationCaptureUntil = nil
            stepCalibrationCaptureArmedAt = nil
            stepCalibrationMotionStreamReady = false
        }
        defaults.set(true, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(false, forKey: Self.protectedR10PassiveReprobePendingKey)
        defaults.set(now.timeIntervalSince1970,
                     forKey: Self.protectedR10DisconnectStormAtKey)
        defaults.set("short_links_with_fresh_r10",
                     forKey: Self.protectedR10DisconnectStormReasonKey)
        defaults.set("isolated_hr_battery_after_disconnect_storm",
                     forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG protected_r10 status=stream_isolated reason=disconnect_storm connected_s=%.1f r10_before_disconnect_s=%.1f action=fresh_pure_hr_owner_next_launch",
                      connectedDuration,
                      abs(lastDisconnectAt - lastR10At))
    }

    /// The retired 0x1A experiment could leave 2A37 alive while R10 stayed
    /// silent. One clean link rebuild is required to restore the strap's live
    /// motion mode; persist the intent so it happens once across app upgrades.
    private func migrateFailedProprietaryBatteryRefreshIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: BatteryDefaults.proprietaryRefreshRecoveryMigrated) else { return }
        defaults.set(true, forKey: BatteryDefaults.proprietaryRefreshRecoveryMigrated)
        guard defaults.string(forKey: BatteryDefaults.proprietaryRefreshLastFailure) != nil else { return }
        defaults.set(true, forKey: BatteryDefaults.proprietaryRefreshRecoveryPending)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.set("battery_probe_recovery_pending", forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=recovery_migrated action=one_clean_link_rebuild")
    }

    @discardableResult
    private func beginRetiredBatteryProbeRecoveryIfNeeded(_ peripheral: CBPeripheral) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: BatteryDefaults.proprietaryRefreshRecoveryPending) else { return false }
        defaults.set(false, forKey: BatteryDefaults.proprietaryRefreshRecoveryPending)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.removeObject(forKey: "atria.protectedR10.rollbackAt")
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.set("battery_probe_recovery_rebuild", forKey: RadioDefaults.passiveR10Status)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: "atria.battery.proprietaryRefresh.recoveryStartedAt")
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=recovery_start action=cancel_once_then_reconnect_known")
        requestFreshScanReconnect(peripheral: peripheral,
                                  reason: "retired_battery_probe_recovery",
                                  intent: .rebuildConnection)
        return true
    }

    private func migrateStableR10TransportDefaultIfNeeded(arguments: [String]) {
        let defaults = UserDefaults.standard
        guard !arguments.contains("--atria-full-protocol-mode") else { return }
        guard defaults.bool(forKey: CaptureDefaults.configured) else { return }
        let migrationWasRecorded = defaults.bool(forKey: CaptureDefaults.stableR10TransportMigrated)
        let userSelectedRadioMode = defaults.bool(forKey: RadioDefaults.standardHROnlyUserSelected)
        guard Self.shouldMigrateAutomaticModeToProtectedR10(
            migrationWasRecorded: migrationWasRecorded,
            userSelectedRadioMode: userSelectedRadioMode
        ) else { return }
        defaults.set(true, forKey: CaptureDefaults.stableR10TransportMigrated)
        defaults.set(true, forKey: RadioDefaults.standardHROnly)
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        forceFreshScanOnRestore = true
        recordRadioMode("protected_r10_minimal", reason: "stable_hr_r10_migration")
        AtriaDebugLog("ATRIADBG radio_mode status=migrated mode=protected_r10_minimal reason=physical_ab_stability strap_steps_background=1 phone_step_fallback=0")
    }

    /// Migrate only automatic/default radio state. A user who explicitly chose
    /// the diagnostic full profile or the stable minimal profile keeps it.
    nonisolated static func shouldMigrateAutomaticModeToProtectedR10(
        migrationWasRecorded: Bool,
        userSelectedRadioMode: Bool
    ) -> Bool {
        !migrationWasRecorded && !userSelectedRadioMode
    }

    /// Normal wear defaults to the physically verified minimal HR + R10 path.
    /// Despite the legacy storage name, this mode retains strap-native motion;
    /// only an explicit user selection may persist the broader profile.
    nonisolated static func shouldUseStandardHROnlyAtNormalLaunch(
        userSelectedBatterySaver: Bool,
        persistedStandardHROnly: Bool
    ) -> Bool {
        userSelectedBatterySaver ? persistedStandardHROnly : true
    }

    /// A temporary diagnostic full-protocol override must restore the exact
    /// prior profile. The automatic prior is now the stable R10-capable mode,
    /// so user ownership no longer changes the restoration result.
    nonisolated static func standardHROnlyModeAfterFullProtocolOverride(
        modeBeforeOverride: Bool,
        userSelectedBatterySaver: Bool
    ) -> Bool {
        _ = userSelectedBatterySaver
        return modeBeforeOverride
    }

    func setStandardHROnlyEnabled(_ enabled: Bool) {
        UserDefaults.standard.set(true, forKey: CaptureDefaults.configured)
        UserDefaults.standard.set(true, forKey: RadioDefaults.standardHROnlyUserSelected)
        applyStandardHROnly(enabled: enabled, persist: true, reconnect: true, reason: "user_toggle")
    }

    /// Enables the bounded raw-motion archive immediately for an in-app step
    /// calibration run. Normally the production protected connection already
    /// carries R10 on stream 5. If the disconnect-storm fuse isolated motion,
    /// explicit calibration clears that fuse and rediscovers only the minimal
    /// R10 service; it still never reads battery or starts offline history.
    func armStepCalibrationCapture(until requestedUntil: Date = Date().addingTimeInterval(
        AtriaStrapCalibrationArchive.defaultCaptureDuration
    )) {
        let now = Date()
        let captureUntil = max(requestedUntil, now.addingTimeInterval(60))
        UserDefaults.standard.set(
            captureUntil.timeIntervalSince1970,
            forKey: AtriaStrapCalibrationArchive.captureUntilDefaultsKey
        )
        strapStepCalibrationCaptureUntil = captureUntil
        stepCalibrationCaptureArmedAt = now
        stepCalibrationMotionStreamReady = false
        // Guided calibration owns the dense motion stream exactly like an
        // explicit workout, so the card never depends on a parallel workout
        // being started by hand (2026-07-16 02:35 IST failure mode).
        workoutMotionCalibrationHoldUntil = captureUntil
        beginWorkoutMotionLease(startedAt: now, reason: "step_calibration_arm")
        if protectedR10StreamSuppressed {
            UserDefaults.standard.set(false,
                                      forKey: Self.protectedR10StreamSuppressedKey)
            UserDefaults.standard.set("explicit_calibration_reprobe",
                                      forKey: RadioDefaults.passiveR10Status)
            if let peripheral, peripheral.state == .connected {
                peripheral.discoverServices([Self.UUIDs.strapService])
            }
        }

        // Calibration is an explicit foreground operation and cannot begin
        // honestly without a new CRC-valid R10 frame. A cached active CCCD can
        // leave HR live while motion stays silent indefinitely; after a short
        // passive grace, rebuild that one connection exactly once. This does
        // not read battery, start history sync, or advance the 0/6 sequence.
        stepCalibrationMotionPreparationTask?.cancel()
        stepCalibrationMotionPreparationTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(4))
            guard let self, !Task.isCancelled else { return }
            self.stepCalibrationMotionPreparationTask = nil
            let checkAt = Date()
            guard Self.stepCalibrationMotionPreparationNeedsReconnect(
                armedAt: self.stepCalibrationCaptureArmedAt,
                motionStreamReady: self.stepCalibrationMotionStreamReady,
                lastR10FrameAt: self.lastR10MotionFrameAt,
                connected: self.status == .connected
                    && self.peripheral?.state == .connected,
                now: checkAt
            ), let peripheral = self.peripheral else { return }
            self.requestFreshScanReconnect(
                peripheral: peripheral,
                reason: "step_calibration_stale_r10",
                intent: .rebuildConnection
            )
            AtriaDebugLog("ATRIADBG strap_step_calibration status=motion_recovery_requested reason=no_fresh_r10_after_arm action=one_clean_link_rebuild")
        }

        AtriaDebugLog(
            "ATRIADBG strap_step_calibration status=armed_runtime until_utc=%@ source=developer_sequence transport=minimal_protected_r10 battery_reads=0 offline_sync=0 commands=0",
            ISO8601DateFormatter().string(from: captureUntil)
        )
    }

    /// Ends passive archival without touching the live transport.
    func finishStepCalibrationCapture(reason: String = "sequence_complete") {
        stepCalibrationMotionPreparationTask?.cancel()
        stepCalibrationMotionPreparationTask = nil
        AtriaStrapCalibrationArchive.shared.flush()
        UserDefaults.standard.removeObject(
            forKey: AtriaStrapCalibrationArchive.captureUntilDefaultsKey
        )
        strapStepCalibrationCaptureUntil = nil
        stepCalibrationCaptureArmedAt = nil
        stepCalibrationMotionStreamReady = false
        workoutMotionCalibrationHoldUntil = nil
        if !AtriaPendingWorkoutIntent.isActiveForBLEContinuity() {
            // Only calibration held the lease; a concurrently running explicit
            // workout keeps its own ownership untouched.
            endWorkoutMotionLease(reason: "step_calibration_\(reason)")
        }

        AtriaDebugLog(
            "ATRIADBG strap_step_calibration status=disarmed reason=%@ transport_unchanged=1 standard_hr_only=%d long_wear_unchanged=1",
            reason,
            standardHROnlyMode ? 1 : 0
        )
    }

    nonisolated static func stepCalibrationMotionPreparationNeedsReconnect(
        armedAt: Date?,
        motionStreamReady: Bool,
        lastR10FrameAt: Date?,
        connected: Bool,
        now: Date,
        passiveGrace: TimeInterval = 4
    ) -> Bool {
        guard connected,
              !motionStreamReady,
              let armedAt,
              now >= armedAt,
              now.timeIntervalSince(armedAt) >= passiveGrace else { return false }
        return lastR10FrameAt.map { $0 < armedAt } ?? true
    }

    func setLongWearModeEnabled(_ enabled: Bool, rest: Int, maxHR: Int) {
        UserDefaults.standard.set(true, forKey: CaptureDefaults.configured)
        UserDefaults.standard.set(true, forKey: LongWearDefaults.userSelected)
        UserDefaults.standard.set(enabled, forKey: LongWearDefaults.enabled)
        longWearModeEnabled = enabled
        updateSessionPointCacheMode()
        if enabled {
            let standardOnly = Self.shouldUseStandardHROnlyInProtectedBackground(
                userSelectedBatterySaver: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnlyUserSelected),
                persistedStandardHROnly: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnly)
            )
            applyStandardHROnly(enabled: standardOnly, persist: false, reconnect: true, reason: "long_wear")
            startLongWearMode(rest: rest, maxHR: maxHR, reason: "user_toggle")
        } else {
            stopLongWearMode(reason: "user_toggle")
        }
    }

    func setCollectionProfile(_ profile: CollectionProfile, rest: Int, maxHR: Int) {
        guard profile != collectionProfile else { return }
        UserDefaults.standard.set(profile.rawValue, forKey: CollectionProfileDefaults.profile)
        collectionProfile = profile
        AtriaDebugLog("ATRIADBG collection_profile status=selected profile=%@ cadence_multiplier=%.2f stale_timeout_multiplier=%.2f",
                      profile.rawValue,
                      profile.cadenceMultiplier,
                      profile.staleTimeoutMultiplier)
        guard longWearModeEnabled else { return }
        startLongWearMode(rest: rest, maxHR: maxHR, reason: "collection_profile")
    }

    func applyPersistentLongWearModeIfNeeded(rest: Int, maxHR: Int) {
        guard UserDefaults.standard.bool(forKey: LongWearDefaults.enabled) else {
            longWearModeEnabled = false
            updateSessionPointCacheMode()
            return
        }
        longWearModeEnabled = true
        updateSessionPointCacheMode()
        guard !foregroundInteractiveMode else {
            return
        }
        let standardOnly = Self.shouldUseStandardHROnlyInProtectedBackground(
            userSelectedBatterySaver: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnlyUserSelected),
            persistedStandardHROnly: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnly)
        )
        applyStandardHROnly(enabled: standardOnly, persist: false, reconnect: false, reason: "long_wear_persisted")
        if !standardOnly {
            rediscoverFullProtocolServicesIfConnected(reason: "long_wear_persisted_strap_steps")
        }
        startLongWearMode(rest: rest, maxHR: maxHR, reason: "persisted")
    }

    private func startLongWearMode(rest: Int, maxHR: Int, reason: String) {
        let defaults = UserDefaults.standard
        let checkpointSeconds = defaults.object(forKey: LongWearDefaults.checkpointInterval) as? Double ?? 60
        let diagnosticSeconds = defaults.object(forKey: LongWearDefaults.diagnosticInterval) as? Double ?? 15
        let autoSaveSeconds = defaults.object(forKey: LongWearDefaults.workoutAutoSaveInterval) as? Double ?? 15
        let noDataTimeout = defaults.object(forKey: LongWearDefaults.noDataTimeout) as? Double ?? 75
        let noDataCheckInterval = defaults.object(forKey: LongWearDefaults.noDataCheckInterval) as? Double ?? 15
        let acceptedHRTimeout = defaults.object(forKey: LongWearDefaults.acceptedHRTimeout) as? Double ?? 45
        let profile = collectionProfile
        let cadenceMultiplier = profile.cadenceMultiplier
        let staleTimeoutMultiplier = profile.staleTimeoutMultiplier
        let noDataWatchdogTimeout = max(60, min(noDataTimeout * staleTimeoutMultiplier, 600))
        let acceptedHRWatchdogTimeout = max(35, min(acceptedHRTimeout * staleTimeoutMultiplier, 180))
        let hrContinuityTimeout = Self.hrContinuityWatchdogTimeout(
            acceptedHRTimeout: acceptedHRWatchdogTimeout
        )
        let label = defaults.string(forKey: LongWearDefaults.label) ?? "All-day wear"
        captureLabel = label
        restoreActiveSessionJournalIfNeeded(reason: reason)
        let config = LongWearSupervisorConfig(
            label: label,
            rest: rest,
            maxHR: maxHR,
            checkpointInterval: max(10, min(checkpointSeconds * cadenceMultiplier, 3_600)),
            diagnosticInterval: max(5, min(diagnosticSeconds * cadenceMultiplier, 300)),
            autoSaveInterval: max(5, min(autoSaveSeconds * cadenceMultiplier, 300)),
            noDataTimeout: noDataWatchdogTimeout,
            noDataCheckInterval: max(5, min(noDataCheckInterval * cadenceMultiplier, 300)),
            hrContinuityTimeout: hrContinuityTimeout,
            rrPresenceTimeout: max(20, min(acceptedHRWatchdogTimeout * 2, 120)),
            acceptedHRTimeout: acceptedHRWatchdogTimeout
        )
        cacheDutyCycleRestHR(rest)
        scheduleLongWearSupervisor(config: config)
        ensureForegroundKeepaliveWatchdog(reason: reason)
        AtriaDebugLog("ATRIADBG long_wear_mode enabled=1 reason=%@ radio_mode=%@ supervisor=1 collection_profile=%@ cadence_multiplier=%.2f stale_timeout_multiplier=%.2f checkpoint_interval_s=%.0f live_workout_interval_s=%.0f workout_autosave_interval_s=%.0f no_data_timeout_s=%.0f no_data_check_interval_s=%.0f hr_continuity_timeout_s=%.0f supervisor_base_tick_s=%.0f accepted_hr_timeout_s=%.0f disconnect_reconnect_policy=staged_read_reassert_then_fresh_scan label=%@ rest_hr=%d max_hr=%d",
              reason,
              standardHROnlyMode ? "standard_hr_only" : "full_protocol",
              profile.rawValue,
              cadenceMultiplier,
              staleTimeoutMultiplier,
              config.checkpointInterval,
              config.diagnosticInterval,
              config.autoSaveInterval,
              config.noDataTimeout,
              config.noDataCheckInterval,
              config.hrContinuityTimeout,
              config.baseTickInterval,
              config.acceptedHRTimeout,
              label,
              rest,
              maxHR)
    }

    /// WHOOP 4's accepted 2A37 cadence is not guaranteed to be one second.
    /// Physical long-wear evidence showed healthy CRC-valid R10 alongside
    /// ordinary 8–14 second HR intervals; the former 6-second timeout therefore
    /// reset notifications continuously and induced a reconnect feedback loop.
    /// Keep continuity repair meaningfully earlier than the accepted-HR failure
    /// gate, but never earlier than a plausible healthy strap interval.
    nonisolated static func hrContinuityWatchdogTimeout(
        acceptedHRTimeout: TimeInterval
    ) -> TimeInterval {
        max(20, min(acceptedHRTimeout * (2.0 / 3.0), 45))
    }

    private func stopLongWearMode(reason: String) {
        stopForegroundKeepaliveWatchdog(reason: reason)
        pauseLongWearAutomation(reason: reason)
        UserDefaults.standard.set(false, forKey: CheckpointDefaults.armed)
        UserDefaults.standard.set("long_wear_stopped", forKey: CheckpointDefaults.lastStatus)
        AtriaDebugLog("ATRIADBG long_wear_mode enabled=0 reason=%@ checkpoint_cancelled=1 live_workout_cancelled=1 workout_autosave_cancelled=1 no_data_watchdog_cancelled=1 hr_continuity_watchdog_cancelled=1 accepted_hr_watchdog_cancelled=1",
              reason)
    }

    private func pauseLongWearAutomation(reason: String) {
        delayedSessionSaveTask?.cancel()
        liveWorkoutDiagnosticTask?.cancel()
        workoutAutoSaveTask?.cancel()
        longWearSupervisorTask?.cancel()
        activeLongWearSupervisorConfig = nil
        noDataWatchdogTask?.cancel()
        debugNoDataWatchdogTask?.cancel()
        hrContinuityWatchdogTask?.cancel()
        rrPresenceWatchdogTask?.cancel()
        debugHRContinuityWatchdogTask?.cancel()
        acceptedHRWatchdogTask?.cancel()
        debugAcceptedHRWatchdogTask?.cancel()
        longWearSupervisorTask = nil
        UserDefaults.standard.set(false, forKey: CheckpointDefaults.armed)
        AtriaDebugLog("ATRIADBG long_wear_mode paused=1 reason=%@ foreground_interactive=%d",
              reason,
              foregroundInteractiveMode ? 1 : 0)
    }

    private func elevateLongWearRadioForInteractiveForegroundIfNeeded(reason: String) {
        guard longWearModeEnabled else { return }
        guard standardHROnlyMode else { return }
        guard !offlineHistoricalSyncInProgress else { return }
        // Protected standard mode now carries 2A37 plus the physically proven
        // minimal stream5/TX/3F01 motion path. Foregrounding must not expand it
        // into legacy full protocol (extra CCCDs/reads/commands), which would
        // undo the isolation that made simultaneous HR and R10 stable.
        reassertHeartRateNotificationsIfConnected(reason: "\(reason)_protected_r10")
        sendProtectedR10ActivationIfReady()
        AtriaDebugLog("ATRIADBG radio_mode mode=standard_hr_only reason=%@ action=preserve_protected_r10_no_full_protocol_escalation",
                      reason)
    }

    private func isRRProtectedSleepWindow(now: Date) -> Bool {
        let hour = Calendar.current.component(.hour, from: now)
        return hour >= 21 || hour < 11
    }

    private func restoreProtectedLongWearRadioIfNeeded(reason: String) {
        guard longWearModeEnabled else { return }
        guard !offlineHistoricalSyncInProgress else { return }
        let standardOnly = Self.shouldUseStandardHROnlyInProtectedBackground(
            userSelectedBatterySaver: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnlyUserSelected),
            persistedStandardHROnly: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnly)
        )
        // Already in the desired mode: leave the active proprietary stream and
        // HR subscription untouched. Rediscovery resets realtimeArmed and would
        // create an avoidable background gap.
        guard standardHROnlyMode != standardOnly else { return }
        applyStandardHROnly(enabled: standardOnly,
                            persist: false,
                            reconnect: standardOnly,
                            reason: reason)
        if !standardOnly {
            rediscoverFullProtocolServicesIfConnected(reason: "\(reason)_strap_steps")
        }
    }

    func handleInteractiveForeground(rest: Int, maxHR: Int) {
        let now = Date()
        // A scene-active callback is not a workout intent. WHOOP pages can be
        // silent for several minutes between their first row and the remaining
        // burst, so cancelling here made an ordinary lock/unlock or screen wake
        // perpetually restart the same unacknowledged page. A persisted manual
        // workout still preempts through beginWorkoutMotionLease; foregrounding
        // alone must leave the loss-safe history owner intact.
        if let lastInteractiveForegroundHandlingAt,
           now.timeIntervalSince(lastInteractiveForegroundHandlingAt) < 1 {
            // UIKit and SwiftUI can report the same foreground transition.
            // Keep the already-live link healthy without repeating journal
            // restore, supervisor replacement, or service rediscovery.
            ensureForegroundKeepaliveWatchdog(reason: "scene_active_coalesced")
            reassertHeartRateNotificationsIfConnected(reason: "scene_active_coalesced")
            reassertR10NotificationIfConnected(reason: "scene_active_coalesced")
            return
        }
        lastInteractiveForegroundHandlingAt = now
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        if Self.shouldUseFastWorkoutForegroundResume(
            activeExplicitWorkout: activeExplicitWorkout,
            hasLiveSession: !session.isEmpty,
            linkConnected: status == .connected && peripheral?.state == .connected
        ) {
            foregroundInteractiveMode = true
            ensureForegroundKeepaliveWatchdog(reason: "scene_active_workout_fast")
            reassertHeartRateNotificationsIfConnected(reason: "scene_active_workout_fast")
            reassertR10NotificationIfConnected(reason: "scene_active_workout_fast")
            updateDutyCycleState(reason: "scene_active_workout_fast", now: now)
            AtriaDebugLog("ATRIADBG foreground_resume path=workout_fast samples=%d connected=1 action=preserve_live_pipeline",
                          session.count)
            return
        }
        scheduleStaleArmedRangeLossBackfillReconciliation(reason: "scene_active")
        resumeForegroundScanIfNeeded(reason: "scene_active")
        restoreActiveSessionJournalIfNeeded(reason: "scene_active_foreground")
        // Arm the silent-link safety net whenever we are foreground + long-wear,
        // including a fresh foreground launch where foregroundInteractiveMode is
        // already true (the all-night, screen-on scenario). Idempotent: only
        // starts when not already running.
        ensureForegroundKeepaliveWatchdog(reason: "scene_active")
        if longWearModeEnabled {
            startLongWearMode(rest: rest, maxHR: maxHR, reason: "scene_active_foreground")
        }
        reassertHeartRateNotificationsIfConnected(reason: "scene_active")
        reassertR10NotificationIfConnected(reason: "scene_active")
        elevateLongWearRadioForInteractiveForegroundIfNeeded(reason: "scene_active_interactive")
        if foregroundInteractiveMode {
            return
        }
        foregroundInteractiveMode = true
        guard longWearModeEnabled else {
            return
        }
        AtriaDebugLog("ATRIADBG long_wear_mode foreground_interactive=1 action=keep_supervisor_and_keepalive_armed rest_hr=%d max_hr=%d",
              rest,
              maxHR)
    }

    private func reassertHeartRateNotificationsIfConnected(reason: String) {
        if motionHandshakeDiagnostic != nil {
            recordMotionHandshakeEvidence(event: "foreground_hr_reassert_blocked", detail: reason)
            return
        }
        guard status == .connected, let peripheral else { return }
        if dutyCycleState == .sparseSentinel {
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=skipped reason=%@ detail=duty_cycle_sparse", reason)
            return
        }
        guard peripheral.state == .connected else {
            recomputeConnectionStatus(reason: "foreground_notify_reassert_peripheral_not_connected")
            if !reconnectToSavedPeripheralIfPossible(reason: "\(reason)_notify_reassert_peripheral_state_\(peripheral.state.rawValue)") {
                startScan(reason: "\(reason)_notify_reassert_peripheral_state_\(peripheral.state.rawValue)")
            }
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=peripheral_not_connected reason=%@ peripheral_state=%d action=reconnect_known_strap",
                          reason,
                          peripheral.state.rawValue)
            return
        }
        if let characteristic = heartRateCharacteristic {
            // A healthy CoreBluetooth subscription survives ordinary app
            // switches. Toggling it off/on on every foreground edge discards
            // in-flight 2A37 samples and was visible as a short workout gap
            // after returning to Atria. Repair only a stale or non-notifying
            // subscription; the keepalive watchdog remains the deeper safety
            // net for a link that goes silent later.
            if Self.shouldPreserveHeartRateNotificationOnForeground(
                isNotifying: characteristic.isNotifying,
                lastRawNotificationAt: lastRawHRNotificationAt,
                now: Date()
            ) {
                AtriaDebugLog("ATRIADBG ble_notify_reassert status=preserved reason=%@ source=foreground_return action=keep_healthy_subscription",
                              reason)
            } else {
                resetHeartRateNotifyIfNeeded(peripheral: peripheral,
                                             characteristic: characteristic,
                                             reason: reason)
            }
            if characteristic.properties.contains(.read) {
                peripheral.readValue(for: characteristic)
            }
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=requested reason=%@ source=foreground_return action=keep_connection",
                          reason)
            return
        }
        guard peripheral.state == .connected else { return }
        peripheral.discoverServices([UUIDs.heartRateService])
        AtriaDebugLog("ATRIADBG ble_notify_reassert status=discover_services reason=%@ source=foreground_return action=keep_connection",
                      reason)
    }

    /// R10 can stop while 2A37 HR remains healthy. Preserve an active stream5
    /// subscription, but repair a genuinely inactive CCCD without reconnecting
    /// or toggling the healthy HR notification.
    private func reassertR10NotificationIfConnected(reason: String,
                                                     now: Date = Date()) {
        guard motionHandshakeDiagnostic == nil,
              r10TransportIsExpected,
              status == .connected,
              let peripheral,
              peripheral.state == .connected else { return }

        if standardHROnlyMode {
            if strapStream5NotifyConfirmed {
                AtriaDebugLog("ATRIADBG r10_notify_repair status=preserved reason=%@ action=keep_initial_profile_cccd",
                              reason)
            } else {
                // The liveness/foreground path can race the first CoreBluetooth
                // notification-state callback. It may observe `false` while the
                // one allowed initial subscribe is still in flight, so it must
                // never decide fallback. The callback itself owns confirmed
                // error/inactive fallback; restored-cache discovery owns the
                // no-callback case.
                AtriaDebugLog("ATRIADBG r10_notify_repair status=awaiting_initial_profile reason=%@ action=no_mid_link_cccd_or_fallback",
                              reason)
            }
            // Physical V4 evidence showed that enabling or disabling stream 5
            // on an established protected link causes rapid disconnects. Only
            // initial characteristic discovery may establish this CCCD.
            return
        }

        guard let strapService = peripheral.services?.first(where: {
            $0.uuid == Self.UUIDs.strapService
        }) else {
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG r10_notify_repair status=discover_service reason=%@ action=no_reconnect",
                          reason)
            return
        }
        guard let characteristics = strapService.characteristics else {
            peripheral.discoverCharacteristics([Self.UUIDs.strapStream5, Self.UUIDs.strapTX],
                                               for: strapService)
            AtriaDebugLog("ATRIADBG r10_notify_repair status=discover_characteristics reason=%@ action=no_reconnect",
                          reason)
            return
        }
        guard let stream5 = characteristics.first(where: {
            $0.uuid == Self.UUIDs.strapStream5
        }), stream5.properties.contains(.notify) else {
            peripheral.discoverCharacteristics([Self.UUIDs.strapStream5, Self.UUIDs.strapTX],
                                               for: strapService)
            return
        }
        if stream5.isNotifying {
            strapStream5NotifyConfirmed = true
            ensureR10LivenessWatchdog(reason: "\(reason)_stream5_active")
            AtriaDebugLog("ATRIADBG r10_notify_repair status=preserved reason=%@ action=keep_active_cccd",
                          reason)
            return
        }
        guard Self.shouldRepairR10Notification(
            expected: r10TransportIsExpected,
            connected: true,
            isNotifying: stream5.isNotifying,
            lastRepairAt: lastR10NotifyRepairAt,
            now: now
        ) else { return }
        lastR10NotifyRepairAt = now
        strapStream5NotifyConfirmed = false
        peripheral.setNotifyValue(true, for: stream5)
        AtriaDebugLog("ATRIADBG r10_notify_repair status=requested reason=%@ action=enable_stream5_no_reconnect",
                      reason)
    }

    /// A healthy active subscription survives foreground transitions untouched.
    /// Inactive enables are coalesced by `heartRateNotificationEnableGate`.
    nonisolated static let foregroundHealthyNotificationWindow: TimeInterval = 12

    nonisolated static func shouldPreserveHeartRateNotificationOnForeground(
        isNotifying: Bool,
        lastRawNotificationAt: Date?,
        now: Date,
        healthyWindow: TimeInterval = foregroundHealthyNotificationWindow
    ) -> Bool {
        guard isNotifying, let lastRawNotificationAt else { return false }
        let age = now.timeIntervalSince(lastRawNotificationAt)
        return age >= 0 && age <= healthyWindow
    }

    private func beginStalledStreamRepair(source: String, now: Date = Date()) -> Bool {
        guard Self.shouldBeginStalledStreamRepair(lastRepairAt: lastStalledStreamRepairAt,
                                                  now: now) else {
            let remaining = max(0, Self.stalledStreamRepairCooldown
                - now.timeIntervalSince(lastStalledStreamRepairAt ?? now))
            AtriaDebugLog("ATRIADBG stalled_stream_repair status=cooldown source=%@ remaining_s=%.1f action=wait_for_data",
                          source,
                          remaining)
            return false
        }
        lastStalledStreamRepairAt = now
        AtriaDebugLog("ATRIADBG stalled_stream_repair status=started source=%@ cooldown_s=%.1f",
                      source,
                      Self.stalledStreamRepairCooldown)
        return true
    }

    @discardableResult
    private func requestHeartRateNotificationEnableIfNeeded(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        reason: String,
        now: Date = Date()
    ) -> HeartRateNotificationEnableDisposition {
        let supportsNotifications = characteristic.properties.contains(.notify)
            || characteristic.properties.contains(.indicate)
        let disposition = heartRateNotificationEnableGate.disposition(
            now: now,
            peripheralID: peripheral.identifier,
            peripheralConnected: peripheral.state == .connected,
            supportsNotifications: supportsNotifications,
            isNotifying: characteristic.isNotifying
        )
        if disposition == .request {
            peripheral.setNotifyValue(true, for: characteristic)
        }
        AtriaDebugLog("ATRIADBG ble_notify_enable status=%@ reason=%@ notifying=%d peripheral_state=%d",
                      String(describing: disposition),
                      reason,
                      characteristic.isNotifying ? 1 : 0,
                      peripheral.state.rawValue)
        return disposition
    }

    private func resetHeartRateNotifyIfNeeded(peripheral: CBPeripheral,
                                              characteristic: CBCharacteristic,
                                              reason: String) {
        if characteristic.isNotifying {
            if characteristic.properties.contains(.read) {
                peripheral.readValue(for: characteristic)
            }
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=preserved reason=%@ action=read_or_observe_active",
                          reason)
            return
        }
        _ = requestHeartRateNotificationEnableIfNeeded(
            peripheral: peripheral,
            characteristic: characteristic,
            reason: reason
        )
    }

    // MARK: - Duty cycle (daytime power saver)

    @Published private(set) var dutyCycleState: DutyCycleState = .fullCapture
    /// Escalation latch: full-rate capture until this instant. Extended while HR
    /// stays over rest+10; a workout therefore keeps full coverage end-to-end.
    private var dutyCycleEscalatedUntil: Date?
    /// Rest baseline cached from the params the app already passes in.
    private var dutyCycleRestHR: Int = 60
    private var lastSparsePollAt: Date?
    static let dutyCycleSparsePollInterval: TimeInterval = 180
    static let dutyCycleEscalationOverRest = 15
    static let dutyCycleSustainOverRest = 10
    static let dutyCycleEscalationHold: TimeInterval = 10 * 60

    var dutyCycleEnabled: Bool {
        UserDefaults.standard.bool(forKey: DutyCycleDefaults.enabled)
            || ProcessInfo.processInfo.arguments.contains("--atria-enable-duty-cycle")
    }

    func cacheDutyCycleRestHR(_ rest: Int) {
        if rest > 0 { dutyCycleRestHR = rest }
    }

    /// Learned sleep window in minutes-after-midnight, written by the session
    /// store from confirmed sleeps; falls back to 23:30-10:30.
    private func dutyCycleSleepWindow(defaults: UserDefaults = .standard) -> (start: Int, end: Int) {
        let start = defaults.integer(forKey: DutyCycleDefaults.sleepWindowStartMin)
        let end = defaults.integer(forKey: DutyCycleDefaults.sleepWindowEndMin)
        guard start > 0 || end > 0 else { return (23 * 60 + 30, 10 * 60 + 30) }
        return (min(max(start, 0), 1439), min(max(end, 0), 1439))
    }

    private func isInsideDutyCycleSleepWindow(now: Date = Date(), calendar: Calendar = .current) -> Bool {
        let window = dutyCycleSleepWindow()
        let components = calendar.dateComponents([.hour, .minute], from: now)
        let minutes = (components.hour ?? 0) * 60 + (components.minute ?? 0)
        if window.start <= window.end {
            return minutes >= window.start && minutes <= window.end
        }
        // Window crosses midnight (the normal case: ~23:30 -> ~10:30).
        return minutes >= window.start || minutes <= window.end
    }

    /// Called on accepted HR (notify or sparse poll): elevated HR escalates to
    /// full capture instantly and keeps extending the latch while elevated.
    func noteDutyCycleHeartRate(_ bpm: Int, now: Date = Date()) {
        guard dutyCycleEnabled else { return }
        if bpm >= dutyCycleRestHR + Self.dutyCycleEscalationOverRest {
            let wasEscalated = dutyCycleEscalatedUntil.map { $0 > now } ?? false
            dutyCycleEscalatedUntil = now.addingTimeInterval(Self.dutyCycleEscalationHold)
            if !wasEscalated {
                AtriaDebugLog("ATRIADBG duty_cycle status=escalated reason=hr_over_rest bpm=%d rest=%d",
                              bpm,
                              dutyCycleRestHR)
                updateDutyCycleState(reason: "hr_escalation")
            }
        } else if bpm >= dutyCycleRestHR + Self.dutyCycleSustainOverRest,
                  let until = dutyCycleEscalatedUntil, until > now {
            dutyCycleEscalatedUntil = now.addingTimeInterval(Self.dutyCycleEscalationHold)
        }
    }

    /// Recompute the desired state and apply transitions. Cheap; called from the
    /// keepalive tick, scene changes, and escalation events.
    func updateDutyCycleState(reason: String, now: Date = Date()) {
        let desired: DutyCycleState
        let defaults = UserDefaults.standard
        if !dutyCycleEnabled
            || !longWearModeEnabled
            || isInsideDutyCycleSleepWindow(now: now)
            || foregroundHighFrequencyDisplayMode
            || isRecording
            || defaults.bool(forKey: DutyCycleDefaults.focusFullCapture)
            || (dutyCycleEscalatedUntil.map { $0 > now } ?? false) {
            desired = .fullCapture
        } else {
            desired = .sparseSentinel
        }
        // Publish before applying the CCCD transition. A discovery callback on
        // CoreBluetooth's delegate queue can now honor the current intent
        // synchronously without crossing to MainActor first.
        heartRateCaptureIntent.update(
            continuousCaptureWanted: desired != .sparseSentinel
        )
        if desired == dutyCycleState {
            // Enforcement is idempotent, not edge-triggered: unguarded reasserts
            // (scene flips, reconnect discovery) can silently re-enable notify
            // while the state stays sparse — re-apply notify-off when seen.
            if desired == .sparseSentinel,
               status == .connected, let peripheral, peripheral.state == .connected,
               let characteristic = heartRateCharacteristic,
               characteristic.isNotifying {
                peripheral.setNotifyValue(false, for: characteristic)
                AtriaDebugLog("ATRIADBG duty_cycle action=hr_notify_off reason=reenforce_%@", reason)
            }
            return
        }
        dutyCycleState = desired
        AtriaDebugLog("ATRIADBG duty_cycle state=%@ reason=%@ sleep_window=%d rest=%d",
                      desired.rawValue,
                      reason,
                      isInsideDutyCycleSleepWindow(now: now) ? 1 : 0,
                      dutyCycleRestHR)
        switch desired {
        case .sparseSentinel:
            // Notify OFF on the live HR link. The protected battery percentage
            // subscription is independent and may emit only when the strap has
            // a new standard 2A19 value.
            if status == .connected, let peripheral, peripheral.state == .connected,
               let characteristic = heartRateCharacteristic,
               characteristic.properties.contains(.notify) {
                peripheral.setNotifyValue(false, for: characteristic)
                AtriaDebugLog("ATRIADBG duty_cycle action=hr_notify_off reason=%@", reason)
            }
        case .fullCapture:
            reassertHeartRateNotificationsIfConnected(reason: "duty_cycle_\(reason)")
        }
    }

    func requestStrapStatusRead(reason: String) {
        if recoveredDataProjectionDeferralIsActive {
            guard status == .connected,
                  let peripheral,
                  peripheral.state == .connected,
                  let batteryLevelCharacteristic else {
                AtriaDebugLog("ATRIADBG strap_status_refresh status=deferred reason=%@ detail=history_transport_owned action=no_battery_characteristic_or_discovery",
                              reason)
                return
            }
            let action = Self.historyOwnedBatteryRefreshAction(
                canNotify: batteryLevelCharacteristic.properties.contains(.notify)
                    || batteryLevelCharacteristic.properties.contains(.indicate),
                isNotifying: batteryLevelCharacteristic.isNotifying
            )
            if action == .subscribe {
                UserDefaults.standard.set(Date().timeIntervalSince1970,
                                          forKey: BatteryDefaults.notificationRequestedAt)
                peripheral.setNotifyValue(true, for: batteryLevelCharacteristic)
                AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ detail=history_transport_owned source=2A19_new_subscription no_read=1",
                              reason)
            } else {
                AtriaDebugLog("ATRIADBG strap_status_refresh status=deferred reason=%@ detail=history_transport_owned action=%@ no_read=1 no_discovery=1",
                              reason,
                              action == .awaitNotification ? "await_2A19_notification" : "2A19_unavailable")
            }
            return
        }
        guard motionHandshakeDiagnostic == nil else {
            recordMotionHandshakeEvidence(event: "battery_read_blocked", detail: reason)
            return
        }
        guard status == .connected, let peripheral, peripheral.state == .connected else {
            AtriaDebugLog("ATRIADBG strap_status_read status=skipped reason=%@ detail=not_connected", reason)
            return
        }
        if let batteryLevelCharacteristic {
            let action = Self.standardBatteryRefreshAction(
                canRead: batteryLevelCharacteristic.properties.contains(.read),
                canNotify: batteryLevelCharacteristic.properties.contains(.notify)
                    || batteryLevelCharacteristic.properties.contains(.indicate),
                isNotifying: batteryLevelCharacteristic.isNotifying
            )
            switch action {
            case .read:
                lastBatteryReadRequestedAt = Date()
                peripheral.readValue(for: batteryLevelCharacteristic)
                AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ source=2A19_read",
                              reason)
            case .subscribe:
                lastBatteryReadRequestedAt = Date()
                UserDefaults.standard.set(Date().timeIntervalSince1970,
                                          forKey: BatteryDefaults.notificationRequestedAt)
                peripheral.setNotifyValue(true, for: batteryLevelCharacteristic)
                AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ source=2A19_new_subscription",
                              reason)
            case .awaitNotification:
                // This timestamp only throttles refresh attempts; it is never
                // used as battery-value freshness evidence.
                let now = Date()
                lastBatteryReadRequestedAt = now
                let defaults = UserDefaults.standard
                switch Self.existingBatteryNotificationAction(
                    currentEpochConfirmed: batteryNotificationTransportIsActive(
                        now: now,
                        defaults: defaults
                    ),
                    recoveryInFlight: batteryNotificationRecoveryTask != nil
                        || pendingNotifyReenableUUIDs.contains(batteryLevelCharacteristic.uuid)
                ) {
                case .awaitCurrentEpoch:
                    promoteReconnectBatteryBaselineIfSafe(
                        now: now,
                        heartRateReceivedAt: lastRawHRNotificationAt,
                        validatedR10ReceivedAt: lastR10MotionFrameAt,
                        reason: "2A19_existing_notify_active"
                    )
                    AtriaDebugLog("ATRIADBG strap_status_refresh status=awaiting reason=%@ source=2A19_existing_subscription",
                                  reason)
                case .refreshUnconfirmedEpoch:
                    // `didConnect` deliberately invalidates the previous link's
                    // notification proof. If CoreBluetooth then hands discovery
                    // a cached `isNotifying == true` characteristic, establish a
                    // real epoch with the same bounded off/on recovery used for
                    // callback failures. Never issue an explicit 2A19 read.
                    batteryNotificationEpochHadRejectedCallback = true
                    if defaults.string(forKey: BatteryDefaults.notificationLastError) == nil {
                        defaults.set("cached_notify_unconfirmed",
                                     forKey: BatteryDefaults.notificationLastError)
                    }
                    defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
                    defaults.set(now.timeIntervalSince1970,
                                 forKey: BatteryDefaults.notificationRequestedAt)
                    revokeBatteryNotificationLease(
                        reason: "2A19_cached_notify_unconfirmed",
                        now: now
                    )
                    pendingNotifyReenableUUIDs.insert(batteryLevelCharacteristic.uuid)
                    peripheral.setNotifyValue(false, for: batteryLevelCharacteristic)
                    armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: batteryLevelCharacteristic,
                        reason: "cached_notify_unconfirmed_disable"
                    )
                    AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ source=2A19_cached_subscription_epoch_refresh",
                                  reason)
                case .awaitRecovery:
                    AtriaDebugLog("ATRIADBG strap_status_refresh status=awaiting reason=%@ source=2A19_subscription_recovery",
                                  reason)
                }
            case .unavailable:
                lastBatteryReadRequestedAt = Date()
                AtriaDebugLog("ATRIADBG strap_status_refresh status=skipped reason=%@ detail=2A19_not_readable_or_notifiable",
                              reason)
            }
            return
        }
        peripheral.discoverServices([UUIDs.batteryService])
        AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ services=battery", reason)
    }

    private func scheduleBatteryConfirmationRead(incomingLevel: Int) {
        if batteryConfirmationReadTask != nil,
           let scheduledLevel = batteryConfirmationReadLevel,
           abs(scheduledLevel - incomingLevel) <= 2 {
            return
        }
        batteryConfirmationReadTask?.cancel()
        let delay = Self.batteryConfirmationRetryDelay(incomingLevel: incomingLevel)
        batteryConfirmationReadLevel = incomingLevel
        batteryConfirmationReadTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(delay))
            guard let self, !Task.isCancelled else { return }
            self.batteryConfirmationReadTask = nil
            self.batteryConfirmationReadLevel = nil
            guard let peripheral,
                  peripheral.state == .connected,
                  self.status == .connected else { return }
            self.requestStrapStatusRead(reason: "battery_confirmation_notify")
        }
    }

    private func rediscoverFullProtocolServicesIfConnected(reason: String) {
        guard status == .connected, let peripheral, peripheral.state == .connected else { return }
        txCharacteristic = nil
        realtimeArmed = false
        activeProprietaryNotifyUUIDs.removeAll()
        strapStream5NotifyConfirmed = false
        peripheral.discoverServices(discoveryServicesForCurrentMode)
        AtriaDebugLog("ATRIADBG radio_mode full_protocol_discovery status=requested reason=%@ action=keep_connection",
                      reason)
    }

    /// Runs while long-wear is enabled, including app-switch/background
    /// transitions. It does nothing while data flows. If the link is `.connected`
    /// but has produced no 2A37 packet for an extended window, it re-asserts the
    /// subscription, then escalates to a fresh-scan reconnect if silence
    /// persists. requestFreshScanReconnect already backs off exponentially.
    private func ensureForegroundKeepaliveWatchdog(reason: String) {
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard longWearModeEnabled || activeExplicitWorkout else {
            stopForegroundKeepaliveWatchdog(reason: reason)
            return
        }
        guard foregroundKeepaliveTask == nil else {
            UserDefaults.standard.set(reason, forKey: KeepaliveDefaults.lastReason)
            AtriaDebugLog("ATRIADBG foreground_keepalive armed=1 reason=%@ action=keep_existing_owner",
                          reason)
            return
        }
        startForegroundKeepaliveWatchdog(reason: reason)
    }

    private func startForegroundKeepaliveWatchdog(reason: String) {
        foregroundKeepaliveTask?.cancel()
        foregroundKeepaliveTask = nil
        foregroundKeepaliveReassertAt = nil
        foregroundKeepaliveLastJournalFlushAt = nil
        foregroundKeepaliveLastRawNotifications = sampleDiagnostics.rawNotifications
        let silenceTimeout: TimeInterval = 75
        let initialSilenceTimeout: TimeInterval = 8
        let initialReconnectWindow: TimeInterval = 20
        let checkInterval: TimeInterval = 20
        let armedAt = Date()
        let defaults = UserDefaults.standard
        defaults.set(true, forKey: KeepaliveDefaults.armed)
        defaults.set(armedAt.timeIntervalSince1970, forKey: KeepaliveDefaults.armedAt)
        defaults.set("armed", forKey: KeepaliveDefaults.lastStatus)
        defaults.set(reason, forKey: KeepaliveDefaults.lastReason)
        defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
        defaults.set(0.0, forKey: KeepaliveDefaults.lastSilence)
        defaults.removeObject(forKey: KeepaliveDefaults.tickStartedAt)
        defaults.removeObject(forKey: KeepaliveDefaults.lastTickAt)
        AtriaDebugLog("ATRIADBG foreground_keepalive armed=1 reason=%@ silence_timeout_s=%.0f check_interval_s=%.0f",
              reason, silenceTimeout, checkInterval)
        runForegroundKeepaliveTick(
            armedAt: armedAt,
            silenceTimeout: silenceTimeout,
            initialSilenceTimeout: initialSilenceTimeout,
            initialReconnectWindow: initialReconnectWindow
        )
        foregroundKeepaliveTask = Task { @MainActor in
            while !Task.isCancelled {
                let governedInterval = checkInterval * effectiveThermalCadenceMultiplier
                try? await Task.sleep(for: .seconds(governedInterval))
                if Task.isCancelled { break }
                runForegroundKeepaliveTick(
                    armedAt: armedAt,
                    silenceTimeout: silenceTimeout,
                    initialSilenceTimeout: initialSilenceTimeout,
                    initialReconnectWindow: initialReconnectWindow
                )
            }
        }
        defaults.synchronize()
    }

    private func runForegroundKeepaliveTick(
        armedAt: Date,
        silenceTimeout: TimeInterval,
        initialSilenceTimeout: TimeInterval,
        initialReconnectWindow: TimeInterval
    ) {
        let now = Date()
        let defaults = UserDefaults.standard
        defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.tickStartedAt)
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard Self.isBLEContinuityRelevant(
            longWearEnabled: longWearModeEnabled,
            activeExplicitWorkout: activeExplicitWorkout
        ) else {
            defaults.set("disabled", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("wait_continuity_owner", forKey: KeepaliveDefaults.lastAction)
            return
        }
        if Self.shouldKeepaliveObserveOnlyDuringHistory(
            offlineHistoricalSyncInProgress: offlineHistoricalSyncInProgress,
            historyOnlyProbeEnabled: historyOnlyProbeEnabled,
            historyTransportPhaseActive: historyOnlyProbeMode
        ) {
            foregroundKeepaliveReassertAt = nil
            defaults.set("history_transport_owned", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=history_transport_owned action=observe_only no_battery_read=1 no_2a37_read_or_discovery=1 no_reconnect=1")
            return
        }
        defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.lastTickAt)
        defaults.set(defaults.integer(forKey: KeepaliveDefaults.ticks) + 1, forKey: KeepaliveDefaults.ticks)
        if peripheral == nil {
            recomputeConnectionStatus(reason: "foreground_keepalive_missing_peripheral")
            defaults.set("missing_peripheral", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("reconnect_known_strap", forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=missing_peripheral action=reconnect_known_strap saved=%d",
                          hasSavedStrap ? 1 : 0)
            if !reconnectToSavedPeripheralIfPossible(reason: "foreground_keepalive_missing_peripheral") {
                startScan(reason: "foreground_keepalive_missing_peripheral")
            }
            return
        }
        guard status == .connected, let peripheral else { return }
        guard peripheral.state == .connected else {
            recomputeConnectionStatus(reason: "foreground_keepalive_peripheral_not_connected")
            defaults.set("peripheral_not_connected", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("reconnect_known_strap", forKey: KeepaliveDefaults.lastAction)
            defaults.set(Double(peripheral.state.rawValue), forKey: KeepaliveDefaults.lastPeripheralState)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=peripheral_not_connected peripheral_state=%d action=reconnect_known_strap saved=%d",
                          peripheral.state.rawValue,
                          hasSavedStrap ? 1 : 0)
            if !reconnectToSavedPeripheralIfPossible(reason: "foreground_keepalive_peripheral_state_\(peripheral.state.rawValue)") {
                startScan(reason: "foreground_keepalive_peripheral_state_\(peripheral.state.rawValue)")
            }
            return
        }
        defaults.set(Double(peripheral.state.rawValue), forKey: KeepaliveDefaults.lastPeripheralState)
        // Fall back to the keepalive's own arm time so silence is always
        // measurable — a state-restored connection (the overnight case)
        // can have no lastRawHRNotificationAt and no connectedAt at all,
        // which previously left this watchdog unable to ever fire.
        let reference = Self.latestLinkActivity([lastRawHRNotificationAt, connectedAt, armedAt]) ?? armedAt
        let silence = now.timeIntervalSince(reference)
        let hasSeenPacket = lastRawHRNotificationAt != nil
        let effectiveSilenceTimeout = hasSeenPacket ? silenceTimeout : initialSilenceTimeout
        defaults.set(silence, forKey: KeepaliveDefaults.lastSilence)
        let currentRawNotifications = sampleDiagnostics.rawNotifications
        let previousRawNotifications = foregroundKeepaliveLastRawNotifications
        foregroundKeepaliveLastRawNotifications = currentRawNotifications
        defaults.set(currentRawNotifications, forKey: KeepaliveDefaults.lastRawNotifications)
        let rawNotificationDelta: Int?
        if let previousRawNotifications {
            let delta = currentRawNotifications - previousRawNotifications
            rawNotificationDelta = delta
            defaults.set(delta, forKey: KeepaliveDefaults.lastRawNotificationDelta)
        } else {
            rawNotificationDelta = nil
        }
        defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.lastSampleCheckAt)
        let applicationActive = UIApplication.shared.applicationState == .active
        updateDutyCycleState(reason: "keepalive_tick", now: now)
        if Self.shouldRequestBatteryRefresh(lastRequestedAt: lastBatteryReadRequestedAt, now: now) {
            requestStrapStatusRead(reason: "keepalive_freshness")
        }
        let batteryNotificationTransportActive = batteryNotificationTransportIsActive(
            now: now,
            defaults: defaults
        )
        let recentReconnectBatteryBaselineDisplayable =
            recentReconnectBatteryBaselineIsDisplayable(
                now: now,
                defaults: defaults
            )
        let savedPeripheralIdentifier = defaults
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        let reconnectBatteryBaselineAwaitingProof =
            Self.reconnectBatteryBaselineIsAwaitingProof(
                level: batteryLevel,
                acceptedAt: lastAcceptedBatteryLevelAt,
                source: defaults.string(forKey: BatteryDefaults.source) ?? "none",
                displayedIsCached: displayedBatteryLevelIsCached,
                requiresFreshConfirmation: defaults.bool(
                    forKey: BatteryDefaults.requiresFreshConfirmation
                ),
                linkConnected: peripheral.state == .connected && status == .connected,
                sameSavedPeripheral: peripheral.identifier == savedPeripheralIdentifier,
                validationStartedAt: batteryBaselineValidationStartedAt,
                now: now
            )
        if batteryLevel >= 0,
           !Self.batteryLevelIsFresh(lastAcceptedAt: lastAcceptedBatteryLevelAt, now: now),
           !recentReconnectBatteryBaselineDisplayable,
           !reconnectBatteryBaselineAwaitingProof,
           !(batteryNotificationTransportActive
                && !displayedBatteryLevelIsCached
                && !UserDefaults.standard.bool(forKey: BatteryDefaults.requiresFreshConfirmation)) {
            // A connected HR stream is not evidence that the independent 2A19
            // value is current. Fail closed instead of keeping a stale low/full
            // percentage on every screen and notification surface.
            assignIfChanged(\.batteryLevel, -1)
            assignIfChanged(\.batteryIsCharging, false)
            assignIfChanged(\.batteryChargeStatus, .levelOnly)
            assignIfChanged(\.batteryRecentlyDropping, false)
            batteryReadingIsRecentBaseline = false
            UserDefaults.standard.set(true, forKey: BatteryDefaults.requiresFreshConfirmation)
            UserDefaults.standard.removeObject(forKey: BatteryDefaults.notificationLeaseAt)
            pendingBatteryDropCandidate = nil
            batteryProjectionRevision &+= 1
            AtriaDebugLog("ATRIADBG battery status=hidden reason=stale_live_value max_age_s=%.0f",
                          Self.batteryDisplayFreshnessLimit)
        }
        if batteryLevel >= 0,
           batteryNotificationTransportActive,
           !displayedBatteryLevelIsCached,
           !UserDefaults.standard.bool(forKey: BatteryDefaults.requiresFreshConfirmation) {
            // Keep the persisted/widget projection current without pretending a
            // new level packet arrived. The raw packet timestamp remains in
            // BatteryDefaults.at; only this subscription lease advances.
            UserDefaults.standard.set(now.timeIntervalSince1970,
                                      forKey: BatteryDefaults.notificationLeaseAt)
        }
        // While the notify stream is silent but the link is up, poll 2A37 by
        // read every tick. Low-battery evidence so far only proves coarse HR
        // may be available here; RR/detail still requires notification recovery.
        // In sparse duty-cycle mode the SAME read-poll is the sentinel, but at
        // the sparse interval instead of every tick.
        let sparseDue = dutyCycleState != .sparseSentinel
            || (lastSparsePollAt.map { now.timeIntervalSince($0) >= Self.dutyCycleSparsePollInterval } ?? true)
        if applicationActive,
           dutyCycleState == .sparseSentinel,
           silence > 15,
           sparseDue,
           let characteristic = heartRateCharacteristic,
           characteristic.properties.contains(.read) {
            lastSparsePollAt = now
            AtriaDebugLog("ATRIADBG duty_cycle action=sparse_poll interval_s=%.0f", Self.dutyCycleSparsePollInterval)
            peripheral.readValue(for: characteristic)
            defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.lastReadPollAt)
        }
        // Immediate stall detection: uses the persisted last-packet timestamp
        // so it fires on the very first tick after a launch/foreground return.
        // The previous delta-based check needed a second tick that a
        // suspended-or-starved process never delivered.
        let persistedLastPacketInterval = defaults.double(forKey: SampleDefaults.lastRawNotificationAt)
        let lastPacketAt = Self.latestLinkActivity([
            lastRawHRNotificationAt,
            persistedLastPacketInterval > 0 ? Date(timeIntervalSince1970: persistedLastPacketInterval) : nil,
            connectedAt,
        ]) ?? armedAt
        let stallCooldownOK = lastStallHardReconnectAt.map { now.timeIntervalSince($0) >= 120 } ?? true
        let subscribeGraceOK = connectedAt.map { now.timeIntervalSince($0) > 25 } ?? true
        let packetAge = now.timeIntervalSince(lastPacketAt)
        let usefulGattReference = Self.latestLinkActivity([lastGattActivityAt, connectedAt, armedAt])
            ?? armedAt
        let usefulGattGap = max(0, now.timeIntervalSince(usefulGattReference))
        let continuityDisposition = Self.heartRateContinuityRecoveryDisposition(
            rawHeartRateGap: max(0, packetAge),
            usefulGattGap: usefulGattGap,
            adaptiveTimeout: effectiveSilenceTimeout,
            peripheralConnected: peripheral.state == .connected,
            hasHeartRateCharacteristic: heartRateCharacteristic != nil,
            heartRateIsNotifying: heartRateCharacteristic?.isNotifying == true,
            canReadHeartRate: heartRateCharacteristic?.properties.contains(.read) == true,
            canNotifyHeartRate: heartRateCharacteristic?.properties.contains(.notify) == true
        )
        updateStrapStreamState(reason: "foreground_keepalive",
                               rawNotificationDelta: rawNotificationDelta,
                               notifying: heartRateCharacteristic?.isNotifying,
                               defaults: defaults)
        if strapStreamState == .lowBatteryShutoff,
           packetAge > Self.staleHeartRatePacketThreshold {
            foregroundKeepaliveReassertAt = nil
            defaults.set("low_battery_shutoff", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("suppress_hard_reconnect", forKey: KeepaliveDefaults.lastAction)
            markLowBatteryReconnectSuppressed(reason: "low_battery_shutoff", defaults: defaults, now: now)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=low_battery_shutoff battery=%d packet_age_s=%.0f action=suppress_hard_reconnect",
                          batteryLevel,
                          packetAge)
            return
        }
        // Sparse duty-cycle intentionally silences 2A37. The sparse read poll
        // and battery refresh above still run, but no silence duration may turn
        // that intentional state into a connection rebuild.
        if dutyCycleState == .sparseSentinel {
            foregroundKeepaliveReassertAt = nil
            defaults.set("sparse_expected_silence", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
            return
        }
        if applicationActive,
           !offlineHistoricalSyncInProgress,
           subscribeGraceOK,
           stallCooldownOK,
           Self.shouldPerformForegroundKeepaliveHardRebuild(
            isSparseSentinel: dutyCycleState == .sparseSentinel,
            disposition: continuityDisposition
           ) {
            foregroundKeepaliveReassertAt = nil
            defaults.set("sample_counter_stalled", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("hard_reconnect", forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=sample_counter_stalled raw_notifications=%d packet_age_s=%.0f useful_gatt_gap_s=%.0f action=hard_reconnect",
                          currentRawNotifications,
                          packetAge,
                          usefulGattGap)
            forceHardReconnectForPacketStall(peripheral: peripheral,
                                             reason: "foreground_keepalive_all_gatt_silent_120s")
            return
        }
        guard silence >= effectiveSilenceTimeout else {
            foregroundKeepaliveReassertAt = nil
            defaults.set("observing", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
            // Keep the live session crash-safe even during a long foreground
            // stretch. persistActiveSessionJournalIfNeeded skips unchanged
            // values, so this once-a-minute checkpoint is cheap.
            if foregroundKeepaliveLastJournalFlushAt.map({ now.timeIntervalSince($0) >= 60 }) ?? true {
                foregroundKeepaliveLastJournalFlushAt = now
                flushActiveSessionJournal(reason: "foreground_keepalive_crash_safety")
            }
            return
        }
        // First escalation keeps an active subscription untouched. Read 2A37
        // when possible; only enable notifications when CoreBluetooth says the
        // characteristic is not currently notifying.
        if foregroundKeepaliveReassertAt == nil {
            foregroundKeepaliveReassertAt = now
            let action: String
            switch continuityDisposition {
            case .readHeartRate:
                if let characteristic = heartRateCharacteristic {
                    peripheral.readValue(for: characteristic)
                }
                action = "read_2a37_keep_notify"
            case .enableHeartRateNotifications:
                if let characteristic = heartRateCharacteristic {
                    _ = requestHeartRateNotificationEnableIfNeeded(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        reason: "foreground_keepalive"
                    )
                }
                action = "enable_2a37_once"
            case .rediscoverHeartRateService:
                peripheral.discoverServices([UUIDs.heartRateService])
                action = "rediscover_2a37_service"
            case .reconnectKnownPeripheral:
                reconnectKnownPeripheralImmediately(
                    peripheral,
                    reason: "foreground_keepalive_corebluetooth_disconnected"
                )
                action = "reconnect_known_peripheral"
            case .observe, .rebuildConnection:
                action = "observe_live_link"
            }
            defaults.set("silent", forKey: KeepaliveDefaults.lastStatus)
            defaults.set(action, forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=silent silence_s=%.0f useful_gatt_gap_s=%.0f action=%@ notifying=%@",
                          silence,
                          usefulGattGap,
                          action,
                          heartRateCharacteristic.map { $0.isNotifying ? "1" : "0" } ?? "missing")
            return
        }
        // Keep observing/repairing the characteristic until the 120-second
        // all-useful-GATT gate above proves that the whole connection is dead.
        let reconnectWindow = hasSeenPacket ? silenceTimeout : initialReconnectWindow
        guard now.timeIntervalSince(foregroundKeepaliveReassertAt ?? now) >= reconnectWindow else { return }
        foregroundKeepaliveReassertAt = nil
        defaults.set("silent", forKey: KeepaliveDefaults.lastStatus)
        defaults.set("observe_until_all_gatt_silent", forKey: KeepaliveDefaults.lastAction)
        AtriaDebugLog("ATRIADBG foreground_keepalive status=silent silence_s=%.0f useful_gatt_gap_s=%.0f action=observe_until_all_gatt_silent",
                      silence,
                      usefulGattGap)
    }

    nonisolated static func shouldKeepaliveObserveOnlyDuringHistory(
        offlineHistoricalSyncInProgress: Bool,
        historyOnlyProbeEnabled: Bool,
        historyTransportPhaseActive: Bool
    ) -> Bool {
        offlineHistoricalSyncInProgress
            || historyOnlyProbeEnabled
            || historyTransportPhaseActive
    }

    nonisolated static func historicalTransportOwnershipIsActive(
        offlineSyncInProgress: Bool,
        historyProbeEnabled: Bool,
        historyPhaseActive: Bool,
        readOnlyRequested: Bool,
        readOnlyActive: Bool,
        postHistoryLiveRestorationPending: Bool,
        explicitRequestPending: Bool,
        freshOwnerCutoverPending: Bool,
        freshOwnerConnectionArmed: Bool,
        explicitLaunchIntentPending: Bool
    ) -> Bool {
        offlineSyncInProgress
            || historyProbeEnabled
            || historyPhaseActive
            || readOnlyRequested
            || readOnlyActive
            || postHistoryLiveRestorationPending
            || explicitRequestPending
            || freshOwnerCutoverPending
            || freshOwnerConnectionArmed
            || explicitLaunchIntentPending
    }

    /// A history owner belongs to the BLE epoch which armed it.  If that epoch
    /// was interrupted, it must not suppress standard 2A37 discovery on the
    /// replacement connection.  A deliberately armed fresh-owner cutover is
    /// the sole exception: it is the one case allowed to carry history
    /// ownership across a disconnect.
    nonisolated static func shouldReleaseInterruptedHistoryOwnerForLiveReconnect(
        offlineSyncInProgress: Bool,
        historyPhaseActive: Bool,
        disconnectObservedWithHistoryOwner: Bool,
        freshOwnerCutoverPending: Bool,
        freshOwnerAdmissionPending: Bool,
        freshOwnerConnectionArmed: Bool
    ) -> Bool {
        guard disconnectObservedWithHistoryOwner,
              offlineSyncInProgress || historyPhaseActive else {
            return false
        }
        return !freshOwnerCutoverPending
            && !freshOwnerAdmissionPending
            && !freshOwnerConnectionArmed
    }

    nonisolated static func shouldAllowAncillaryGATTRefresh(
        historyTransportOwnsLink: Bool
    ) -> Bool {
        !historyTransportOwnsLink
    }

    private func stopForegroundKeepaliveWatchdog(reason: String) {
        guard foregroundKeepaliveTask != nil else { return }
        foregroundKeepaliveTask?.cancel()
        foregroundKeepaliveTask = nil
        foregroundKeepaliveReassertAt = nil
        UserDefaults.standard.set(false, forKey: KeepaliveDefaults.armed)
        UserDefaults.standard.set("stopped", forKey: KeepaliveDefaults.lastStatus)
        UserDefaults.standard.set(reason, forKey: KeepaliveDefaults.lastReason)
        UserDefaults.standard.set("stop", forKey: KeepaliveDefaults.lastAction)
        AtriaDebugLog("ATRIADBG foreground_keepalive armed=0 reason=%@", reason)
    }

    func setForegroundHighFrequencyDisplayMode(_ enabled: Bool) {
        guard foregroundHighFrequencyDisplayMode != enabled else { return }
        foregroundHighFrequencyDisplayMode = enabled
        updateDutyCycleState(reason: enabled ? "live_screen_open" : "live_screen_closed")
    }

    func handleUnattendedMode(rest: Int, maxHR: Int, reason: String) {
        if !foregroundInteractiveMode {
            ensureForegroundKeepaliveWatchdog(reason: reason)
            return
        }
        foregroundInteractiveMode = false
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard Self.isBLEContinuityRelevant(
            longWearEnabled: longWearModeEnabled,
            activeExplicitWorkout: activeExplicitWorkout
        ) else {
            stopForegroundKeepaliveWatchdog(reason: reason)
            return
        }
        ensureForegroundKeepaliveWatchdog(reason: reason)
        if longWearModeEnabled {
            if Self.shouldRestoreProtectedLongWearRadioInBackground(
                activeExplicitWorkout: activeExplicitWorkout
            ) {
                restoreProtectedLongWearRadioIfNeeded(reason: reason)
            }
            startLongWearMode(rest: rest, maxHR: maxHR, reason: reason)
        }
        AtriaDebugLog("ATRIADBG long_wear_mode foreground_interactive=0 action=resume_automation reason=%@ rest_hr=%d max_hr=%d",
              reason,
              rest,
              maxHR)
    }

    func handleSceneBackgroundTransition(reason: String,
                                         rest: Int,
                                         maxHR: Int,
                                         flushRealtimeState: Bool = true) {
        foregroundInteractiveMode = false
        if flushRealtimeState {
            flushLifecycleRealtimeState(reason: reason)
        }
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        if longWearModeEnabled {
            // A live workout owns its current radio mode. In particular, R10 step
            // calibration needs full protocol in the background; downgrading to
            // standard-HR-only here reconnects and loses both steps and HR.
            if Self.shouldRestoreProtectedLongWearRadioInBackground(
                activeExplicitWorkout: activeExplicitWorkout
            ) {
                restoreProtectedLongWearRadioIfNeeded(reason: reason)
            }
            startLongWearMode(rest: rest, maxHR: maxHR, reason: reason)
        } else {
            ensureForegroundKeepaliveWatchdog(reason: reason)
        }
        reassertHeartRateNotificationsIfConnected(reason: reason)
        reassertR10NotificationIfConnected(reason: reason)
        AtriaDebugLog("ATRIADBG long_wear_mode foreground_interactive=0 action=background_keep_link reason=%@ connected=%d",
              reason,
              status == .connected ? 1 : 0)
    }

    @discardableResult
    private func retainPendingOfflineHistoricalSyncRequest(
        reason: String,
        force: Bool,
        explicitRequest: Bool
    ) -> PendingOfflineHistoricalSyncRequest {
        let retained = Self.coalescedPendingOfflineHistoricalSyncRequest(
            existing: pendingOfflineHistoricalSyncRequest,
            reason: reason,
            force: force,
            explicitRequest: explicitRequest
        )
        pendingOfflineHistoricalSyncRequest = retained
        return retained
    }

    private func takePendingOfflineHistoricalSyncRequest()
        -> PendingOfflineHistoricalSyncRequest? {
        defer { pendingOfflineHistoricalSyncRequest = nil }
        return pendingOfflineHistoricalSyncRequest
    }

    /// An explicitly requested diagnostic may resume after a current-epoch HR
    /// sample has entered the journal. A persisted *interrupted* full drain is
    /// different: it is recovery evidence, not a user command. Reclaiming a
    /// just-restored live link for that old request creates a reconnect loop,
    /// so preserve its exact gap and wait for ordinary retry policy or a new
    /// explicit diagnostic instead.
    private func resumePendingForcedHistoricalSyncAfterLivePersistenceIfNeeded(
        reason: String
    ) {
        guard let pending = pendingOfflineHistoricalSyncRequest,
              pending.force,
              pending.explicitRequest,
              !freshHistoryOwnerBoundaryFailureLatched,
              !offlineHistoricalSyncInProgress,
              !AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
              !historicalConsumerMaterializationInFlight,
              postHistoryLiveRestorationTask == nil,
              peripheral?.state == .connected,
              status == .connected,
              let connectedAt,
              let lastAcceptedHRAt,
              lastAcceptedHRAt >= connectedAt else { return }
        if Self.shouldDeferInterruptedFullDrainRelaunchAfterLivePersistence(
            pendingReason: pending.reason
        ) {
            _ = takePendingOfflineHistoricalSyncRequest()
            explicitHistoryLaunchIntentPending = false
            deferInterruptedFullDrainForCurrentLiveConnection = true
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            let defaults = UserDefaults.standard
            defaults.set("deferred_interrupted_full_drain_live_priority",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(pending.reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_interrupted_full_drain_live_priority reason=%@ trigger=%@ action=retain_exact_gap_no_fresh_owner_cutover",
                          pending.reason,
                          reason)
            return
        }
        _ = takePendingOfflineHistoricalSyncRequest()
        AtriaDebugLog("ATRIADBG offline_sync status=resuming_explicit_force reason=%@ trigger=%@ action=flush_live_journal_then_acquire_history_owner",
                      pending.reason,
                      reason)
        _ = requestOfflineHistoricalSyncIfNeeded(
            reason: pending.reason,
            force: pending.force,
            explicitResearchRequest: pending.explicitRequest
        )
    }

    nonisolated static func shouldResumeInterruptedFullDrainAtLaunch(
        rangeLossBackfillPending: Bool,
        authorityStatus: AtriaHistoricalFullDrainCoverageStore.Authority.Status?,
        exactGapFingerprintStillPending: Bool
    ) -> Bool {
        rangeLossBackfillPending
            && authorityStatus == .draining
            && exactGapFingerprintStillPending
    }

    /// The launch marker restores a durable recovery candidate, not permission
    /// to interrupt the first healthy live connection after a radio outage.
    nonisolated static func shouldDeferInterruptedFullDrainRelaunchAfterLivePersistence(
        pendingReason: String
    ) -> Bool {
        pendingReason == "interrupted_full_drain_relaunch"
    }

    /// A full-drain authority is a durable transport transaction, not merely a
    /// diagnostic snapshot. If iOS replaces the process before HISTORY_COMPLETE,
    /// ordinary launch must reacquire the history owner from the already-fsynced
    /// admission cursor. Otherwise the app silently falls back to live HR and
    /// leaves the missing window pending forever unless a Mac supplies a debug
    /// launch argument. Only `.draining` is eligible here: terminal authorities
    /// resume their publication journal elsewhere and must never seize BLE again.
    private func restoreInterruptedFullDrainLaunchIntentIfNeeded(
        defaults: UserDefaults
    ) {
        let authority = try? historicalFullDrainCoverageStore.load()
        let exactGapFingerprintStillPending = authority.flatMap { authority in
            UUID(uuidString: authority.gap.gapIdentifier).flatMap { gapID in
                AtriaHistoricalGapLedger.recoveryCandidate(
                    id: gapID,
                    startUnix: authority.gap.startUnix,
                    endUnix: authority.gap.endUnix,
                    reason: authority.gap.reason
                )
            }
        } != nil
        guard Self.shouldResumeInterruptedFullDrainAtLaunch(
            rangeLossBackfillPending: defaults.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
            ),
            authorityStatus: authority?.status,
            exactGapFingerprintStillPending: exactGapFingerprintStillPending
        ) else { return }
        explicitHistoryLaunchIntentPending = true
        retainPendingOfflineHistoricalSyncRequest(
            reason: "interrupted_full_drain_relaunch",
            force: true,
            explicitRequest: true
        )
        defaults.set("pending_interrupted_full_drain_relaunch",
                     forKey: OfflineSyncDefaults.lastStatus)
        defaults.set("interrupted_full_drain_relaunch",
                     forKey: OfflineSyncDefaults.lastReason)
        AtriaDebugLog("ATRIADBG offline_sync status=pending_interrupted_full_drain_relaunch authority=%@ action=await_current_epoch_hr_then_resume_durable_cursor",
                      authority?.authorityIdentifier ?? "none")
    }

    @discardableResult
    func requestOfflineHistoricalSyncIfNeeded(
        reason: String,
        force: Bool = false,
        allowConnectedAutomaticHandoff: Bool = false,
        freshOwnerCutoverCompleted: Bool = false,
        explicitResearchRequest: Bool = false
    ) -> Bool {
        guard !readOnlyHistoryCaptureRequested else {
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=read_only_capture_owns_transport action=no_production_commands",
                          reason)
            return false
        }
        if motionHandshakeDiagnostic != nil {
            recordMotionHandshakeEvidence(event: "offline_sync_blocked", detail: reason)
            return false
        }
        let defaults = UserDefaults.standard
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        let connectedLink = peripheral?.state == .connected
        let connectingLink = peripheral?.state == .connecting
        let explicitUserRequest = Self.isExplicitUserOfflineSyncReason(reason)
        let explicitHistoricalRequest = explicitUserRequest || explicitResearchRequest
        // A sequence-confirmation retry is an explicit, bounded replay of the
        // exact transition which previously failed closed. An automatic
        // range-loss retry must not acquire another history generation while
        // that replay is waiting for its fresh-HR boundary: doing so can
        // replace the retained cursor and turn one diagnostic retry into
        // competing history owners. Explicit user/repair requests remain the
        // only allowed owner during this window.
        if historySequenceConfirmationRetryTask != nil,
           !explicitHistoricalRequest {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("deferred_sequence_confirmation_replay",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_sequence_confirmation_replay reason=%@ action=retain_automatic_gap_until_explicit_replay_finishes",
                          reason)
            return false
        }
        // Aged automatic retries can carry `force`, so force alone must not
        // bypass this gate. Preserve the durable request and the live radio
        // while iOS reports serious/critical pressure; the governor schedules
        // the retained range-loss recovery when pressure returns to fair or
        // nominal. Never abort a transaction already in progress here.
        if Self.shouldDeferAutomaticOfflineSyncForThermalPressure(
            thermalPressure: powerThermalGovernor.shouldDeferNonEssentialAnalysis,
            explicitUserRequest: explicitHistoricalRequest
        ), !offlineHistoricalSyncInProgress {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_thermal_pressure",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=thermal_pressure mode=%@ force=%d action=retain_gap_preserve_live_radio",
                          reason,
                          powerThermalGovernor.mode.rawValue,
                          force ? 1 : 0)
            return false
        }
        // Never turn a pending CoreBluetooth reconnect into a history
        // transaction. In a locked-phone physical soak the aged automatic retry
        // cancelled the standing standard-HR reconnect, churned three links,
        // and then suspended with no samples. Retain/coalesce the durable
        // request and let didConnect restore
        // realtime ownership first. Explicit UI/research requests also wait for
        // that connection edge rather than manufacturing another disconnect.
        if !freshOwnerCutoverCompleted,
           Self.shouldDeferAutomaticOfflineSyncForConnectedLink(
            linkConnected: false,
            linkConnecting: connectingLink,
            explicitUserRequest: explicitHistoricalRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_realtime_reconnect_in_flight",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=realtime_reconnect_in_flight action=retain_gap_and_pending_connect explicit=%d",
                          reason,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        let verifiedPeripheralID = defaults.string(forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID)
        let currentPeripheralID = peripheral?.identifier.uuidString
        let previouslyVerified = currentPeripheralID != nil && currentPeripheralID == verifiedPeripheralID
        var verifiedHistoryCapability = Self.supportsVerifiedHistoricalRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified
        )
        var verifiedMetricHistoryCapability = Self.supportsVerifiedHistoricalTransactionRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified,
            fullDrainGapRecoveryEnabled:
                Self.productionHistoricalFullDrainGapRecoveryEnabled
        )
        let recoverableGapPending = Self.hasValidRangeLossBackfillRequest(
            pending: defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
            requestedAt: defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double,
            now: Date()
        )
        if Self.shouldQualifyPendingHistoryByServiceDiscovery(
            exactGapPending: recoverableGapPending,
            verifiedHistoryCapability: verifiedHistoryCapability,
            model: strapModel,
            linkConnected: connectedLink,
            activeExplicitWorkout: activeExplicitWorkout,
            syncInProgress: offlineHistoricalSyncInProgress
        ) {
            if peripheral?.services?.contains(where: {
                $0.uuid == Self.UUIDs.strapService
            }) == true {
                strapModel = .strap4Class
                verifiedHistoryCapability = Self.supportsVerifiedHistoricalRecovery(
                    model: strapModel,
                    previouslyVerified: previouslyVerified
                )
                verifiedMetricHistoryCapability = Self.supportsVerifiedHistoricalTransactionRecovery(
                    model: strapModel,
                    previouslyVerified: previouslyVerified,
                    fullDrainGapRecoveryEnabled:
                        Self.productionHistoricalFullDrainGapRecoveryEnabled
                )
                AtriaDebugLog("ATRIADBG history_capability status=qualified model=strap4Class source=restored_service_cache action=continue_pending_recovery")
            } else {
                retainPendingOfflineHistoricalSyncRequest(
                    reason: reason, force: force,
                    explicitRequest: explicitHistoricalRequest
                )
                armHistoryCapabilityQualification(for: currentPeripheralID)
                defaults.set("qualifying_history_service",
                             forKey: OfflineSyncDefaults.lastStatus)
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                AtriaDebugLog("ATRIADBG history_capability status=qualifying model=unknown action=discover_service_only_no_characteristic_or_command")
                return false
            }
        }
        let recoveryStartValue = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart)
        let recoveryEndValue = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd)
        let recoveryStart = (recoveryStartValue as? Date)
            ?? (recoveryStartValue as? Double).map(Date.init(timeIntervalSince1970:))
        let recoveryEnd = (recoveryEndValue as? Date)
            ?? (recoveryEndValue as? Double).map(Date.init(timeIntervalSince1970:))
        let gapFingerprint = Self.historicalGapFingerprint(
            windows: AtriaHistoricalGapLedger.windows(defaults: defaults),
            recoveryStart: recoveryStart,
            recoveryEnd: recoveryEnd,
            requestedAt: defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double
        )
        let rawGapAlreadyArchived = gapFingerprint != nil
            && gapFingerprint == defaults.string(forKey: OfflineSyncDefaults.rawArchivedGapFingerprint)
        // Migrate the last production timeout recorded before the exact-gap
        // circuit breaker existed. The guard binds the app-owned timeout,
        // confirmed 16/00 write, recovery attempt and current gap to one short
        // history-owner epoch; it must never infer a timeout from an unrelated
        // app cancellation. Explicit repair is deliberately never blocked.
        if !explicitHistoricalRequest,
           defaults.string(forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint) == nil {
            let newestClosedGapEndUnix = AtriaHistoricalGapLedger
                .newestClosedRecoveryCandidate(defaults: defaults)?
                .window.end?.timeIntervalSince1970
            if Self.shouldMigrateHistoryStartTimeoutCircuitBreaker(
                lastAppCancelReason: defaults.string(forKey: "atria.ble.lastAppCancelReason"),
                lastAppCancelAtUnix: defaults.double(forKey: "atria.ble.lastAppCancelAt"),
                handshakeStatus: defaults.string(forKey: OfflineSyncDefaults.handshakeStatus),
                handshakeAtUnix: defaults.double(forKey: OfflineSyncDefaults.handshakeAt),
                backfillStartedAtUnix: defaults.double(
                    forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt
                ),
                newestClosedGapEndUnix: newestClosedGapEndUnix
            ), let gapFingerprint {
                defaults.set(
                    gapFingerprint,
                    forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
                )
                defaults.set(
                    defaults.double(forKey: "atria.ble.lastAppCancelAt"),
                    forKey: OfflineSyncDefaults.historyStartTimeoutGapAt
                )
                defaults.set("history_start_timeout_gap_migrated",
                             forKey: OfflineSyncDefaults.lastStatus)
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                AtriaDebugLog("ATRIADBG offline_sync status=history_start_timeout_gap_migrated reason=%@ action=preserve_exact_gap_suppress_automatic_owner_manual_repair_available",
                              reason)
            }
        }
        if Self.shouldSuppressAutomaticHistoricalNoRowsRetry(
            exactGapPending: recoverableGapPending,
            explicitUserRequest: explicitHistoricalRequest,
            currentGapFingerprint: gapFingerprint,
            noRowsGapFingerprint: defaults.string(
                forKey: OfflineSyncDefaults.noRowsGapFingerprint
            )
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("no_rows_gap_retained", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=no_rows_gap_retained reason=%@ detail=unchanged_durable_gap action=suppress_automatic_reentry_preserve_live_radio explicit=0",
                          reason)
            return false
        }
        // A confirmed 16/00 can time out before HISTORY_START on this strap.
        // That result is not permission to erase or mark the gap recovered,
        // but an automatic retry of the exact same gap would repeat the same
        // fresh-owner disconnect and can starve R10/live collection. Manual
        // repair remains authoritative and a materially new gap is eligible.
        let timeoutFingerprintForCurrentProfile =
            defaults.string(forKey: OfflineSyncDefaults.historyStartTimeoutProfileVersion)
                == Self.productionHistoryServeProfileVersion
                ? defaults.string(
                    forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
                )
                : nil
        if Self.shouldSuppressAutomaticHistoryStartTimeoutRetry(
            exactGapPending: recoverableGapPending,
            explicitUserRequest: explicitHistoricalRequest,
            currentGapFingerprint: gapFingerprint,
            historyStartTimeoutGapFingerprint: timeoutFingerprintForCurrentProfile
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("history_start_timeout_gap_retained",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=history_start_timeout_gap_retained reason=%@ detail=unchanged_durable_gap action=suppress_automatic_reentry_preserve_live_r10 explicit=0",
                          reason)
            return false
        }
        let rawOnlyDisconnectedRecovery = Self.shouldAttemptRawOnlyHistoricalRecovery(
            exactGapPending: recoverableGapPending,
            rawHistoryVerified: verifiedHistoryCapability,
            metricHistoryVerified: verifiedMetricHistoryCapability,
            linkConnected: connectedLink,
            activeExplicitWorkout: activeExplicitWorkout,
            explicitUserRequest: explicitHistoricalRequest,
            rawGapAlreadyArchived: rawGapAlreadyArchived
        )
        if recoverableGapPending,
           verifiedHistoryCapability,
           !verifiedMetricHistoryCapability,
           !explicitHistoricalRequest,
           !rawOnlyDisconnectedRecovery {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            let status = rawGapAlreadyArchived
                ? "raw_gap_archived_awaiting_transaction_validation"
                : "gap_retained_transaction_unverified"
            defaults.set(status,
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=%@ reason=%@ detail=raw_transport_only connected=%d archived=%d action=%@ explicit=0",
                          status,
                          reason,
                          connectedLink ? 1 : 0,
                          rawGapAlreadyArchived ? 1 : 0,
                          rawGapAlreadyArchived
                            ? "await_exact_range_and_clock_validation_without_repull"
                            : "preserve_realtime_until_natural_disconnect")
            return false
        }
        // Evaluate the exact-gap handoff before clean-owner deferrals. The
        // durable journal + verified WHOOP-4 capability fence is the bounded
        // exception that prevents a healthy standing reconnect from starving
        // its own missing interval forever.
        let protectedHistoryHandoffAllowed = Self.shouldAllowProtectedHistoricalRecovery(
            linkConnected: connectedLink,
            exactGapPending: recoverableGapPending,
            verifiedHistoryCapability: verifiedHistoryCapability,
            activeExplicitWorkout: activeExplicitWorkout,
            syncInProgress: offlineHistoricalSyncInProgress,
            explicitUserRequest: explicitHistoricalRequest
        )

        // A clean-owner cutover/proof/fallback owns the process radio even
        // across a disconnect. The physical V4 proof showed that admitting a
        // natural-disconnect history worker here immediately created a second
        // short link and obscured the protected-profile result.
        if !protectedHistoryHandoffAllowed,
           Self.shouldDeferAutomaticHistoryForCleanOwner(
            cleanOwner: protectedR10CleanOwner,
            state: protectedR10CleanOwnerState,
            explicitUserRequest: explicitHistoricalRequest,
            linkConnected: connectedLink
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_clean_owner_history_handoff",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=clean_owner_%@_%@ action=preserve_gap_no_history_reconnect",
                          reason,
                          protectedR10CleanOwner.rawValue,
                          protectedR10CleanOwnerState.rawValue)
            return false
        }

        if !protectedHistoryHandoffAllowed,
           Self.shouldDeferAutomaticOfflineSyncForProtectedR10Continuity(
            standardHROnlyMode: standardHROnlyMode,
            explicitUserRequest: explicitHistoricalRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_protected_r10_continuity",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=protected_r10_continuity force=%d explicit=0 action=preserve_gap_and_realtime",
                          reason,
                          force ? 1 : 0)
            return false
        }
        if !protectedHistoryHandoffAllowed,
           Self.shouldDeferOfflineSyncForProtectedR10Qualification(
            standardHROnlyMode: standardHROnlyMode,
            stableTransportProven: defaults.bool(forKey: Self.protectedR10StableTransportKey),
            explicitUserRequest: explicitHistoricalRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_protected_r10_realtime",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=protected_r10_realtime force=%d explicit=%d action=preserve_request_and_continuous_motion",
                          reason,
                          force ? 1 : 0,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        if standardHROnlyMode,
           !historyOnlyProbeMode,
           !protectedHistoryHandoffAllowed {
            UserDefaults.standard.set("disabled_protected_r10_minimal",
                                      forKey: OfflineSyncDefaults.lastStatus)
            UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=skipped reason=%@ detail=protected_r10_minimal_preserve_live connected=%d pending=%d verified=%d workout=%d explicit=%d",
                          reason,
                          connectedLink ? 1 : 0,
                          defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) ? 1 : 0,
                          verifiedHistoryCapability ? 1 : 0,
                          activeExplicitWorkout ? 1 : 0,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        let now = Date()
        scheduleStaleArmedRangeLossBackfillReconciliation(reason: reason, now: now)
        guard defaults.bool(forKey: OfflineSyncDefaults.enabled) else {
            defaults.set("disabled", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=skipped reason=%@ detail=disabled", reason)
            return false
        }
        guard Self.supportsVerifiedHistoricalRecovery(model: strapModel,
                                                       previouslyVerified: previouslyVerified) else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_unverified_history_capability", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=unverified_history_capability model=%@ peripheral=%@ action=fail_closed",
                          reason,
                          strapModel.rawValue,
                          currentPeripheralID ?? "none")
            return false
        }
        // A user-started workout owns the live radio. Historical replay changes
        // services/modes and has caused repeated reconnects in the background;
        // retain the request and run it after the durable workout intent closes.
        // This applies even to a force retry: force may bypass cadence, never the
        // user's active workout continuity boundary.
        if Self.shouldDeferOfflineSyncForExplicitWorkout(
            activeExplicitWorkout: activeExplicitWorkout
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_explicit_workout", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=explicit_workout_active force=%d action=preserve_live_radio",
                          reason,
                          force ? 1 : 0)
            return false
        }
        guard !historicalConsumerMaterializationInFlight else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_terminal_materialization",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=terminal_consumer_materialization_in_flight action=preserve_request",
                          reason)
            return false
        }
        guard !offlineHistoricalSyncInProgress else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("coalesced", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=coalesced reason=%@", reason)
            return false
        }
        guard postHistoryLiveRestorationTask == nil else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_post_history_live_restoration",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            return false
        }
        // Automatic archive recovery must never seize the proprietary command
        // pipe from an already-connected realtime stream. `force` is also used
        // by the aged range-loss retry state machine, so it is not evidence of
        // user intent: after 90 seconds that path previously stopped realtime
        // HR, entered history mode, disconnected, then repeated after every
        // reconnect while the exact recovery window remained pending. Wait for
        // a naturally disconnected transport instead. A deliberate user action
        // remains able to request a connected sync.
        if Self.shouldDeferAutomaticOfflineSyncForConnectedLink(
            linkConnected: connectedLink,
            linkConnecting: connectingLink,
            explicitUserRequest: explicitHistoricalRequest,
            exactGapPending: recoverableGapPending,
            verifiedMetricRecovery: verifiedMetricHistoryCapability,
            automaticConnectedHandoffAllowed: allowConnectedAutomaticHandoff
                || freshOwnerCutoverCompleted
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_connected_live_link", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_connected_live_link reason=%@ force=%d action=preserve_realtime_until_natural_disconnect",
                          reason,
                          force ? 1 : 0)
            return false
        }
        // Historical transport shares the proprietary command pipe with live
        // HR/R10. A physical five-minute proof showed that even a successful
        // background offload could end by cancelling an otherwise healthy
        // stream. Preserve live data; the durable gap ledger keeps this request
        // pending until a natural reconnect or an explicit manual force sync.
        if !force,
           !(recoverableGapPending && verifiedMetricHistoryCapability),
           shouldProtectLiveStreamForOfflineSync(now: now) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitHistoricalRequest
            )
            defaults.set("deferred_live_link", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_live_link reason=%@ detail=live_hr_recent action=keep_ble_stream",
                          reason)
            return false
        }
        let connectedChunkedBackfill = connectedLink
        let lastAttempt = defaults.object(forKey: OfflineSyncDefaults.lastAttemptAt) as? Date
        let minimumInterval = offlineHistoricalSyncMinimumInterval(for: reason)
        // `force` is also used internally once an automatic pending request is
        // old enough to take a safe radio handoff. It must not disable cadence
        // protection: that produced a real history transaction every ~30s
        // (hundreds of attempts) when a durable boundary could not advance.
        // Only an explicit user/research request may bypass the cooldown.
        if !explicitHistoricalRequest,
           let lastAttempt,
           now.timeIntervalSince(lastAttempt) < minimumInterval {
            defaults.set("throttled", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=skipped reason=%@ detail=throttled age_s=%.0f min_s=%.0f",
                  reason,
                  now.timeIntervalSince(lastAttempt),
                  minimumInterval)
            return false
        }
        if !freshOwnerCutoverCompleted,
           Self.shouldUseFreshHistoryOwnerCutover(
            linkConnected: connectedLink,
            force: force,
            explicitRequest: explicitHistoricalRequest || allowConnectedAutomaticHandoff,
            activeExplicitWorkout: activeExplicitWorkout,
            cutoverAlreadyPending: freshHistoryOwnerCutoverPending
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitHistoricalRequest
            )
            beginFreshHistoryOwnerCutover(reason: reason)
            return true
        }
        if freshHistoryOwnerCutoverPending && !freshOwnerCutoverCompleted {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitHistoricalRequest
            )
            AtriaDebugLog("ATRIADBG offline_sync status=coalesced reason=%@ detail=fresh_history_owner_cutover_pending force=%d explicit=%d",
                          reason,
                          force ? 1 : 0,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        return startOfflineHistoricalSync(
            reason: reason,
            force: force,
            explicitRequest: explicitHistoricalRequest,
            connectedChunkedBackfill: connectedChunkedBackfill,
            attemptAt: now,
            rawOnlyGapFingerprint: rawOnlyDisconnectedRecovery ? gapFingerprint : nil,
            gapFingerprint: gapFingerprint,
            freshOwnerCutoverCompleted: freshOwnerCutoverCompleted
        )
    }

    private func armHistoryCapabilityQualification(for peripheralID: String?) {
        guard let peripheral,
              peripheral.state == .connected,
              peripheral.identifier.uuidString == peripheralID else { return }
        historyCapabilityQualificationPeripheralID = peripheral.identifier
        if serviceDiscoveryCallbackObservedForConnection,
           !historyCapabilityQualificationDiscoveryIssued {
            historyCapabilityQualificationDiscoveryIssued = true
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG history_capability status=qualification_discovery_requested trigger=completed_service_callback peripheral=%@",
                          peripheral.identifier.uuidString)
            return
        }
        guard historyCapabilityQualificationFallbackTask == nil else { return }
        historyCapabilityQualificationFallbackTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(5))
            guard let self, let peripheral,
                  !Task.isCancelled,
                  self.historyCapabilityQualificationPeripheralID == peripheral.identifier,
                  !self.historyCapabilityQualificationDiscoveryIssued,
                  peripheral.state == .connected else { return }
            self.historyCapabilityQualificationDiscoveryIssued = true
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG history_capability status=qualification_discovery_requested trigger=bounded_callback_fallback peripheral=%@",
                          peripheral.identifier.uuidString)
        }
    }

    private func handleHistoryCapabilityServiceDiscovery(
        peripheral: CBPeripheral,
        serviceUUIDs: [CBUUID]
    ) {
        serviceDiscoveryCallbackObservedForConnection = true
        guard historyCapabilityQualificationPeripheralID == peripheral.identifier else {
            return
        }
        if serviceUUIDs.contains(Self.UUIDs.strapService) {
            historyCapabilityQualificationFallbackTask?.cancel()
            historyCapabilityQualificationFallbackTask = nil
            historyCapabilityQualificationPeripheralID = nil
            historyCapabilityQualificationDiscoveryIssued = false
            if strapModel == .unknown, !debugForceUnknownStrapGeneration {
                strapModel = .strap4Class
            }
            AtriaDebugLog("ATRIADBG history_capability status=qualified model=strap4Class source=serialized_service_callback action=resume_pending_recovery")
            scheduleRangeLossBackfillIfNeeded(reason: "history_capability_qualified")
        } else if !historyCapabilityQualificationDiscoveryIssued {
            historyCapabilityQualificationDiscoveryIssued = true
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG history_capability status=qualification_discovery_requested trigger=nonproprietary_service_callback peripheral=%@",
                          peripheral.identifier.uuidString)
        }
    }

    /// Close the current live evidence boundary, then intentionally release the
    /// connected owner. `didDisconnect` hands the preserved explicit request to
    /// the already-audited disconnected recovery path, which creates the fresh
    /// service/notification epoch. Failure to prove durability leaves live BLE
    /// untouched; there is no timeout-driven disconnect and no retry loop.
    private func beginFreshHistoryOwnerCutover(reason: String) {
        guard !freshHistoryOwnerCutoverPending,
              let connectedPeripheral = peripheral,
              connectedPeripheral.state == .connected else { return }
        freshHistoryOwnerCutoverPending = true
        freshHistoryOwnerBoundaryFailureLatched = false
        let peripheralIdentifier = connectedPeripheral.identifier
        let boundarySessionID = liveSessionID
        let boundarySessionSampleCount = session.count
        let boundaryRRCount = rrArchive.count
        let boundaryResearch = ResearchAggregates(
            sensorProbeFrames: researchProbeFrameCount,
            spo2CandidateFrames: researchProbeOxygenCandidateFrames,
            skinTempCandidateFrames: researchProbeTemperatureCandidateFrames,
            skinTempCandidateValueSum: researchProbeTemperatureCandidateValueSum,
            skinTempCandidateValueCount: researchProbeTemperatureCandidateValueCount,
            strapSteps: strapStepResearchCount,
            strapRawSteps: strapStepResearchPeakCount,
            strapDeviceTimestamp: strapStepResearchDeviceTimestamp,
            strapStepState: strapStepResearchState,
            gyroCadenceResearchSteps: currentGyroCadenceResearchSessionSteps()
        )
        let boundaryRawSteps = strapStepResearchPeakCount
        let startedAt = Date()
        // A full active journal can legitimately queue behind session-store and
        // recovered-projection I/O on launch. Five seconds repeatedly failed
        // before the already-running atomic write could publish its counters.
        // Keep live HR untouched while waiting, but allow one bounded 30-second
        // window for the fixed target snapshot to become durable.
        let deadline = startedAt.addingTimeInterval(30)
        flushActiveSessionJournal(reason: "fresh_history_owner_cutover_\(reason)")
        persistStrapStepLedgerIfNeeded(
            reason: "fresh_history_owner_cutover_\(reason)",
            force: true
        )
        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_boundary_started reason=%@ action=await_atomic_fsync_then_single_cutover",
                      reason)
        Task { @MainActor [weak self] in
            guard let self else { return }
            while Date() < deadline {
                guard self.freshHistoryOwnerCutoverPending,
                      self.peripheral?.identifier == peripheralIdentifier,
                      connectedPeripheral.state == .connected else { return }
                let sessionIdentityValid = self.liveSessionID == boundarySessionID
                let journalDurable = sessionIdentityValid
                    && self.lastActiveJournalSavedSessionSampleCount
                        >= boundarySessionSampleCount
                    && self.lastActiveJournalSavedRRArchiveCount
                        >= boundaryRRCount
                    && Self.researchAggregates(
                        self.lastActiveJournalSavedResearchAggregates,
                        cover: boundaryResearch
                    )
                let stepsDurable = !self.strapStepLedgerRestoreInFlight
                    && !self.strapStepLedgerSaveInFlight
                    && self.lastStrapStepLedgerSavedRawSteps
                        >= boundaryRawSteps
                if journalDurable && stepsDurable {
                    AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_boundary_durable reason=%@ target_samples=%d target_rr=%d target_raw_steps=%d trailing_samples=%d durability=atomic_fsync action=single_intentional_disconnect_and_record_trailing_gap",
                                  reason,
                                  boundarySessionSampleCount,
                                  boundaryRRCount,
                                  boundaryRawSteps,
                                  max(0, self.session.count - boundarySessionSampleCount))
                    self.freshHistoryOwnerBoundaryFailureLatched = false
                    self.cancelPeripheralConnection(
                        connectedPeripheral,
                        reason: "explicit_history_fresh_owner_cutover"
                    )
                    return
                }
                if !self.activeJournalSaveInFlight {
                    self.flushActiveSessionJournal(
                        reason: "fresh_history_owner_cutover_tail_\(reason)"
                    )
                }
                if !self.strapStepLedgerRestoreInFlight,
                   !self.strapStepLedgerSaveInFlight {
                    self.persistStrapStepLedgerIfNeeded(
                        reason: "fresh_history_owner_cutover_tail_\(reason)",
                        force: true
                    )
                }
                try? await Task.sleep(for: .milliseconds(50))
            }
            guard self.freshHistoryOwnerCutoverPending else { return }
            self.freshHistoryOwnerCutoverPending = false
            self.freshHistoryOwnerBoundaryFailureLatched = true
            AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_boundary_failed reason=%@ elapsed_ms=%d session_match=%d target_samples=%d saved_samples=%d target_rr=%d saved_rr=%d target_raw_steps=%d saved_raw_steps=%d journal_in_flight=%d step_restore=%d step_in_flight=%d action=keep_live_link_retain_explicit_request_latch_no_packet_retry",
                          reason,
                          Int(Date().timeIntervalSince(startedAt) * 1_000),
                          self.liveSessionID == boundarySessionID ? 1 : 0,
                          boundarySessionSampleCount,
                          self.lastActiveJournalSavedSessionSampleCount,
                          boundaryRRCount,
                          self.lastActiveJournalSavedRRArchiveCount,
                          boundaryRawSteps,
                          self.lastStrapStepLedgerSavedRawSteps,
                          self.activeJournalSaveInFlight ? 1 : 0,
                          self.strapStepLedgerRestoreInFlight ? 1 : 0,
                          self.strapStepLedgerSaveInFlight ? 1 : 0)
        }
    }

    nonisolated static func researchAggregates(
        _ saved: ResearchAggregates,
        cover target: ResearchAggregates
    ) -> Bool {
        saved.sensorProbeFrames >= target.sensorProbeFrames
            && saved.spo2CandidateFrames >= target.spo2CandidateFrames
            && saved.skinTempCandidateFrames >= target.skinTempCandidateFrames
            && saved.skinTempCandidateValueSum >= target.skinTempCandidateValueSum
            && saved.skinTempCandidateValueCount >= target.skinTempCandidateValueCount
            && saved.strapSteps >= target.strapSteps
            && saved.strapRawSteps >= target.strapRawSteps
            && saved.gyroCadenceResearchSteps >= target.gyroCadenceResearchSteps
            && (target.strapDeviceTimestamp == nil
                || saved.strapDeviceTimestamp != nil)
    }

    /// Gives iOS one bounded opportunity to establish the strap bond before
    /// standard HR is available. The only protocol mutation reachable here is
    /// GET_DATA_RANGE 22/00 with response. It does not activate the history
    /// phase fence, serve/abort history, acknowledge data, or grant live proof.
    func requestOnboardingPairingPreflightIfNeeded() {
        guard let connectedPeripheral = peripheral,
              connectedPeripheral.state == .connected,
              let connectedAt else { return }
        let connectionIdentity = "\(connectedPeripheral.identifier.uuidString)|\(connectedAt.timeIntervalSince1970)"
        let alreadyAttempted = onboardingPairingPreflightAttemptedConnection
            == connectionIdentity
        guard Self.shouldAttemptOnboardingPairingPreflight(
            linkConnected: status == .connected,
            currentConnectionHasFreshHeartRate: currentConnectionHasFreshHeartRate,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            historyTransportActive: offlineHistoricalSyncInProgress
                || historyOnlyProbeEnabled
                || historyOnlyProbeMode
                || readOnlyHistoryCaptureRequested
                || readOnlyHistoryCaptureActive,
            freshHistoryOwnerCutoverPending: freshHistoryOwnerCutoverPending,
            preflightInFlight: onboardingPairingPreflightInFlight,
            alreadyAttemptedForConnection: alreadyAttempted
        ) else { return }

        onboardingPairingPreflightAttemptedConnection = connectionIdentity
        onboardingPairingPreflightGeneration &+= 1
        let generation = onboardingPairingPreflightGeneration
        onboardingPairingPreflightInFlight = true
        onboardingPairingPreflightDiscoveryRequested = true
        onboardingPairingPreflightSequence = nil
        onboardingPairingPreflightWriteResult = nil
        connectedPeripheral.discoverServices([Self.UUIDs.strapService])
        AtriaDebugLog("ATRIADBG onboarding_pairing status=armed generation=%llu peripheral=%@ command_allowlist=2200 mutation=pairing_preflight_only",
                      generation,
                      connectedPeripheral.identifier.uuidString)

        onboardingPairingPreflightTask?.cancel()
        onboardingPairingPreflightTask = Task { @MainActor [weak self] in
            guard let self else { return }
            // Discovery and any prior single-flight WR callback get a bounded
            // chance to settle. No competing write is cancelled or displaced.
            for _ in 0..<75 {
                guard !Task.isCancelled,
                      self.onboardingPairingPreflightInFlight,
                      self.onboardingPairingPreflightGeneration == generation,
                      self.peripheral?.identifier == connectedPeripheral.identifier,
                      self.peripheral?.state == .connected else {
                    self.finishOnboardingPairingPreflight(
                        generation: generation,
                        reason: "transport_interrupted"
                    )
                    return
                }
                if self.txCharacteristic != nil,
                   self.writeCompletionLedger.pending.isEmpty {
                    break
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard self.txCharacteristic != nil,
                  self.writeCompletionLedger.pending.isEmpty else {
                self.finishOnboardingPairingPreflight(
                    generation: generation,
                    reason: "tx_or_single_flight_unavailable"
                )
                return
            }

            var result = await self.sendOnboardingPairingPreflightRange(
                generation: generation
            )
            var retriesAlreadyIssued = 0
            if AtriaBLEReadOnlyHistoryCapturePolicy.permitsRangeRetry(
                after: result,
                retriesAlreadyIssued: retriesAlreadyIssued
            ) {
                retriesAlreadyIssued += 1
                AtriaDebugLog("ATRIADBG onboarding_pairing status=security_required generation=%llu action=bounded_pairing_settle_then_single_2200_retry",
                              generation)
                try? await Task.sleep(for: .seconds(
                    AtriaBLEReadOnlyHistoryCapturePolicy.pairingSettle
                ))
                guard !Task.isCancelled,
                      self.onboardingPairingPreflightInFlight,
                      self.onboardingPairingPreflightGeneration == generation,
                      self.peripheral?.identifier == connectedPeripheral.identifier,
                      self.peripheral?.state == .connected else {
                    self.finishOnboardingPairingPreflight(
                        generation: generation,
                        reason: "pairing_settle_completed_or_interrupted"
                    )
                    return
                }
                result = await self.sendOnboardingPairingPreflightRange(
                    generation: generation
                )
            }
            self.finishOnboardingPairingPreflight(
                generation: generation,
                reason: "range_write_\(result)"
            )
        }
    }

    private func sendOnboardingPairingPreflightRange(
        generation: UInt64
    ) async -> AtriaBLEReadOnlyHistoryCapturePolicy.WriteConfirmationResult {
        guard onboardingPairingPreflightInFlight,
              onboardingPairingPreflightGeneration == generation,
              !offlineHistoricalSyncInProgress,
              !historyOnlyProbeEnabled,
              !historyOnlyProbeMode,
              !readOnlyHistoryCaptureRequested,
              !readOnlyHistoryCaptureActive else { return .interrupted }
        onboardingPairingPreflightSequence = nil
        onboardingPairingPreflightWriteResult = nil
        guard sendCommand(
            Cmd.getDataRange,
            [0x00],
            mode: .withResponse,
            onboardingPairingPreflight: true
        ), let expected = writeCompletionLedger.pending.first,
           expected.command == Cmd.getDataRange,
           expected.payload == [0x00] else { return .failed }
        onboardingPairingPreflightSequence = expected.sequence
        AtriaDebugLog("ATRIADBG onboarding_pairing status=range_requested generation=%llu sequence=%d command=2200 mode=wr history_owner=0 live_authority=0",
                      generation,
                      Int(expected.sequence))

        let attempts = AtriaBLEReadOnlyHistoryCapturePolicy
            .writeConfirmationPollAttempts(
                opcode: Cmd.getDataRange,
                pollInterval: AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            )
        for _ in 0..<attempts {
            if let result = onboardingPairingPreflightWriteResult {
                return result
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  onboardingPairingPreflightInFlight,
                  onboardingPairingPreflightGeneration == generation else {
                return .interrupted
            }
        }
        return .timedOut
    }

    private func finishOnboardingPairingPreflight(
        generation: UInt64,
        reason: String
    ) {
        guard onboardingPairingPreflightGeneration == generation else { return }
        onboardingPairingPreflightInFlight = false
        onboardingPairingPreflightDiscoveryRequested = false
        onboardingPairingPreflightSequence = nil
        onboardingPairingPreflightWriteResult = nil
        onboardingPairingPreflightTask = nil
        AtriaDebugLog("ATRIADBG onboarding_pairing status=finished generation=%llu reason=%@ action=await_genuine_current_epoch_hr",
                      generation,
                      reason)
    }

    /// Advance the already-armed explicit generation on its one fresh link.
    /// Service discovery is the only radio mutation here; TX discovery and the
    /// existing notification-readiness gate remain solely responsible for
    /// starting 22/00, so no protocol command can precede confirmed RX/stream5.
    private func resumeFreshHistoryOwnerConnectionIfNeeded(
        peripheral: CBPeripheral
    ) -> Bool {
        guard let generation = freshHistoryOwnerConnectionGeneration else {
            return false
        }
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else {
            freshHistoryOwnerConnectionGeneration = nil
            AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_resume_rejected generation=%llu current=%llu active=%d action=normal_live_discovery",
                          generation,
                          offlineHistoricalSyncGeneration,
                          offlineHistoricalSyncInProgress ? 1 : 0)
            return false
        }
        freshHistoryOwnerConnectionGeneration = nil
        // The phase was already activated when the explicit request acquired
        // its generation, before the live-owner cutover. Re-activate its
        // ownership token on the fresh CoreBluetooth connection without
        // changing the proven RX + stream-5 listener or command profile.
        let usesExplicitHistoryProfile = historyTransportPhaseFence.snapshot()
            .usesExplicitHistoryProfile
        historyOnlyProbeEnabled = true
        _ = historyTransportPhaseFence.activate(
            generation: generation,
            usesExplicitHistoryProfile: usesExplicitHistoryProfile
        )
        peripheral.discoverServices(Self.UUIDs.productionHistoryServices)
        noteOfflineHistoricalSyncProgress(
            generation: generation,
            reason: "fresh_owner_connected"
        )
        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_resumed generation=%llu action=discover_history_plus_standard_hr_battery_then_await_notification_readiness commands=0",
                      generation)
        return true
    }

    /// Starts (or joins) a historical drain and suspends the caller until that
    /// exact generation reaches HISTORY_COMPLETE. Background task owners use
    /// this instead of starting an asynchronous offload and immediately telling
    /// iOS that their work finished.
    func requestOfflineHistoricalSyncAwaitingCompletion(
        reason: String,
        force: Bool = false,
        admitAutomaticConnectedHandoffIfEligible: Bool = false
    ) async -> Bool {
        let automaticConnectedHandoff = admitAutomaticConnectedHandoffIfEligible
            && automaticConnectedHistoricalHandoffIsEligible(now: Date())
        let started = requestOfflineHistoricalSyncIfNeeded(
            reason: reason,
            force: force || automaticConnectedHandoff,
            allowConnectedAutomaticHandoff: automaticConnectedHandoff
        )
        guard started || offlineHistoricalSyncInProgress else { return false }
        let generation = offlineHistoricalSyncGeneration
        while lastCompletedHistoricalSyncGeneration < generation {
            guard !Task.isCancelled else { return false }
            try? await Task.sleep(for: .milliseconds(250))
        }
        guard lastCompletedHistoricalSyncGeneration == generation else { return false }
        let onboardingRequest = reason == "onboarding_initial_import"
        guard onboardingRequest
                ? lastCompletedHistoricalSyncHasOnboardingAuthority
                : lastCompletedHistoricalSyncReachedTerminal else { return false }
        let receiptsRequired = historicalConsumerReceiptRequiredGenerations
            .contains(generation)
        guard onboardingRequest, receiptsRequired else {
            return true
        }
        // Full-drain/exact-request authorities publish five durable typed
        // receipts asynchronously after live ownership returns. Onboarding may
        // not turn that scheduled work into success. A failure/defer ends the
        // in-flight lease without a receipt and therefore fails closed here.
        while historicalConsumerMaterializationInFlight,
              !historicalConsumerReceiptedGenerations.contains(generation) {
            guard !Task.isCancelled else { return false }
            try? await Task.sleep(for: .milliseconds(250))
        }
        return Self.onboardingConsumerReceiptsAreComplete(
            required: receiptsRequired,
            receipted: historicalConsumerReceiptedGenerations.contains(generation)
        )
    }

    nonisolated static func onboardingHistoryTransportAuthorityIsValid(
        terminalReceived: Bool,
        durableTerminalAuthority: Bool,
        verifiedEmptyCursor: Bool
    ) -> Bool {
        (terminalReceived && durableTerminalAuthority) || verifiedEmptyCursor
    }

    nonisolated static func onboardingConsumerReceiptsAreComplete(
        required: Bool,
        receipted: Bool
    ) -> Bool {
        !required || receipted
    }

    /// One stateful adapter around the pure connected-handoff policy. Both the
    /// foreground retry scheduler and BGProcessing must evaluate exactly the
    /// same live-link, durable-gap, workout, freshness, age and cooldown facts;
    /// otherwise a suspended timer can starve the only iOS execution window
    /// capable of draining a connected strap backlog.
    private func automaticConnectedHistoricalHandoffIsEligible(
        now: Date
    ) -> Bool {
        // A genuine reconnect is the recovery opportunity for an overnight
        // gap. Do not blanket-block it by clock hour: the policy below still
        // requires a stable current epoch, fresh accepted HR, no active
        // workout, an exact durable gap, a verified decoder, and cooldown.
        // Those gates make one journaled fresh-owner handoff safe while also
        // allowing the strap to fill a sleep-time outage.
        let defaults = UserDefaults.standard
        let currentPeripheralID = peripheral?.identifier.uuidString
        let verifiedPeripheralID = defaults.string(
            forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID
        )
        let previouslyVerified = currentPeripheralID != nil
            && currentPeripheralID == verifiedPeripheralID
        let effectiveModel: AtriaStrapModel = {
            if strapModel == .unknown,
               peripheral?.services?.contains(where: {
                   $0.uuid == Self.UUIDs.strapService
               }) == true {
                return .strap4Class
            }
            return strapModel
        }()
        let verifiedMetricRecovery = Self
            .supportsVerifiedHistoricalTransactionRecovery(
                model: effectiveModel,
                previouslyVerified: previouslyVerified,
                fullDrainGapRecoveryEnabled:
                    Self.productionHistoricalFullDrainGapRecoveryEnabled
            )
        // An ambiguous legacy coalesced envelope is intentionally retained as
        // unresolved evidence, but it cannot identify which seconds the strap
        // should recover. Only a selectable exact ledger candidate (or the
        // older explicit start/end fallback) may start an automatic transport.
        // Using `hasPendingWindows` here made quarantined legacy state wake the
        // strap forever as a raw-only drain with no possible settlement.
        let hasExactGapWindow = AtriaHistoricalGapLedger
            .oldestClosedRecoveryCandidate(defaults: defaults) != nil
            || (defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart) != nil
            && defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd) != nil)
        let requestedAtValue = defaults.object(
            forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt
        )
        let requestedAt = (requestedAtValue as? Date)
            ?? (requestedAtValue as? Double).map(Date.init(timeIntervalSince1970:))
        let lastAttemptValue = defaults.object(
            forKey: OfflineSyncDefaults.lastAttemptAt
        )
        let lastAttemptAt = (lastAttemptValue as? Date)
            ?? (lastAttemptValue as? Double).map(Date.init(timeIntervalSince1970:))
        return Self.shouldAttemptAutomaticConnectedHistoricalHandoff(
            linkConnected: peripheral?.state == .connected,
            exactGapPending: hasExactGapWindow,
            verifiedMetricRecovery: verifiedMetricRecovery,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            syncInProgress: offlineHistoricalSyncInProgress,
            connectedAt: connectedAt,
            hasContact: hasContact,
            acceptedSampleCount: session.count,
            lastAcceptedHRAt: lastAcceptedHRAt,
            requestedAt: requestedAt,
            lastAttemptAt: lastAttemptAt,
            now: now,
            stableConnectionInterval: automaticConnectedHistoryStableInterval,
            acceptedFreshnessWindow: offlineSyncLiveAcceptedHRProtectionWindow,
            minimumSamples: autoSaveMinSamples,
            minimumGapAge: rangeLossBackfillReadyForceInterval,
            attemptCooldown: automaticConnectedHistoryAttemptCooldown
        )
    }

    private func recordMotionHandshakeEvidence(event: String, detail: String = "") {
        guard let diagnostic = motionHandshakeDiagnostic else { return }
        let defaults = UserDefaults.standard
        let now = Date().timeIntervalSince1970
        let sequence = defaults.integer(forKey: "atria.motionHandshake.eventSequence") + 1
        defaults.set(sequence, forKey: "atria.motionHandshake.eventSequence")
        defaults.set(event, forKey: "atria.motionHandshake.lastEvent")
        defaults.set(detail, forKey: "atria.motionHandshake.lastDetail")
        defaults.set(now, forKey: "atria.motionHandshake.lastEventAt")
        defaults.set(now, forKey: "atria.motionHandshake.\(event)At")
        AtriaDebugLog("ATRIADBG motion_handshake run=%@ seq=%d event=%@ detail=%@ unix=%.3f",
                      diagnostic.runID, sequence, event, detail, now)
    }

    /// Establish the public WHOOP response/event/data notification profile in
    /// deterministic order. CoreBluetooth can otherwise complete three CCCD
    /// writes in an arbitrary order, which makes a disconnect impossible to
    /// attribute. Every characteristic is requested at most once per fresh
    /// diagnostic connection.
    private func beginMotionHandshakeNotificationProfile(
        peripheral: CBPeripheral,
        characteristics: [CBCharacteristic]
    ) {
        guard let diagnostic = motionHandshakeDiagnostic,
              peripheral.state == .connected else { return }
        motionHandshakeProfileCharacteristics = Dictionary(
            uniqueKeysWithValues: characteristics.map { ($0.uuid, $0) }
        )
        motionHandshakeRequestedNotifyUUIDs.removeAll()
        motionHandshakeConfirmedNotifyUUIDs = Set(
            characteristics.compactMap { characteristic in
                characteristic.isNotifying ? characteristic.uuid : nil
            }
        )
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: diagnostic.useResponseEventDataProfile
        )
        let missing = required.filter {
            motionHandshakeProfileCharacteristics[$0] == nil
        }
        guard missing.isEmpty else {
            recordMotionHandshakeEvidence(
                event: "notification_profile_missing",
                detail: missing.map(\.uuidString).joined(separator: ",")
            )
            return
        }
        recordMotionHandshakeEvidence(
            event: "notification_profile_discovered",
            detail: required.map(\.uuidString).joined(separator: ",")
        )
        advanceMotionHandshakeNotificationProfile(peripheral: peripheral)
    }

    private func advanceMotionHandshakeNotificationProfile(peripheral: CBPeripheral) {
        guard let diagnostic = motionHandshakeDiagnostic,
              peripheral.state == .connected else { return }
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: diagnostic.useResponseEventDataProfile
        )
        if let nextUUID = required.first(where: {
            !motionHandshakeConfirmedNotifyUUIDs.contains($0)
                && !motionHandshakeRequestedNotifyUUIDs.contains($0)
        }), let characteristic = motionHandshakeProfileCharacteristics[nextUUID] {
            guard characteristic.properties.contains(.notify) else {
                recordMotionHandshakeEvidence(
                    event: "notification_profile_unsupported",
                    detail: nextUUID.uuidString
                )
                return
            }
            motionHandshakeRequestedNotifyUUIDs.insert(nextUUID)
            recordMotionHandshakeEvidence(
                event: "notification_profile_request",
                detail: nextUUID.uuidString
            )
            peripheral.setNotifyValue(true, for: characteristic)
            return
        }
        guard required.allSatisfy(motionHandshakeConfirmedNotifyUUIDs.contains) else {
            return
        }
        recordMotionHandshakeEvidence(
            event: "notification_profile_confirmed",
            detail: required.map(\.uuidString).joined(separator: ",")
        )
        if diagnostic.sendR10IMUSequence {
            // Public WHOOP implementations send the stream commands as soon as
            // response/event/data CCCDs are confirmed. Waiting for the later
            // standard-HR addition left the strap in a subscribed-but-unarmed
            // state and the physical link closed at 13.25 seconds before any
            // command could be evaluated.
            sendMotionHandshakeR10IMUSequenceIfReady()
        }
        scheduleMotionHandshakeStandardHRAddition(peripheral: peripheral)
    }

    private func handleMotionHandshakeNotificationState(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        error: Error?
    ) {
        guard let diagnostic = motionHandshakeDiagnostic else { return }
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: diagnostic.useResponseEventDataProfile
        )
        guard required.contains(characteristic.uuid) else {
            if characteristic.uuid == Self.UUIDs.heartRateMeasure {
                if let error {
                    recordMotionHandshakeEvidence(
                        event: "hr_notify_error",
                        detail: error.localizedDescription
                    )
                } else if characteristic.isNotifying {
                    recordMotionHandshakeEvidence(event: "hr_notify_active")
                    if diagnostic.sendR10IMUSequence {
                        sendMotionHandshakeR10IMUSequenceIfReady()
                    } else {
                        sendMotionHandshakeSingleR10ActivationIfReady()
                    }
                }
            }
            return
        }
        if let error {
            recordMotionHandshakeEvidence(
                event: "notification_profile_error",
                detail: "\(characteristic.uuid.uuidString)_\(error.localizedDescription)"
            )
            return
        }
        guard characteristic.isNotifying else {
            recordMotionHandshakeEvidence(
                event: "notification_profile_inactive",
                detail: characteristic.uuid.uuidString
            )
            return
        }
        motionHandshakeConfirmedNotifyUUIDs.insert(characteristic.uuid)
        recordMotionHandshakeEvidence(
            event: "notification_profile_active",
            detail: characteristic.uuid.uuidString
        )
        advanceMotionHandshakeNotificationProfile(peripheral: peripheral)
    }

    private func scheduleMotionHandshakeStandardHRAddition(peripheral: CBPeripheral) {
        guard let diagnostic = motionHandshakeDiagnostic,
              motionHandshakeAddHRTask == nil else { return }
        recordMotionHandshakeEvidence(event: "stream5_notify_confirmed",
                                      detail: "add_hr_after_\(Int(diagnostic.addHRDelay))s")
        motionHandshakeAddHRTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(diagnostic.addHRDelay))
            guard let self, !Task.isCancelled,
                  let peripheral, peripheral.state == .connected else { return }
            self.recordMotionHandshakeEvidence(event: "hr_service_discovery_requested")
            peripheral.discoverServices([Self.UUIDs.heartRateService])
        }
    }

    private func sendMotionHandshakeSingleR10ActivationIfReady() {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard let diagnostic = motionHandshakeDiagnostic,
              diagnostic.sendSingleR10Activation,
              !motionHandshakeActivationSent else { return }
        let defaults = UserDefaults.standard
        defaults.set(defaults.integer(forKey: "atria.motionHandshake.activationAttempts") + 1,
                     forKey: "atria.motionHandshake.activationAttempts")
        guard let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            recordMotionHandshakeEvidence(event: "activation_not_ready",
                                          detail: "missing_connected_wwr_tx")
            return
        }

        // Command 0x3F is explicitly named sendR10R11Realtime in the locally
        // validated protocol map. Payload 0x01 enables that stream. This bypass
        // is deliberately narrower than sendCommand: exactly one 3F/01 WWR is
        // possible, only after the third launch-consent switch and active HR.
        motionHandshakeActivationSent = true
        let sequence = cmdSeq
        cmdSeq &+= 1
        let frame = encodeFrame([Packet.command, sequence, Cmd.sendR10R11Realtime, 0x01])
        let now = Date().timeIntervalSince1970
        defaults.set(now, forKey: "atria.motionHandshake.activationSentAt")
        defaults.set(Int(sequence), forKey: "atria.motionHandshake.activationSequence")
        defaults.set(defaults.integer(forKey: ProtocolDefaults.packets),
                     forKey: "atria.motionHandshake.activationProtocolPacketsBaseline")
        defaults.set(defaults.integer(forKey: ProtocolDefaults.imuFrames),
                     forKey: "atria.motionHandshake.activationIMUFramesBaseline")
        defaults.set(defaults.integer(forKey: "atria.motionHandshake.activationSentCount") + 1,
                     forKey: "atria.motionHandshake.activationSentCount")
        recordMotionHandshakeEvidence(event: "activation_3f01_sent",
                                      detail: "wwr_seq_\(sequence)_bytes_\(frame.count)")
        peripheral.writeValue(frame, for: txCharacteristic, type: .withoutResponse)
    }

    /// Hardware-research profile used only behind four diagnostic launch
    /// consents: once response/event/data notifications are confirmed, send
    /// one paced 3F/01 then one 6A/01. Standard HR is added later as an
    /// independent coexistence probe. Optical 6B is omitted to
    /// reduce airtime because exact steps need R10 IMU, not raw optical data.
    private func sendMotionHandshakeR10IMUSequenceIfReady() {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard let diagnostic = motionHandshakeDiagnostic,
              diagnostic.useResponseEventDataProfile,
              diagnostic.sendR10IMUSequence,
              motionHandshakeCommandSequenceTask == nil,
              !motionHandshakeActivationSent else { return }
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: true
        )
        guard required.allSatisfy(motionHandshakeConfirmedNotifyUUIDs.contains),
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            recordMotionHandshakeEvidence(
                event: "r10_imu_sequence_not_ready",
                detail: "profile_or_tx_missing"
            )
            return
        }
        let runSequenceKey = "atria.motionHandshake.\(diagnostic.runID).r10IMUSequenceSent"
        guard !UserDefaults.standard.bool(forKey: runSequenceKey) else {
            recordMotionHandshakeEvidence(
                event: "r10_imu_sequence_suppressed",
                detail: "already_sent_for_run"
            )
            return
        }
        UserDefaults.standard.set(true, forKey: runSequenceKey)
        motionHandshakeActivationSent = true
        motionHandshakeCommandSequenceTask = Task { @MainActor [weak self, weak peripheral] in
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected else { return }
            let defaults = UserDefaults.standard
            let startedAt = Date()
            defaults.set(startedAt.timeIntervalSince1970,
                         forKey: "atria.motionHandshake.r10IMUSequenceStartedAt")
            defaults.set(defaults.integer(forKey: "atria.motionHandshake.r10IMUSequenceCount") + 1,
                         forKey: "atria.motionHandshake.r10IMUSequenceCount")

            let r10Sequence = self.cmdSeq
            self.cmdSeq &+= 1
            let r10Frame = encodeFrame([
                Packet.command, r10Sequence, Cmd.sendR10R11Realtime, 0x01
            ])
            self.recordMotionHandshakeEvidence(
                event: "activation_3f01_sent",
                detail: "wwr_seq_\(r10Sequence)_bytes_\(r10Frame.count)"
            )
            peripheral.writeValue(r10Frame, for: txCharacteristic, type: .withoutResponse)

            try? await Task.sleep(for: .milliseconds(120))
            guard !Task.isCancelled, peripheral.state == .connected else { return }
            let imuSequence = self.cmdSeq
            self.cmdSeq &+= 1
            let imuFrame = encodeFrame([
                Packet.command, imuSequence, Cmd.toggleIMUMode, 0x01
            ])
            self.recordMotionHandshakeEvidence(
                event: "activation_6a01_sent",
                detail: "wwr_seq_\(imuSequence)_bytes_\(imuFrame.count)"
            )
            peripheral.writeValue(imuFrame, for: txCharacteristic, type: .withoutResponse)
            defaults.set(Date().timeIntervalSince1970,
                         forKey: "atria.motionHandshake.r10IMUSequenceCompletedAt")
            self.motionHandshakeCommandSequenceTask = nil
        }
    }

    /// Production form of the physically-proven response/event/data profile.
    /// It is intentionally a separate owner from the launch-argument diagnostic:
    /// one fresh link, one ordered CCCD pass, one command pair, no repair loop.
    private func beginProtectedR10ResponseEventDataProfile(
        peripheral: CBPeripheral,
        characteristics: [CBCharacteristic],
        error: Error?
    ) {
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !historyOnlyProbeMode,
              protectedR10CleanOwner == .protectedV9,
              protectedR10CleanOwnerState == .protectedLaunchPending,
              protectedR10InitialProfilePeripheralID == peripheral.identifier,
              peripheral.state == .connected else { return }
        if let error {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_discovery_error_\(error.localizedDescription)"
            )
            return
        }

        protectedR10ProfileCharacteristics = Dictionary(
            uniqueKeysWithValues: characteristics.map { ($0.uuid, $0) }
        )
        protectedR10ProfileRequestedNotifyUUIDs.removeAll()
        protectedR10ProfileConfirmedNotifyUUIDs = Set(
            characteristics.compactMap { $0.isNotifying ? $0.uuid : nil }
        )
        guard let tx = protectedR10ProfileCharacteristics[Self.UUIDs.strapTX],
              tx.properties.contains(.writeWithoutResponse) else {
            persistProtectedR10CleanOwnerFallback(reason: "response_event_data_tx_missing")
            return
        }
        txCharacteristic = tx
        dbgTxReady = true

        let missing = Self.protectedR10ResponseEventDataNotifyOrder.filter {
            protectedR10ProfileCharacteristics[$0] == nil
        }
        guard missing.isEmpty else {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_characteristic_missing_\(missing.map(\.uuidString).joined(separator: "_"))"
            )
            return
        }
        let unsupported = Self.protectedR10ResponseEventDataNotifyOrder.filter {
            protectedR10ProfileCharacteristics[$0]?.properties.contains(.notify) != true
        }
        guard unsupported.isEmpty else {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_notify_unsupported_\(unsupported.map(\.uuidString).joined(separator: "_"))"
            )
            return
        }

        let startedAt = Date()
        let defaults = UserDefaults.standard
        defaults.set(ProtectedR10CleanOwnerState.proving.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.set("clean_owner_v9_profile_subscribing",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        scheduleProtectedR10CleanOwnerProofTimeout(startedAt: startedAt)
        advanceProtectedR10ResponseEventDataProfile(peripheral: peripheral)
    }

    private func advanceProtectedR10ResponseEventDataProfile(peripheral: CBPeripheral) {
        guard protectedR10ResponseEventDataProofIsActive,
              peripheral.state == .connected else { return }
        if let nextUUID = Self.protectedR10ResponseEventDataNotifyOrder.first(where: {
            !protectedR10ProfileConfirmedNotifyUUIDs.contains($0)
                && !protectedR10ProfileRequestedNotifyUUIDs.contains($0)
        }), let characteristic = protectedR10ProfileCharacteristics[nextUUID] {
            protectedR10ProfileRequestedNotifyUUIDs.insert(nextUUID)
            peripheral.setNotifyValue(true, for: characteristic)
            incrementRadioCounter(RadioDefaults.customNotifyEnabled,
                                  reason: "protected_v9_initial_profile")
            dbgSubsReq += 1
            AtriaDebugLog("ATRIADBG protected_r10 status=profile_subscribe_requested owner=v9 ch=%@ action=ordered_once",
                          nextUUID.uuidString)
            return
        }
        guard Self.protectedR10ResponseEventDataNotifyOrder.allSatisfy(
            protectedR10ProfileConfirmedNotifyUUIDs.contains
        ) else { return }
        sendProtectedR10ResponseEventDataSequenceIfReady(peripheral: peripheral)
    }

    @discardableResult
    private func handleProtectedR10ResponseEventDataNotificationState(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        error: Error?
    ) -> Bool {
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              protectedR10CleanOwner == .protectedV9,
              Self.protectedR10ResponseEventDataNotifyOrder.contains(characteristic.uuid),
              (protectedR10CleanOwnerState == .proving
                || protectedR10CleanOwnerState == .qualified) else { return false }
        if let error {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_notify_error_\(characteristic.uuid.uuidString)_\(error.localizedDescription)"
            )
            return true
        }
        guard characteristic.isNotifying else {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_notify_inactive_\(characteristic.uuid.uuidString)"
            )
            return true
        }
        protectedR10ProfileConfirmedNotifyUUIDs.insert(characteristic.uuid)
        activeProprietaryNotifyUUIDs.insert(characteristic.uuid)
        if characteristic.uuid == Self.UUIDs.strapStream5 {
            strapStream5NotifyConfirmed = true
            markPassiveR10SubscriptionConfirmed()
        }
        advanceProtectedR10ResponseEventDataProfile(peripheral: peripheral)
        return true
    }

    private func sendProtectedR10ResponseEventDataSequenceIfReady(peripheral: CBPeripheral) {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard protectedR10ResponseEventDataProofIsActive,
              protectedR10CommandSequenceTask == nil,
              !protectedR10ActivationSent,
              Self.protectedR10ResponseEventDataNotifyOrder.allSatisfy(
                protectedR10ProfileConfirmedNotifyUUIDs.contains
              ),
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse),
              peripheral.state == .connected else { return }
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: Self.protectedR10ResponseEventDataSequenceSentKey) else {
            persistProtectedR10CleanOwnerFallback(reason: "response_event_data_sequence_already_sent")
            return
        }

        let startedAt = Date()
        defaults.set(true, forKey: Self.protectedR10ResponseEventDataSequenceSentKey)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10ActivationSentAtKey)
        defaults.set(defaults.integer(forKey: Self.protectedR10ActivationCountKey) + 1,
                     forKey: Self.protectedR10ActivationCountKey)
        defaults.set("response_event_data_commands_started",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationSent = true
        protectedR10ActivationAt = startedAt
        protectedR10FramesAfterActivation = 0
        protectedR10CommandSequenceTask = Task { @MainActor [weak self, weak peripheral] in
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            let r10Sequence = self.cmdSeq
            self.cmdSeq &+= 1
            let r10Frame = encodeFrame([
                Packet.command, r10Sequence, Cmd.sendR10R11Realtime, 0x01
            ])
            peripheral.writeValue(r10Frame, for: txCharacteristic, type: .withoutResponse)
            AtriaDebugLog("ATRIADBG protected_r10 status=command_sent owner=v9 cmd=3f data=01 seq=%d action=exactly_once",
                          Int(r10Sequence))

            try? await Task.sleep(for: .seconds(Self.protectedR10CommandPacingDelay))
            guard !Task.isCancelled, peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            let imuSequence = self.cmdSeq
            self.cmdSeq &+= 1
            let imuFrame = encodeFrame([
                Packet.command, imuSequence, Cmd.toggleIMUMode, 0x01
            ])
            peripheral.writeValue(imuFrame, for: txCharacteristic, type: .withoutResponse)
            AtriaDebugLog("ATRIADBG protected_r10 status=command_sent owner=v9 cmd=6a data=01 seq=%d pacing_ms=120 action=exactly_once_complete",
                          Int(imuSequence))
            self.protectedR10CommandSequenceTask = nil
            self.scheduleProtectedR10BatteryDiscovery(peripheral: peripheral)
        }

        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10MissingFrameTimeout))
            guard let self, !Task.isCancelled,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            if self.protectedR10FramesAfterActivation == 0 {
                let retried = self.retryProtectedR10ShortBurstIfEligible(
                    now: Date(),
                    reason: "prior_qualified_zero_frame_proof"
                )
                if !retried {
                    self.persistProtectedR10CleanOwnerFallback(
                        reason: "response_event_data_missing_r10_frames"
                    )
                }
            } else {
                self.retryProtectedR10ShortBurstIfEligible(
                    now: Date(),
                    reason: "initial_proof_short_burst"
                )
            }
        }
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10EarlyDisconnectWindow))
            guard let self, !Task.isCancelled,
                  self.protectedR10ResponseEventDataProofIsActive,
                  self.peripheral?.state == .connected else { return }
            let now = Date()
            guard Self.protectedR10StabilityWindowIsProven(
                framesAfterActivation: self.protectedR10FramesAfterActivation,
                lastFrameAt: self.lastR10MotionFrameAt,
                connectedAt: self.connectedAt,
                activationAt: startedAt,
                now: now
            ) else {
                self.persistProtectedR10CleanOwnerFallback(
                    reason: "response_event_data_insufficient_r10_density"
                )
                return
            }
            self.qualifyProtectedR10RecoveryIfNeeded(
                at: now,
                status: "response_event_data_receiving_crc_valid"
            )
        }
    }

    private func scheduleProtectedR10BatteryDiscovery(peripheral: CBPeripheral) {
        guard protectedR10StandardDiscoveryTask == nil else { return }
        protectedR10StandardDiscoveryTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(
                Self.protectedR10PostCommandStandardDiscoveryDelay
            ))
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            self.protectedR10StandardDiscoveryStarted = true
            peripheral.discoverServices([
                Self.UUIDs.heartRateService,
                Self.UUIDs.batteryService,
            ])
            AtriaDebugLog("ATRIADBG protected_r10 status=standard_services_requested owner=v9 services=heart_rate,battery action=after_diagnostic_order_motion_start")
            self.protectedR10StandardDiscoveryTask = nil
        }
    }

    private func sendProtectedR10ActivationIfReady() {
        let cleanProofActive = protectedR10CleanOwner == .protectedV7
            && protectedR10CleanOwnerProofIsActive
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !historyOnlyProbeMode,
              cleanProofActive
                || (protectedR10CleanOwner == .legacy
                    && !protectedR10RollbackEnabled),
              !protectedR10ActivationSent,
              protectedR10ActivationGraceTask == nil,
              strapStream5NotifyConfirmed,
              heartRateCharacteristic?.isNotifying == true,
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else { return }

        // First observe the passive stream. A reconnect is not proof that the
        // strap forgot a previous 3F/01, and repeatedly writing that command was
        // physically correlated with early disconnects. A fresh passive frame
        // cancels this task; otherwise the persisted lease/cooldown permits at
        // most one later activation.
        let defaults = UserDefaults.standard
        let persistedActivationAt = (defaults.object(forKey: Self.protectedR10ActivationSentAtKey) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        let leaseDelay = Self.protectedR10ActivationLeaseDelay(lastActivationAt: persistedActivationAt,
                                                               now: Date())
        let observationDelay: TimeInterval
        if cleanProofActive {
            let proofStartedAt = (defaults.object(
                forKey: Self.protectedR10CleanOwnerProofStartedAtKey
            ) as? Double).map(Date.init(timeIntervalSince1970:))
            let observationAge = proofStartedAt.map {
                max(0, Date().timeIntervalSince($0))
            } ?? 0
            observationDelay = max(0.001,
                                   max(Self.protectedR10PassiveGraceDuration - observationAge,
                                       leaseDelay))
        } else {
            observationDelay = max(Self.protectedR10PassiveGraceDuration, leaseDelay)
        }
        protectedR10ActivationGraceTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(observationDelay))
            guard let self, !Task.isCancelled else { return }
            self.protectedR10ActivationGraceTask = nil
            self.sendProtectedR10ActivationNowIfReady()
        }
    }

    private func sendProtectedR10ActivationNowIfReady() {
        guard !readOnlyHistoryCaptureRequested else { return }
        let cleanProofActive = protectedR10CleanOwner == .protectedV7
            && protectedR10CleanOwnerProofIsActive
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !historyOnlyProbeMode,
              cleanProofActive
                || (protectedR10CleanOwner == .legacy
                    && !protectedR10RollbackEnabled),
              !protectedR10ActivationSent,
              strapStream5NotifyConfirmed,
              heartRateCharacteristic?.isNotifying == true,
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else { return }

        if cleanProofActive {
            let now = Date()
            let defaults = UserDefaults.standard
            let proofStartedAt = (defaults.object(
                forKey: Self.protectedR10CleanOwnerProofStartedAtKey
            ) as? Double).map(Date.init(timeIntervalSince1970:))
            let lastActivationAt = (defaults.object(
                forKey: Self.protectedR10ActivationSentAtKey
            ) as? Double).map(Date.init(timeIntervalSince1970:))
            let decision = Self.protectedR10RecoveryDecision(
                pending: true,
                connected: status == .connected && peripheral.state == .connected,
                stream5Notifying: strapStream5NotifyConfirmed,
                activationSent: false,
                passiveObservationAge: proofStartedAt.map { now.timeIntervalSince($0) },
                activationAge: nil,
                activationLeaseRemaining: Self.protectedR10ActivationLeaseDelay(
                    lastActivationAt: lastActivationAt,
                    now: now
                ),
                stableHRDuration: proofStartedAt.map { now.timeIntervalSince($0) } ?? 0,
                latestHRAge: lastRawHRNotificationAt.map { now.timeIntervalSince($0) },
                batteryLevel: motionEligibilityBatteryLevel(now: now),
                isCharging: motionEligibilityIsCharging,
                frames: protectedR10FramesAfterActivation,
                lastFrameAge: lastR10MotionFrameAt.map { now.timeIntervalSince($0) }
            )
            guard decision == .sendSingleLeasedActivation else { return }
        }

        protectedR10ActivationSent = true
        protectedR10FramesAfterActivation = 0
        let sentAt = Date()
        protectedR10ActivationAt = sentAt
        let sequence = cmdSeq
        cmdSeq &+= 1
        let frame = encodeFrame([Packet.command, sequence, Cmd.sendR10R11Realtime, 0x01])
        let defaults = UserDefaults.standard
        defaults.set(sentAt.timeIntervalSince1970, forKey: Self.protectedR10ActivationSentAtKey)
        defaults.set(defaults.integer(forKey: Self.protectedR10ActivationCountKey) + 1,
                     forKey: Self.protectedR10ActivationCountKey)
        defaults.set("activation_sent", forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG protected_r10 status=activation_sent cmd=3f data=01 mode=wwr seq=%d action=single_write",
                      Int(sequence))
        peripheral.writeValue(frame, for: txCharacteristic, type: .withoutResponse)

        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10MissingFrameTimeout))
            guard let self, !Task.isCancelled,
                  Self.shouldLatchProtectedR10RollbackForMissingFrames(
                    activationSent: self.protectedR10ActivationSent,
                    framesAfterActivation: self.protectedR10FramesAfterActivation
                  ) else { return }
            if self.protectedR10CleanOwnerProofIsActive {
                self.persistProtectedR10CleanOwnerFallback(
                    reason: "missing_r10_after_clean_owner_activation"
                )
            } else {
                self.latchProtectedR10Rollback(reason: "missing_r10_after_activation")
            }
        }
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10EarlyDisconnectWindow))
            guard let self, !Task.isCancelled,
                  self.protectedR10ActivationAt == sentAt,
                  self.peripheral?.state == .connected else { return }
            let verifiedAt = Date()
            guard Self.protectedR10StabilityWindowIsProven(
                framesAfterActivation: self.protectedR10FramesAfterActivation,
                lastFrameAt: self.lastR10MotionFrameAt,
                connectedAt: self.connectedAt,
                activationAt: sentAt,
                now: verifiedAt
            ) else {
                AtriaDebugLog("ATRIADBG protected_r10 status=stability_window_failed duration_s=%.0f frames=%d last_frame_age_s=%.1f action=rollback_without_reconnect",
                              Self.protectedR10EarlyDisconnectWindow,
                              self.protectedR10FramesAfterActivation,
                              self.lastR10MotionFrameAt.map { verifiedAt.timeIntervalSince($0) } ?? -1)
                if self.protectedR10CleanOwnerProofIsActive {
                    self.persistProtectedR10CleanOwnerFallback(
                        reason: "insufficient_clean_owner_r10_density"
                    )
                } else {
                    self.latchProtectedR10Rollback(reason: "insufficient_r10_stability_density")
                }
                return
            }
            self.qualifyProtectedR10RecoveryIfNeeded(at: verifiedAt,
                                                     status: "receiving_crc_valid")
            AtriaDebugLog("ATRIADBG protected_r10 status=stable_window_complete duration_s=%.0f frames=%d action=clear_early_disconnect_streak",
                          Self.protectedR10EarlyDisconnectWindow,
                          self.protectedR10FramesAfterActivation)
        }
    }

    private func retryProtectedR10AfterStableHRIfEligible(now: Date) {
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !offlineHistoricalSyncInProgress,
              !historyOnlyProbeEnabled,
              !historyOnlyProbeMode,
              peripheral?.state == .connected else { return }

        if protectedR10CleanOwnerProofIsActive {
            if Self.protectedR10CleanOwnerProofHasExpired(
                proofActive: true,
                attemptAge: (UserDefaults.standard.object(
                    forKey: Self.protectedR10CleanOwnerProofStartedAtKey
                ) as? Double).map { now.timeIntervalSince1970 - $0 }
            ) {
                persistProtectedR10CleanOwnerFallback(
                    reason: "clean_owner_proof_timeout_on_hr"
                )
                return
            }
            // HR may become fresh after the 20-second passive timer. Recheck
            // only the leased command gate; never rediscover or toggle stream5.
            sendProtectedR10ActivationIfReady()
        }
    }

    private func beginProtectedR10CleanOwnerProofIfNeeded(at startedAt: Date) {
        let defaults = UserDefaults.standard
        guard protectedR10CleanOwner == .protectedV7,
              protectedR10CleanOwnerState == .protectedLaunchPending,
              strapStream5NotifyConfirmed,
              status == .connected,
              peripheral?.state == .connected else { return }
        defaults.set(ProtectedR10CleanOwnerState.proving.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set("clean_owner_v7_passive_proof",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationGraceTask?.cancel()
        protectedR10ActivationGraceTask = nil
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        scheduleProtectedR10CleanOwnerProofTimeout(startedAt: startedAt)
        sendProtectedR10ActivationIfReady()
        AtriaDebugLog("ATRIADBG protected_r10 status=clean_owner_proof_started owner=v7 grace_s=%.0f action=observe_initial_profile_no_cccd_mutation",
                      Self.protectedR10PassiveGraceDuration)
    }

    private func scheduleProtectedR10CleanOwnerProofTimeout(startedAt: Date) {
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = Task { @MainActor [weak self] in
            let age = max(0, Date().timeIntervalSince(startedAt))
            let remaining = max(0, Self.protectedR10PassiveReprobeTimeout - age)
            try? await Task.sleep(for: .seconds(remaining))
            guard let self, !Task.isCancelled,
                  self.protectedR10CleanOwnerProofIsActive else { return }
            self.protectedR10CleanOwnerProofTimeoutTask = nil
            self.persistProtectedR10CleanOwnerFallback(
                reason: "clean_owner_proof_timeout"
            )
        }
    }

    private func qualifyProtectedR10RecoveryIfNeeded(at qualifiedAt: Date,
                                                     status: String) {
        workoutMotionLeaseProfileArmed = false
        let defaults = UserDefaults.standard
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.set(0, forKey: Self.protectedR10RetryCountKey)
        defaults.set(true, forKey: Self.protectedR10StableTransportKey)
        defaults.set(qualifiedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(false, forKey: Self.protectedR10PassiveReprobePendingKey)
        defaults.set(0, forKey: Self.protectedR10PassiveReprobeFailureCountKey)
        defaults.set(0, forKey: Self.protectedR10ProofChurnFailureCountKey)
        if protectedR10CleanOwner == .protectedV7
            || protectedR10CleanOwner == .protectedV9 {
            defaults.set(ProtectedR10CleanOwnerState.qualified.rawValue,
                         forKey: Self.protectedR10CleanOwnerStateKey)
            defaults.removeObject(forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
            defaults.removeObject(forKey: Self.protectedR10CleanOwnerFailureReasonKey)
        }
        defaults.set(status, forKey: RadioDefaults.passiveR10Status)
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
    }

    /// Persist a clean pure-HR owner for the next process. The current proof
    /// link is left untouched: no CCCD disable, service rediscovery,
    /// connection cancellation or history handoff is allowed here.
    private func persistProtectedR10CleanOwnerFallback(reason: String) {
        let defaults = UserDefaults.standard
        if workoutMotionLeaseProfileArmed {
            // The current per-connection proof owns the truth state. It cleared
            // stableTransport before sending the command pair, so an
            // interruption or a two-frame burst cannot honestly restore
            // `qualified` from an older epoch. Continue into pure-HR fallback;
            // HR/RR remain available while motion is reported unavailable.
            workoutMotionLeaseProfileArmed = false
            AtriaDebugLog("ATRIADBG workout_motion status=lease_bring_up_failed reason=%@ action=pure_hr_fallback_no_false_qualification",
                          reason)
        }
        let failures = defaults.integer(forKey: Self.protectedR10PassiveReprobeFailureCountKey) + 1
        defaults.set(failures, forKey: Self.protectedR10PassiveReprobeFailureCountKey)
        let fallbackOwner: ProtectedR10CleanOwner = protectedR10CleanOwner == .protectedV9
            ? .pureHRV10
            : .pureHRV8
        defaults.set(fallbackOwner.rawValue,
                     forKey: Self.protectedR10CleanOwnerKey)
        defaults.set(ProtectedR10CleanOwnerState.fallbackPending.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(false, forKey: Self.protectedR10PassiveReprobePendingKey)
        defaults.set(true, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(true, forKey: Self.protectedR10RollbackKey)
        defaults.set(reason, forKey: Self.protectedR10DisconnectStormReasonKey)
        defaults.set(reason, forKey: Self.protectedR10CleanOwnerFailureReasonKey)
        defaults.set(Date().timeIntervalSince1970, forKey: Self.protectedR10FallbackAtKey)
        defaults.removeObject(forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set(fallbackOwner == .pureHRV10
                        ? "clean_owner_v10_fallback_pending"
                        : "clean_owner_v8_fallback_pending",
                     forKey: RadioDefaults.passiveR10Status)
        retireLiveR10MotionFreshness(
            state: "passive_r10_unavailable",
            reason: "clean_owner_fallback_\(reason)"
        )
        protectedR10ActivationGraceTask?.cancel()
        protectedR10ActivationGraceTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = nil
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = nil
        protectedR10CommandSequenceTask?.cancel()
        protectedR10CommandSequenceTask = nil
        protectedR10StandardDiscoveryTask?.cancel()
        protectedR10StandardDiscoveryTask = nil
        protectedR10ProfileCharacteristics.removeAll()
        protectedR10ProfileRequestedNotifyUUIDs.removeAll()
        protectedR10ProfileConfirmedNotifyUUIDs.removeAll()
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        protectedR10InitialProfilePeripheralID = nil
        protectedR10InitialProfileNotificationRequested = false
        stopR10LivenessWatchdog(reason: reason)
        AtriaDebugLog("ATRIADBG protected_r10 status=clean_owner_fallback_pending owner=%@ reason=%@ failures=%d action=keep_current_link_untouched_select_fresh_pure_hr_next_process_no_history",
                      fallbackOwner.rawValue,
                      reason,
                      failures)
    }

    /// Stream 5 may be subscribed exactly once as part of a newly connected
    /// protected profile. Service restoration and watchdog rediscovery happen
    /// on an established link and must never mutate its CCCD.
    private func requestProtectedR10InitialProfileNotificationIfAllowed(
        _ characteristic: CBCharacteristic,
        peripheral: CBPeripheral
    ) {
        guard standardHROnlyMode,
              !historyOnlyProbeMode,
              !protectedR10StreamSuppressed,
              characteristic.uuid == Self.UUIDs.strapStream5,
              characteristic.properties.contains(.notify),
              !characteristic.isNotifying else { return }
        guard protectedR10InitialProfilePeripheralID == peripheral.identifier else {
            AtriaDebugLog("ATRIADBG protected_r10 status=stream5_inactive action=skip_mid_link_cccd_mutation owner=%@ state=%@",
                          protectedR10CleanOwner.rawValue,
                          protectedR10CleanOwnerState.rawValue)
            if protectedR10CleanOwner == .protectedV7,
               (protectedR10CleanOwnerState == .protectedLaunchPending
                || protectedR10CleanOwnerState == .proving
                || protectedR10CleanOwnerState == .qualified) {
                persistProtectedR10CleanOwnerFallback(
                    reason: "clean_owner_stream5_inactive_after_initial_profile"
                )
            }
            return
        }
        guard !protectedR10InitialProfileNotificationRequested else { return }
        protectedR10InitialProfileNotificationRequested = true
        peripheral.setNotifyValue(true, for: characteristic)
        incrementRadioCounter(RadioDefaults.customNotifyEnabled,
                              reason: "protected_r10_initial_profile")
        dbgSubsReq += 1
        AtriaDebugLog("ATRIADBG protected_r10 status=stream5_subscribe_requested action=initial_profile_once owner=%@",
                      protectedR10CleanOwner.rawValue)
    }

    /// Only a completed CoreBluetooth callback may reject the initial v7
    /// profile. Foreground/liveness observations are intentionally excluded
    /// because they can run while the subscribe request is still in flight.
    private func persistProtectedR10FallbackForStream5Callback(reason: String) {
        guard standardHROnlyMode,
              protectedR10CleanOwner == .protectedV7,
              protectedR10CleanOwnerState == .protectedLaunchPending
                || protectedR10CleanOwnerState == .proving
                || protectedR10CleanOwnerState == .qualified else { return }
        persistProtectedR10CleanOwnerFallback(reason: reason)
    }

    /// CoreBluetooth restoration can hand back a connected peripheral whose
    /// services/characteristics are already cached without replaying every
    /// discovery callback. Rehydrate the protected R10 prerequisites directly
    /// from that cache so a Release reinstall cannot leave HR healthy while the
    /// motion stream silently stays dormant.
    private func resumeProtectedR10FromRestoredCache(_ peripheral: CBPeripheral) {
        guard standardHROnlyMode,
              !historyOnlyProbeMode,
              !protectedR10StreamSuppressed,
              peripheral.state == .connected else { return }

        var cachedHR: CBCharacteristic?
        var cachedStream5: CBCharacteristic?
        var cachedTX: CBCharacteristic?
        var cachedBattery: CBCharacteristic?
        for service in peripheral.services ?? [] {
            if service.uuid == Self.UUIDs.heartRateService {
                guard let characteristics = service.characteristics else {
                    peripheral.discoverCharacteristics([Self.UUIDs.heartRateMeasure], for: service)
                    continue
                }
                cachedHR = characteristics.first { $0.uuid == Self.UUIDs.heartRateMeasure }
            } else if service.uuid == Self.UUIDs.strapService {
                guard let characteristics = service.characteristics else {
                    peripheral.discoverCharacteristics([Self.UUIDs.strapStream5, Self.UUIDs.strapTX], for: service)
                    continue
                }
                cachedStream5 = characteristics.first { $0.uuid == Self.UUIDs.strapStream5 }
                cachedTX = characteristics.first { $0.uuid == Self.UUIDs.strapTX }
            } else if service.uuid == Self.UUIDs.batteryService {
                guard let characteristics = service.characteristics else {
                    peripheral.discoverCharacteristics([Self.UUIDs.batteryLevel], for: service)
                    continue
                }
                cachedBattery = characteristics.first { $0.uuid == Self.UUIDs.batteryLevel }
            }
        }

        if let cachedHR {
            heartRateCharacteristic = cachedHR
            if cachedHR.properties.contains(.notify), !cachedHR.isNotifying {
                _ = requestHeartRateNotificationEnableIfNeeded(
                    peripheral: peripheral,
                    characteristic: cachedHR,
                    reason: "restored_heart_rate_cache"
                )
            }
        }
        if let cachedTX, cachedTX.properties.contains(.writeWithoutResponse) {
            txCharacteristic = cachedTX
            dbgTxReady = true
        }
        if let cachedStream5, cachedStream5.properties.contains(.notify) {
            if cachedStream5.isNotifying {
                activeProprietaryNotifyUUIDs.insert(Self.UUIDs.strapStream5)
                strapStream5NotifyConfirmed = true
                markPassiveR10SubscriptionConfirmed()
            } else {
                requestProtectedR10InitialProfileNotificationIfAllowed(
                    cachedStream5,
                    peripheral: peripheral
                )
            }
        }
        if let cachedBattery {
            batteryLevelCharacteristic = cachedBattery
            let batteryRefreshAllowed = Self.shouldAllowAncillaryGATTRefresh(
                historyTransportOwnsLink: recoveredDataProjectionDeferralIsActive
            )
            if batteryRefreshAllowed,
               cachedBattery.properties.contains(.notify)
                    || cachedBattery.properties.contains(.indicate) {
                let now = Date()
                let defaults = UserDefaults.standard
                let canReuseRestoredEpoch = Self.restoredCachedBatteryNotificationCanReuseEpoch(
                    characteristicIsNotifying: cachedBattery.isNotifying,
                    restoredSamePeripheral: batteryConnectionRestoredSamePeripheral,
                    confirmedAt: (defaults.object(forKey: BatteryDefaults.notificationConfirmedAt) as? Double)
                        .map(Date.init(timeIntervalSince1970:)),
                    lastError: defaults.string(forKey: BatteryDefaults.notificationLastError),
                    linkConnected: peripheral.state == .connected && status == .connected,
                    now: now
                )
                if canReuseRestoredEpoch {
                    promoteReconnectBatteryBaselineIfSafe(
                        now: now,
                        heartRateReceivedAt: lastRawHRNotificationAt,
                        validatedR10ReceivedAt: lastR10MotionFrameAt,
                        reason: "2A19_restored_cache_notify_active"
                    )
                } else if cachedBattery.isNotifying {
                    // The cached flag cannot mint a new confirmation or erase a
                    // prior callback error. Force a real off/on callback cycle.
                    if defaults.string(forKey: BatteryDefaults.notificationLastError) == nil {
                        defaults.set("restored_cache_unconfirmed",
                                     forKey: BatteryDefaults.notificationLastError)
                    }
                    defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
                    revokeBatteryNotificationLease(reason: "2A19_restored_cache_unconfirmed",
                                                   now: now)
                    pendingNotifyReenableUUIDs.insert(cachedBattery.uuid)
                    peripheral.setNotifyValue(false, for: cachedBattery)
                    armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: cachedBattery,
                        reason: "restored_cache_disable"
                    )
                } else {
                    defaults.set(now.timeIntervalSince1970,
                                 forKey: BatteryDefaults.notificationRequestedAt)
                    peripheral.setNotifyValue(true, for: cachedBattery)
                    armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: cachedBattery,
                        reason: "restored_cache_enable"
                    )
                }
            } else if !batteryRefreshAllowed {
                AtriaDebugLog("ATRIADBG battery source=2A19 status=restored_cache_observed reason=history_transport_owned action=no_cccd_recovery")
            }
        }
        AtriaDebugLog("ATRIADBG protected_r10 status=restored_cache_rehydrated services=%d hr=%d stream5=%d tx=%d stream5_notifying=%d action=resume_minimal_transport",
                      peripheral.services?.count ?? 0,
                      cachedHR == nil ? 0 : 1,
                      cachedStream5 == nil ? 0 : 1,
                      cachedTX == nil ? 0 : 1,
                      cachedStream5?.isNotifying == true ? 1 : 0)
        sendProtectedR10ActivationIfReady()
    }

    private func latchProtectedR10Rollback(reason: String) {
        guard motionHandshakeDiagnostic == nil else { return }
        let defaults = UserDefaults.standard
        defaults.set(true, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(reason, forKey: "atria.protectedR10.rollbackReason")
        defaults.set(Date().timeIntervalSince1970, forKey: "atria.protectedR10.rollbackAt")
        defaults.set("activation_suppressed_observing_passive_r10",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationGraceTask?.cancel()
        protectedR10ActivationGraceTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = nil
        // Never unsubscribe, cancel, rediscover, or reconnect here. Those
        // interventions caused the old loop. Keep the healthy 2A37 link and
        // apply pure-HR discovery only after the next natural connection edge.
        AtriaDebugLog("ATRIADBG protected_r10 status=activation_suppressed reason=%@ action=preserve_2a37_and_passive_stream5_no_reconnect_no_more_commands",
                      reason)
    }

    private func startOfflineHistoricalSync(reason: String, force: Bool) {
        _ = startOfflineHistoricalSync(reason: reason,
                                       force: force,
                                       explicitRequest:
                                        Self.isExplicitUserOfflineSyncReason(reason),
                                       connectedChunkedBackfill: false,
                                       attemptAt: Date(),
                                       rawOnlyGapFingerprint: nil,
                                       gapFingerprint: nil)
    }

    /// CoreBluetooth can wake the app in the background, but iOS may suspend
    /// it again immediately after the delegate callback. The verified WHOOP
    /// handshake contains short ordering delays, so acquire a finite UIKit
    /// execution lease only for the active recovery transaction. The lease is
    /// ended on every normal terminal path and never changes gap authority.
    private func beginOfflineHistoricalSyncBackgroundLease(generation: UInt64) {
        endOfflineHistoricalSyncBackgroundLease(status: "replaced")
        offlineHistoricalSyncBackgroundTaskGeneration = generation
        let defaults = UserDefaults.standard
        defaults.set("active", forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.backgroundLeaseAt)
        offlineHistoricalSyncBackgroundTask = UIApplication.shared.beginBackgroundTask(
            withName: "Atria WHOOP history recovery"
        ) { [weak self] in
            Task { @MainActor in
                guard let self,
                      self.offlineHistoricalSyncBackgroundTaskGeneration == generation else {
                    return
                }
                AtriaDebugLog("ATRIADBG offline_sync background_lease=expired generation=%llu action=retain_pending_and_allow_corebluetooth_resume",
                              generation)
                self.endOfflineHistoricalSyncBackgroundLease(status: "expired_pending")
            }
        }
        if offlineHistoricalSyncBackgroundTask == .invalid {
            defaults.set("unavailable",
                         forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        }
        AtriaDebugLog("ATRIADBG offline_sync background_lease=active generation=%llu application_state=%ld",
                      generation,
                      UIApplication.shared.applicationState.rawValue)
    }

    private func endOfflineHistoricalSyncBackgroundLease(status: String) {
        let task = offlineHistoricalSyncBackgroundTask
        offlineHistoricalSyncBackgroundTask = .invalid
        offlineHistoricalSyncBackgroundTaskGeneration = nil
        if task != .invalid {
            UIApplication.shared.endBackgroundTask(task)
        }
        let defaults = UserDefaults.standard
        defaults.set(status, forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.backgroundLeaseAt)
    }

    /// UIKit background-task identifiers are process-local. If iOS terminates
    /// the process during a history serve, the persisted diagnostic must not
    /// continue saying "active" on the next launch: there is no in-memory
    /// owner and the durable gap is still pending. This is bookkeeping only;
    /// it neither clears a gap nor issues a BLE command.
    private func reconcileOrphanedBackgroundHistoryLeaseAtLaunch() {
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: OfflineSyncDefaults.backgroundLeaseStatus) == "active" else {
            return
        }
        defaults.set("orphaned_process_terminated",
                     forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.backgroundLeaseAt)
        AtriaDebugLog("ATRIADBG offline_sync background_lease=orphaned_process_terminated action=retain_gap_no_transport_mutation")
    }

    private func startOfflineHistoricalSync(reason: String,
                                            force: Bool,
                                            explicitRequest: Bool,
                                            connectedChunkedBackfill: Bool,
                                            attemptAt: Date,
                                            rawOnlyGapFingerprint: String?,
                                            gapFingerprint: String?,
                                            freshOwnerCutoverCompleted: Bool = false) -> Bool {
        // Never overwrite a raw ingress journal from a terminated process.
        // Its replay has no reducer/ACK authority, but preserves real frames
        // that otherwise disappear at the next generation boundary.
        if archiveOrphanHistoricalIngressIfNeeded(
            reason: reason,
            force: force,
            explicitRequest: explicitRequest
        ) {
            return false
        }
        // Automatic recovery is subordinate to a visible live dashboard. The
        // request stays pending and can run after backgrounding or a later
        // natural link loss; an explicit user import remains allowed.
        if foregroundInteractiveMode
            && !explicitRequest
            && !freshOwnerCutoverCompleted {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            let defaults = UserDefaults.standard
            defaults.set("deferred_interactive_live_priority",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=interactive_foreground_live_priority action=retain_pending_no_history_owner force=%d",
                          reason,
                          force ? 1 : 0)
            return false
        }
        // Recheck at the exact transaction boundary. `request...` evaluated the
        // transport earlier, but CBPeripheral.state is owned by CoreBluetooth;
        // it may become `.connecting` before this synchronous handoff reaches
        // the mutation below. A force flag grants cadence authority only—it
        // must never grant permission to cancel the standing realtime connect.
        guard peripheral?.state != .connecting else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: explicitRequest
            )
            let defaults = UserDefaults.standard
            defaults.set("deferred_realtime_reconnect_in_flight",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=transaction_boundary_reconnect_in_flight action=no_attempt_no_lease_no_cancel force=%d",
                          reason,
                          force ? 1 : 0)
            return false
        }
        // The launch intent is now represented by the active generation (or by
        // one of the retained cutover/request states). Clearing it here keeps the
        // ownership fence finite without opening a pre-transaction scan window.
        explicitHistoryLaunchIntentPending = false
        let defaults = UserDefaults.standard
        defaults.set(attemptAt, forKey: OfflineSyncDefaults.lastAttemptAt)
        defaults.set(defaults.integer(forKey: OfflineSyncDefaults.attempts) + 1,
                     forKey: OfflineSyncDefaults.attempts)
        defaults.set("starting", forKey: OfflineSyncDefaults.lastStatus)
        defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
        offlineHistoricalSyncRawOnlyGapFingerprint = rawOnlyGapFingerprint
        offlineHistoricalSyncGapFingerprint = gapFingerprint
        if defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) {
            defaults.set(attemptAt.timeIntervalSince1970,
                         forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt)
        }
        flushActiveSessionJournal(reason: "offline_sync_preflight_\(reason)")
        offlineHistoricalSyncPreviousStandardHROnlyMode = standardHROnlyMode
        offlineHistoricalSyncStartRows = historicalArchiveRows
        offlineHistoricalSyncMadeRequestedMetricProgress = false
        offlineHistoricalSyncResolvedGapCoverage = false
        offlineHistoricalSyncReachedTerminal = false
        verifiedEmptyHistoryCursorGeneration = nil
        durableTerminalAuthorityGeneration = nil
        offlineHistoricalSyncGeneration &+= 1
        let syncGeneration = offlineHistoricalSyncGeneration
        historicalConsumerReceiptRequiredGenerations.remove(syncGeneration)
        historicalConsumerReceiptedGenerations.remove(syncGeneration)
        // Publish callback ownership before discovery or any history command can
        // produce a notification. Delegate readers observe this through a lock.
        _ = historyTransportPhaseFence.activate(
            generation: syncGeneration,
            usesExplicitHistoryProfile: explicitRequest
        )
        offlineHistoricalSyncInProgress = true
        suspendWorkoutMotionLeaseForHistoricalSync()
        historyRealtimeStopRequestedGeneration = nil
        historyRealtimeStopCompletedGeneration = nil
        lastProprietaryWriteCompletion = nil
        beginOfflineHistoricalSyncBackgroundLease(generation: syncGeneration)
        offlineHistoricalSyncReason = reason
        // Production currently sends WHOOP's verified full-dump command. It
        // does not encode the local gap interval and no accepted response is
        // durably tied to that interval+attempt. Keep this drain raw-only: a
        // local exact gap is not strap-issued no-data/coverage authority.
        activeHistoricalRequestBinding = nil
        historicalFullDrainWriteEvidence = nil
        historicalAdmissionAttempt = nil
        historicalAdmissionHighestOrdinal = nil
        historicalAdmissionFailed = false
        historicalCheckpointCoordinator.begin(generation: syncGeneration)
        let persistedFullDrainAuthority = try? historicalFullDrainCoverageStore.load()
        if let persisted = persistedFullDrainAuthority,
           persisted.status == .draining,
           let gapID = UUID(uuidString: persisted.gap.gapIdentifier) {
            selectedFullDrainGap = AtriaHistoricalGapLedger.recoveryCandidate(
                id: gapID,
                startUnix: persisted.gap.startUnix,
                endUnix: persisted.gap.endUnix,
                reason: persisted.gap.reason
            )
            if selectedFullDrainGap == nil {
                let windows = AtriaHistoricalGapLedger.windows()
                var oldAuthorityCleared = false
                if let changed = windows.first(where: { $0.id == gapID }),
                   let changedEnd = changed.end {
                    oldAuthorityCleared = (try? historicalFullDrainCoverageStore
                        .abandonDrainingAuthorityIfGapFingerprintChanged(
                            gapIdentifier: persisted.gap.gapIdentifier,
                            observedStartUnix: changed.start.timeIntervalSince1970,
                            observedEndUnix: changedEnd.timeIntervalSince1970,
                            observedReason: changed.reason
                        )) ?? false
                } else if !windows.contains(where: { $0.id == gapID }) {
                    try? historicalFullDrainCoverageStore
                        .clearUnresolvedAuthorityIfGapNoLongerPending(
                            gapIdentifier: persisted.gap.gapIdentifier
                        )
                    oldAuthorityCleared = true
                }
                if oldAuthorityCleared {
                    selectedFullDrainGap = AtriaHistoricalGapLedger
                        .newestClosedRecoveryCandidate()
                }
            }
        } else {
            // An automatic reconnect exists to repair the gap that just
            // closed, not to make the user wait behind unrelated historical
            // outages. Older intervals remain in the durable ledger and are
            // never discarded; only this transaction's coverage authority is
            // scoped to the newest exact candidate.
            selectedFullDrainGap = explicitRequest
                ? AtriaHistoricalGapLedger.oldestClosedRecoveryCandidate()
                : AtriaHistoricalGapLedger.newestClosedRecoveryCandidate()
        }
        fullDrainTransportNonce = UUID().uuidString.lowercased()
        pendingHistoryClockCommandSequence = nil
        pendingHistoryClockCommandRequestedAtUnix = nil
        pendingHistoryClockWriteCompletedAtUnix = nil
        productionHistoryReadPreflightRequired = Self
            .shouldUseProductionHistoryReadPreflight(
                explicitRequest: explicitRequest,
                force: force,
                reason: reason
            )
        historyReadPreflightGate.reset()
        acceptedHistoryReadPreflightIdentity = nil
        productionFullDrainClockAuthorityEnabled = false
        historyClockRef = nil
        acceptedHistoryClockResponseSequence = nil
        acceptedHistoryClockDeviceUnix = nil
        acceptedHistoryClockWallUnix = nil
        acceptedHistoryClockResponseAtUnix = nil
        pendingHistoryDataRangeCommandSequence = nil
        pendingHistoryDataRangeWriteCompletedAtUnix = nil
        acceptedHistoryDataRange = nil
        pendingHistoryDataRangeRequestedAtUnix = nil
        acceptedHistoryDataRangeResponseAtUnix = nil
        acceptedHistoryDataRangeResponseUptime = nil
        acceptedHistoryStartSequence = nil
        acceptedHistoryStartAtUnix = nil
        historyFirstFrameWatchdogTask?.cancel()
        historyFirstFrameWatchdogTask = nil
        historyFirstFrameReceivedGeneration = nil
        pendingFullDrainCommandRequestedAtUnix = nil
        activeFullDrainEventIdentity = nil
        historicalIngressSpool?.remove()
        historicalIngressSpool = nil
        historicalIngressSpoolFailure = nil
        historicalIngressDeferredEvent = nil
        historicalIngressStrapIdentifier = peripheral?.identifier.uuidString
            ?? UserDefaults.standard.string(forKey: LinkDefaults.savedPeripheralUUID)
            ?? "unknown-whoop4"
        let ingressDirectory = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        )[0].appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionDirectoryName,
            isDirectory: true
        )
        let ingressURL = ingressDirectory.appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionFileName
        )
        // The orphan replay above is the sole retirement path for a prior
        // generation. If one still exists, fail closed rather than silently
        // replacing it with a new spool.
        if FileManager.default.fileExists(atPath: ingressURL.path) {
            historicalAdmissionFailed = true
            historicalIngressSpoolFailure = "orphan_ingress_not_retired"
            AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=orphan_not_archived action=withhold_ack_retain_gap", syncGeneration)
        }
        do {
            historicalIngressSpool = try AtriaWhoop4HistoricalIngressSpool(
                url: ingressURL,
                generation: syncGeneration
            )
        } catch {
            historicalAdmissionFailed = true
            historicalIngressSpoolFailure = String(describing: error)
            AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=spool_open_failed error=%@ action=withhold_ack_retain_gap",
                          syncGeneration, historicalIngressSpoolFailure ?? "unknown")
        }
        historicalAdmissionBatchInFlight = false
        historicalAdmissionBatchScheduled = false
        fullDrainHistoryEndPayloads.removeAll(keepingCapacity: false)
        fullDrainACKPermits.removeAll(keepingCapacity: false)
        latestFullDrainDurableStores = nil
        fullDrainHistoryCompletePayload = nil
        AtriaDebugLog("ATRIADBG history_request_authority status=%@ reason=%@ detail=full_flash_positive_gap_authority gap=%@ action=clock_then_drain",
                      selectedFullDrainGap == nil ? "raw_only_no_closed_gap" : "candidate_selected",
                      reason,
                      selectedFullDrainGap?.window.id.uuidString ?? "none")
        prepareHistorySequenceContinuity(for: peripheral?.identifier.uuidString)
        _ = historyDrain.begin(generation: syncGeneration)
        startHistoricalDrainTelemetry(generation: syncGeneration)
        historicalMetricDurabilityFence.begin(generation: syncGeneration)
        noteOfflineHistoricalSyncProgress(
            generation: syncGeneration,
            reason: "generation_started"
        )
        pendingHistoryEndACK = nil
        pendingHistoryACKAttempts = 0
        historyACKGate.reset()
        historicalPageContinuationTask?.cancel()
        historicalPageContinuationTask = nil
        historyFirstFrameWatchdogTask?.cancel()
        historyFirstFrameWatchdogTask = nil
        historyFirstFrameReceivedGeneration = nil
        historicalReplayACKTask?.cancel()
        historicalReplayACKTask = nil
        historicalReplayACKBoundaryID = nil
        historyDurableFlushInFlight = false
        historicalArchiveWriteFailures = 0
        // Preserve the explicit, user-approved one-shot clock repair across
        // generation setup. This flag is set from the launch argument before
        // the generation is created; resetting it here used to silently turn
        // the approved repair back into an ordinary 0x16 history request.
        // Automatic recovery never sets this flag.
        let preserveUserApprovedHistoryClockRepair = historyClockSyncEnabled
        let preserveDebugHistoryRangeProbe = historyOnlyProbeEnabled
            && (historySelectorSweepEnabled || historyDataRangeSweepEnabled)
            && !historySkipDataRangeRequest
        historyOnlyProbeEnabled = true
        cancelHistoryOnlyProbe(reason: "new_offline_generation")
        // The four-form clock experiment is not part of the validated WHOOP 4
        // recovery handshake. Sending all four WR commands back-to-back filled
        // the callback ledger and physically disconnected the strap before the
        // full-drain command. Production archives the strap's record timestamp
        // directly; explicit selector/range diagnostics may retain clock probes.
        historyClockSyncEnabled = preserveDebugHistoryRangeProbe
            || preserveUserApprovedHistoryClockRepair
        probeCommandMode = .withResponse
        if preserveDebugHistoryRangeProbe {
            if historyInitSweepCommands.isEmpty {
                historyInitSweepCommands = [
                    [Cmd.abortHistoricalTransmits, 0x00],
                    [Cmd.enterHighFreqSync, 0x00],
                ]
            }
            historySkipDataRangeRequest = false
        } else {
            // Production WHOOP 4 recovery first quiets only the proprietary
            // R10/R11 raw stream, then issues the stable, bounded offload
            // request. Standard 2A37 HR/RR remains live. Abort and
            // high-frequency-sync are research controls: inserting them here
            // can leave an otherwise connected strap returning zero rows.
            historyInitSweepCommands = Self.productionHistoricalRecoveryInitCommands()
            historySkipDataRangeRequest = true
        }
        if !preserveDebugHistoryRangeProbe {
            historyDataRangeSweepEnabled = false
        }
        historyDataRangePendingRequests.removeAll()
        ackedHistoryAckKeys.removeAll()
        realtimeArmed = false
        realtimeOn = false
        // 0x03/0 is the verified realtime-HR stop. It is sent by the history
        // handshake only after TX has been rediscovered. Sending it here made
        // recovery launch-order dependent because a restored minimal 2A37 link
        // commonly has no cached proprietary TX characteristic yet.
        txCharacteristic = nil
        UserDefaults.standard.set("armed", forKey: OfflineSyncDefaults.lastStatus)
        UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
        let initSweepLabel = historyInitSweepCommands
            .map { Self.hex($0) }
            .joined(separator: ",")
        // Legacy static-check token from the pre-HIST-1 fail-closed path:
        // live_realtime=skipped metrics_fail_closed=1
        AtriaDebugLog("ATRIADBG offline_sync status=armed reason=%@ mode=%@ init_sweep=%@ ack_mode=enddata live_realtime=skipped metrics_fail_closed=1 cmd22=%d connected_chunked=%d",
              reason,
              connectedChunkedBackfill ? "connected_chunked_backfill" : (preserveDebugHistoryRangeProbe ? "selector_probe" : "safe_history_backfill"),
              initSweepLabel,
              historySkipDataRangeRequest ? 0 : 1,
              connectedChunkedBackfill ? 1 : 0)

        if let peripheral {
            dbgLast = "offline sync reconnect"
            switch peripheral.state {
            case .connected:
                peripheral.discoverServices(discoveryServicesForCurrentMode)
                AtriaDebugLog("ATRIADBG offline_sync status=connected_chunked reason=%@ action=discover_services_without_live_link_deferral samples=%d",
                              reason,
                              session.count)
            case .connecting:
                // Defensive second fence if CoreBluetooth changes state after
                // the transaction-boundary check. Never cancel the realtime
                // connection. Unwind this generation and retain the gap.
                retainPendingOfflineHistoricalSyncRequest(
                    reason: reason, force: force,
                    explicitRequest: explicitRequest
                )
                AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=reconnect_began_during_arm action=unwind_no_cancel force=%d",
                              reason,
                              force ? 1 : 0)
                finishOfflineHistoricalSync(
                    reason: "\(reason)_reconnect_began_during_arm",
                    generation: syncGeneration,
                    resumePendingSync: false
                )
                return false
            default:
                self.peripheral = nil
                recomputeConnectionStatus(reason: "offline_sync_stale_peripheral")
                if central.state == .poweredOn {
                    startScan(reason: "offline_sync_\(reason)")
                }
            }
        } else if central.state == .poweredOn {
            startScan(reason: "offline_sync_\(reason)")
        }

        armOfflineHistoricalSyncIdleWatchdog(
            generation: syncGeneration,
            reason: reason
        )
        return true
    }

    /// Replays a previous-process spool before a new generation can reuse its
    /// filename. Only exact frame bytes are archived. Metadata cannot safely
    /// reconstruct an old reducer boundary, so it is intentionally ignored;
    /// this path never writes an ACK, cursor, admission record, terminal proof,
    /// or gap-coverage evidence. Any error retains the complete original file
    /// for an idempotent later retry (archive identities deduplicate frames).
    @discardableResult
    private func archiveOrphanHistoricalIngressIfNeeded(
        reason: String,
        force: Bool,
        explicitRequest: Bool
    ) -> Bool {
        let ingressDirectory = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        )[0].appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionDirectoryName,
            isDirectory: true
        )
        let ingressURL = ingressDirectory.appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionFileName
        )
        guard !orphanHistoricalIngressArchiveInFlight else { return true }

        // The v1 spool header contains no strap identifier. Prefer the
        // terminally verified history owner, but a process killed during its
        // *first* successful serve has no such terminal record yet. In that
        // narrow case, the existing live-link identity is the app's only
        // persisted pairing proof: require it to match the saved connected
        // peripheral before archiving. It is still raw-only archival, never a
        // history protocol authorization or gap-coverage assertion.
        guard let strapIdentifier = peripheral?.identifier.uuidString else {
            AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_no_connected_owner action=retain_raw_no_new_generation")
            return true
        }
        let defaults = UserDefaults.standard
        let terminallyVerifiedOwner = defaults.string(
            forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID
        )
        let currentLinkedOwner = defaults.string(forKey: LinkDefaults.savedPeripheralUUID)
        guard strapIdentifier == terminallyVerifiedOwner
                || strapIdentifier == currentLinkedOwner else {
            AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_identity_unverified action=retain_raw_no_new_generation")
            return true
        }
        // This method is also called from every accepted live HR callback. A
        // non-nil spool belongs to the *current* history reducer and may still
        // be receiving CoreBluetooth frames; never inspect or seal it here.
        guard historicalIngressSpool == nil else {
            return true
        }
        let hasIngressSource = FileManager.default.fileExists(atPath: ingressURL.path)
        guard hasIngressSource || AtriaWhoop4HistoricalOrphanVault.hasPotentialProductionEntries() else {
            return false
        }
        retainPendingOfflineHistoricalSyncRequest(
            reason: reason, force: force, explicitRequest: explicitRequest
        )
        // Set this before dispatch so another HR callback cannot schedule a
        // second reader while the first worker is hashing/copying the source.
        orphanHistoricalIngressArchiveInFlight = true

        let archiveWarmGroup = historicalArchiveWarmGroup
        orphanHistoricalIngressArchiveQueue.async { [weak self] in
            var openedVault: AtriaWhoop4HistoricalOrphanVault?
            var sealedOrphans: [AtriaWhoop4HistoricalOrphanVault.Entry] = []
            do {
                let orphanVault = try AtriaWhoop4HistoricalOrphanVault.production()
                openedVault = orphanVault
                if hasIngressSource {
                let orphanGeneration = try AtriaWhoop4HistoricalIngressSpool.generation(
                    at: ingressURL
                )
                // Do not make protection of real, previously received strap
                // frames depend on opening the large canonical identity index.
                // Seal the raw spool first; canonical replay below remains the
                // sole route that can ever grant ACK or coverage authority.
                let sealed = try orphanVault.seal(
                    sourceURL: ingressURL,
                    strapIdentifier: strapIdentifier,
                    generation: orphanGeneration
                )
                try FileManager.default.removeItem(at: ingressURL)
                AtriaDebugLog("ATRIADBG historyIngress status=sealed_to_orphan_vault generation=%llu bytes=%llu action=raw_only_no_ack_no_coverage",
                              orphanGeneration,
                              sealed.byteCount)
                sealedOrphans = [sealed]
                } else {
                // A process may be suspended after seal but before its large
                // canonical index becomes ready. Resume that verified raw
                // vault on every later connection to the same paired strap.
                sealedOrphans = try orphanVault.validatedEntries(for: strapIdentifier)
                }
                guard !sealedOrphans.isEmpty else {
                    Task { @MainActor [weak self] in
                        self?.orphanHistoricalIngressArchiveInFlight = false
                    }
                    return
                }
            } catch {
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.orphanHistoricalIngressArchiveInFlight = false
                    AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_vault_open_failed error=%@ action=retain_raw_no_ack_no_coverage", String(describing: error))
                }
                return
            }
            guard let orphanVault = openedVault else { return }
            defer {
                sealedOrphans.forEach { HistoricalArchive.endDurableDrain(generation: $0.generation) }
            }
            var archivedFrames = 0
            var ignoredMetadata = 0
            do {
                AtriaDebugLog("ATRIADBG historyIngress status=replay_waiting_for_identity_store entries=%d", sealedOrphans.count)
                archiveWarmGroup.wait()
                AtriaDebugLog("ATRIADBG historyIngress status=replay_identity_store_ready entries=%d", sealedOrphans.count)
                for sealedOrphan in sealedOrphans {
                    let orphanGeneration = sealedOrphan.generation
                    AtriaDebugLog("ATRIADBG historyIngress status=replay_worker_started generation=%llu", orphanGeneration)
                    let spool = try orphanVault.spool(for: sealedOrphan)
                    AtriaDebugLog("ATRIADBG historyIngress status=replay_journal_opened pending=%d generation=%llu", spool.pendingCount, orphanGeneration)
                    while let event = try spool.popFirst() {
                    switch event {
                    case let .frame(payload, clock, clockAuthorityEnabled):
                        let reference = clock.map { clock in
                            let drift = Int(clock.wall) - Int(clock.device)
                            let snapped: Int
                            if abs(drift) >= 86_400 {
                                let granularity = 300
                                snapped = drift >= 0
                                    ? ((drift + granularity / 2) / granularity) * granularity
                                    : ((drift - granularity / 2) / granularity) * granularity
                            } else {
                                snapped = drift
                            }
                            return AtriaWhoop4HistoryArchivePipeline.ClockReference(
                                device: clock.device,
                                wall: clock.wall,
                                driftSeconds: drift,
                                snappedDriftSeconds: snapped
                            )
                        }
                        let computation = AtriaWhoop4HistoryArchivePipeline.prepare(
                            payload: payload,
                            clock: reference,
                            historyClockSyncEnabled: clockAuthorityEnabled
                        )
                        let persisted = AtriaWhoop4HistoryArchivePipeline.persist(
                            computation,
                            strapIdentifier: strapIdentifier,
                            generation: orphanGeneration
                        )
                        guard persisted.succeeded else {
                            throw NSError(
                                domain: "AtriaOrphanHistoricalIngress",
                                code: 1,
                                userInfo: [NSLocalizedDescriptionKey:
                                    persisted.errorDescription ?? "archive_persist_failed"]
                            )
                        }
                        archivedFrames += 1
                        AtriaDebugLog("ATRIADBG historyIngress status=replay_frame_persisted count=%d generation=%llu", archivedFrames, orphanGeneration)
                    case .metadata:
                        ignoredMetadata += 1
                    }
                    }
                    // `persist` is per-frame durable; synchronize the
                    // canonical archive once more before retiring this source
                    // journal. This does not imply gap coverage.
                    AtriaDebugLog("ATRIADBG historyIngress status=replay_flush_started frames=%d generation=%llu", archivedFrames, orphanGeneration)
                    _ = try HistoricalArchive.synchronizeDurableStorage(
                        generation: orphanGeneration
                    )
                    try orphanVault.retire(sealedOrphan)
                }
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.orphanHistoricalIngressArchiveInFlight = false
                    AtriaDebugLog("ATRIADBG historyIngress status=archived_orphan frames=%d metadata=%d entries=%d action=raw_only_no_ack_no_coverage",
                                  archivedFrames, ignoredMetadata, sealedOrphans.count)
                    if let pending = self.takePendingOfflineHistoricalSyncRequest() {
                        _ = self.requestOfflineHistoricalSyncIfNeeded(
                            reason: pending.reason,
                            force: pending.force,
                            explicitResearchRequest: pending.explicitRequest
                        )
                    }
                }
            } catch {
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.orphanHistoricalIngressArchiveInFlight = false
                    AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_archive_failed error=%@ action=retain_raw_no_ack_no_coverage",
                                  String(describing: error))
                }
            }
        }
        return true
    }

    private func noteOfflineHistoricalSyncProgress(
        generation: UInt64,
        reason: String
    ) {
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else { return }
        if reason == "historical_frame"
            || reason == "history_start"
            || reason == "history_end"
            || reason == "history_complete" {
            historicalPageContinuationTask?.cancel()
            historicalPageContinuationTask = nil
        }
        offlineHistoricalSyncLastProgressUptime = ProcessInfo.processInfo.systemUptime
        if reason != "historical_frame" {
            AtriaDebugLog("ATRIADBG offline_sync watchdog=progress generation=%llu event=%@",
                          generation,
                          reason)
        }
    }

    /// A suspended or otherwise lost unstructured watchdog task must not leave
    /// history ownership stranded forever while standard heart-rate packets
    /// prove that the process is still receiving CoreBluetooth callbacks. Run
    /// the same fail-closed idle decision from those callbacks as an
    /// independent liveness path. This never ACKs, aborts, or advances the
    /// strap cursor; it only drops the link so the durable prefix can replay on
    /// a fresh history-owner generation.
    ///
    /// Do not exempt a stalled local ACK, persistence batch, or callback queue
    /// here. Those are precisely the states which can strand an owner after the
    /// task-based watchdog was suspended. Once the full idle interval elapsed,
    /// a transport reset is safer than holding the link indefinitely: no ACK is
    /// manufactured and the durable prefix remains replayable.
    private func enforceHistoricalIdleTimeoutFromGattHeartbeatIfNeeded(
        nowUptime: TimeInterval
    ) {
        guard offlineHistoricalSyncInProgress,
              let lastProgress = offlineHistoricalSyncLastProgressUptime,
              Self.historicalSyncHasStalled(
                lastProgressUptime: lastProgress,
                nowUptime: nowUptime,
                idleTimeout: offlineHistoricalSyncIdleTimeout
              ),
              let stalledPeripheral = peripheral,
              stalledPeripheral.state == .connected else { return }

        let generation = offlineHistoricalSyncGeneration
        let idle = max(0, nowUptime - lastProgress)
        AtriaDebugLog("ATRIADBG offline_sync watchdog=gatt_heartbeat_idle_timeout generation=%llu idle_s=%.1f action=disconnect_without_ack_or_abort_retain_durable_prefix",
                      generation,
                      idle)
        cancelPeripheralConnection(
            stalledPeripheral,
            reason: "history_idle_timeout_gatt_heartbeat_transport_reset"
        )
    }

    /// A short whole-drain deadline truncated healthy physical WHOOP transfers.
    /// Watch the absence of progress instead: active data,
    /// persistence, fsync and ACK callbacks may keep a large asynchronous drain
    /// alive, while a silent transport still fails closed and retains its gap.
    private func armOfflineHistoricalSyncIdleWatchdog(
        generation: UInt64,
        reason: String
    ) {
        offlineHistoricalSyncTimeoutTask?.cancel()
        offlineHistoricalSyncTimeoutTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard let self else { return }
                try? await Task.sleep(
                    for: .seconds(self.offlineHistoricalSyncWatchdogPollInterval)
                )
                guard !Task.isCancelled,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation else {
                    return
                }
                let now = ProcessInfo.processInfo.systemUptime
                guard Self.historicalSyncHasStalled(
                    lastProgressUptime: self.offlineHistoricalSyncLastProgressUptime,
                    nowUptime: now,
                    idleTimeout: self.offlineHistoricalSyncIdleTimeout
                ) else { continue }
                let idle = self.offlineHistoricalSyncLastProgressUptime.map {
                    max(0, now - $0)
                } ?? -1
                // Silence is not a protocol terminal. The strap may still own
                // an unacknowledged HISTORY_END page (or be waiting inside a
                // page), so ending local history ownership and arming R10 on
                // this same connection would interleave transport epochs. Do
                // not manufacture an ACK or send ABORT here. A clean link loss
                // makes the durable prefix replayable; didDisconnect performs
                // the common fail-closed finalization and standing reconnect.
                if let stalledPeripheral = self.peripheral,
                   stalledPeripheral.state == .connected {
                    AtriaDebugLog("ATRIADBG offline_sync watchdog=idle_timeout generation=%llu idle_s=%.1f action=disconnect_without_ack_or_abort_retain_durable_prefix",
                                  generation,
                                  idle)
                    self.cancelPeripheralConnection(
                        stalledPeripheral,
                        reason: "history_idle_timeout_transport_reset"
                    )
                    return
                }
                AtriaDebugLog("ATRIADBG offline_sync watchdog=idle_timeout generation=%llu idle_s=%.1f action=finish_disconnected_without_ack_or_abort_retain_gap",
                              generation,
                              idle)
                self.finishOfflineHistoricalSync(
                    reason: "\(reason)_idle_timeout",
                    generation: generation
                )
                return
            }
        }
    }

    private func bindExactHistoricalRequestAuthorityIfAvailable(
        transportGeneration: UInt64,
        reason: String,
        exactRangeWasEncodedAndTransmitted: Bool,
        acceptedResponseDurablyTiedToAttempt: Bool
    ) {
        activeHistoricalRequestBinding = nil
        guard !reconcileConsumedHistoricalTerminalPublicationIfNeeded(
            reason: "pre_arm_\(reason)"
        ) else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=consumed_publication_reconciliation_in_flight action=no_rearm",
                          reason)
            return
        }
        guard Self.shouldBindExactHistoricalRequestAuthority(
            exactRangeWasEncodedAndTransmitted: exactRangeWasEncodedAndTransmitted,
            acceptedResponseDurablyTiedToAttempt: acceptedResponseDurablyTiedToAttempt
        ) else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=exact_range_transport_not_verified action=raw_archive_only_no_consumer_attestation",
                          reason)
            return
        }
        let defaults = UserDefaults.standard
        guard let exactRequest = AtriaBLEHistoryExactRequestPolicy.resolve(
            pending: defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
            explicitStart: defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart),
            explicitEnd: defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd),
            gapWindows: AtriaHistoricalGapLedger.windows(defaults: defaults),
            now: Date()
        ) else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=no_genuine_closed_exact_interval action=raw_archive_only_no_consumer_attestation",
                          reason)
            return
        }
        guard let peripheralIdentifier = peripheral?.identifier.uuidString
                ?? defaults.string(forKey: LinkDefaults.savedPeripheralUUID),
              !peripheralIdentifier.isEmpty else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=peripheral_identity_missing action=raw_archive_only_no_consumer_attestation",
                          reason)
            return
        }
        let strapIdentity = strapModel.rawValue
        do {
            let authority = try historicalRequestAuthorityStore.arm(
                exactRequest: exactRequest,
                peripheralIdentifier: peripheralIdentifier,
                strapIdentity: strapIdentity,
                now: Date()
            )
            let binding = try historicalRequestAuthorityStore.bind(
                authorityGeneration: authority.generation,
                requestIdentifier: authority.requestIdentifier,
                transportGeneration: transportGeneration,
                peripheralIdentifier: peripheralIdentifier,
                strapIdentity: strapIdentity,
                now: Date()
            )
            activeHistoricalRequestBinding = binding
            AtriaDebugLog("ATRIADBG history_request_authority status=bound reason=%@ authority_generation=%llu attempt=%llu transport_generation=%llu request_identifier=%@ peripheral=%@ strap=%@ start_unix=%d end_unix=%d source=%@",
                          reason,
                          binding.authorityGeneration,
                          binding.attempt,
                          binding.transportGeneration,
                          binding.requestIdentifier,
                          peripheralIdentifier,
                          strapIdentity,
                          Int(binding.exactRequest.requestedStartUnix),
                          Int(binding.exactRequest.requestedEndUnix),
                          binding.exactRequest.sourceIdentifier)
        } catch {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=%@ action=raw_archive_only_no_consumer_attestation",
                          reason,
                          String(describing: error))
        }
    }

    /// Closes the two-file commit after a crash between durable authority
    /// consumption and publication-journal completion. It verifies the exact
    /// consumed identity plus catalog/aggregate/completion/receipt set before
    /// completing the journal, and never creates a replacement authority.
    @discardableResult
    private func reconcileConsumedHistoricalTerminalPublicationIfNeeded(
        reason: String
    ) -> Bool {
        guard !historicalConsumerMaterializationInFlight,
              let job = try? historicalTerminalPublicationStore.load(),
              job.status == .projectionsPublished,
              (try? historicalRequestAuthorityStore.validateConsumedAuthority(
                  generation: job.authorityGeneration,
                  requestIdentifier: job.requestIdentifier,
                  peripheralIdentifier: job.peripheralIdentifier,
                  strapIdentity: job.strapIdentity,
                  exactRequest: job.exactRequest
              )) != nil else {
            return false
        }
        let timeZoneIdentifier = TimeZone.current.identifier
        let restingHeartRate = restingHR ?? 60
        let configuration = AtriaHistoricalConsumerProjectionConfiguration.production(
            restingHeartRate: restingHeartRate,
            maximumHeartRate: maxHRSetting,
            timeZoneIdentifier: timeZoneIdentifier
        )
        let publicationStore = historicalTerminalPublicationStore
        historicalConsumerMaterializationInFlight = true
        historicalArchiveQueue.async { [weak self] in
            var status = "deferred"
            var detail = "unknown"
            do {
                let result = try HistoricalArchive
                    .resumeTerminalConsumerProjectionsAfterCrash(
                        job: job,
                        configuration: configuration
                    )
                guard result.consumers.hasCompleteConsumerCoverage else {
                    throw AtriaBLEHistoryTerminalMaterializationError
                        .incompleteConsumerCoverage
                }
                try publicationStore.markAuthorityConsumedAfterReconciliation(job)
                status = "completed"
                detail = "consumed_authority_and_five_artifact_set_reverified"
            } catch {
                detail = String(describing: error)
            }
            AtriaDebugLog("ATRIADBG historical_consumers_reconcile status=%@ reason=%@ authority_generation=%llu detail=%@ raw_retained=1",
                          status,
                          reason,
                          job.authorityGeneration,
                          detail)
            Task { @MainActor [weak self] in
                self?.historicalConsumerMaterializationInFlight = false
            }
        }
        return true
    }

    private func startHistoricalDrainTelemetry(generation: UInt64) {
        historicalDrainTelemetryTask?.cancel()
        historicalDrainTelemetry.reset(generation: generation)
        historicalDrainTelemetryTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                do {
                    try await Task.sleep(for: .seconds(5))
                } catch {
                    return
                }
                guard !Task.isCancelled,
                      let self,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation else {
                    return
                }
                self.emitHistoricalDrainTelemetry(generation: generation,
                                                  trigger: "periodic")
            }
        }
    }

    private func emitHistoricalDrainTelemetry(
        generation: UInt64,
        trigger: String,
        now: Date = Date()
    ) {
        guard historicalDrainTelemetry.generation == generation else { return }
        let pending = pendingHistoricalTransportEventCount
            + historyDrain.pendingPersistenceCount
            + (historicalAdmissionBatchInFlight ? 1 : 0)
        historicalDrainTelemetry.observePending(pending)
        let lastProgressAge = max(0, now.timeIntervalSince(
            historicalDrainTelemetry.lastProgressAt
        ))
        AtriaDebugLog("ATRIADBG historyDrainTelemetry trigger=%@ generation=%llu stream5_rx=%d admitted=%d decoded=%d decode_errors=%d persisted=%d persist_errors=%d pending=%d pending_high_water=%d flush_started=%d flush_ok=%d flush_errors=%d ack_sent=%d ack_ok=%d ack_errors=%d last_progress_age_s=%.1f phase=%@",
                      trigger,
                      generation,
                      historicalDrainTelemetry.stream5Received,
                      historicalDrainTelemetry.admitted,
                      historicalDrainTelemetry.decoded,
                      historicalDrainTelemetry.decodeErrors,
                      historicalDrainTelemetry.persisted,
                      historicalDrainTelemetry.persistErrors,
                      pending,
                      historicalDrainTelemetry.pendingHighWater,
                      historicalDrainTelemetry.flushStarted,
                      historicalDrainTelemetry.flushSucceeded,
                      historicalDrainTelemetry.flushErrors,
                      historicalDrainTelemetry.ackSent,
                      historicalDrainTelemetry.ackSucceeded,
                      historicalDrainTelemetry.ackErrors,
                      lastProgressAge,
                      historyDrain.phaseForDiagnostics)
    }

    private func finishHistoricalDrainTelemetry(generation: UInt64, trigger: String) {
        emitHistoricalDrainTelemetry(generation: generation, trigger: trigger)
        historicalDrainTelemetryTask?.cancel()
        historicalDrainTelemetryTask = nil
    }

    private func finishOfflineHistoricalSync(
        reason: String,
        generation: UInt64,
        resumePendingSync: Bool = true
    ) {
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else {
            AtriaDebugLog("ATRIADBG offline_sync status=ignored reason=%@ detail=stale_completion generation=%llu current=%llu",
                          reason,
                          generation,
                          offlineHistoricalSyncGeneration)
            return
        }
        let rawOnlyGapFingerprint = offlineHistoricalSyncRawOnlyGapFingerprint
        offlineHistoricalSyncRawOnlyGapFingerprint = nil
        let gapFingerprint = offlineHistoricalSyncGapFingerprint
        offlineHistoricalSyncGapFingerprint = nil
        let rows = historicalArchiveRows
        let newRows = max(0, rows - offlineHistoricalSyncStartRows)
        historyOnlyProbeEnabled = false
        if freshHistoryOwnerConnectionGeneration == generation {
            freshHistoryOwnerConnectionGeneration = nil
        }
        cancelHistoryOnlyProbe(reason: "offline_sync_finished")
        historicalMetricDurabilityFence.invalidate(generation: generation)
        historyDurableFlushInFlight = false
        pendingHistoryEndACK = nil
        pendingHistoryACKAttempts = 0
        historyACKGate.reset()
        historicalPageContinuationTask?.cancel()
        historicalPageContinuationTask = nil
        historyFirstFrameWatchdogTask?.cancel()
        historyFirstFrameWatchdogTask = nil
        historyFirstFrameReceivedGeneration = nil
        historicalReplayACKTask?.cancel()
        historicalReplayACKTask = nil
        historicalReplayACKBoundaryID = nil
        historyReadPreflightGate.reset()
        acceptedHistoryReadPreflightIdentity = nil
        productionHistoryReadPreflightRequired = false
        historyClockSyncEnabled = false
        productionFullDrainClockAuthorityEnabled = false
        historyClockRef = nil
        historyRealtimeStopRequestedGeneration = nil
        historyRealtimeStopCompletedGeneration = nil
        endOfflineHistoricalSyncBackgroundLease(status: "terminal_\(reason)")
        historyInitSweepCommands.removeAll()
        historySkipDataRangeRequest = false
        probeCommandMode = .withoutResponse
        finishHistoricalDrainTelemetry(generation: generation, trigger: "finish")
        let mayDiscardIngress = offlineHistoricalSyncReachedTerminal
            && !historicalAdmissionFailed
            && pendingHistoricalTransportEventCount == 0
            && historyDrain.pendingPersistenceCount == 0
            && !historicalAdmissionBatchInFlight
        if mayDiscardIngress {
            // The reducer terminal proof and canonical archive durability have
            // both completed. Only now is this raw ingress cache disposable.
            historicalIngressSpool?.remove()
        } else {
            // Preserve a failed/interrupted generation for crash diagnostics;
            // it cannot be reused as a new generation's ACK authority.
            try? historicalIngressSpool?.synchronize()
        }
        historicalIngressSpool = nil
        historicalIngressDeferredEvent = nil
        offlineHistoricalSyncInProgress = false
        // Keep the phase visible until the transaction is no longer active, so
        // an in-flight RX/stream4 callback is never dropped inside the drain.
        _ = historyTransportPhaseFence.deactivate(ifMatching: generation)
        HistoricalArchive.endDurableDrain(generation: generation)
        offlineHistoricalSyncTimeoutTask?.cancel()
        offlineHistoricalSyncTimeoutTask = nil
        offlineHistoricalSyncLastProgressUptime = nil
        offlineHistoricalSyncStartRows = rows
        let verifiedEmptyCursor = verifiedEmptyHistoryCursorGeneration == generation
        let completedDrain = offlineHistoricalSyncReachedTerminal || verifiedEmptyCursor
        let requestedWindowMetricProgress = offlineHistoricalSyncMadeRequestedMetricProgress
        let ledgerCoverageResolved = offlineHistoricalSyncResolvedGapCoverage
        let restoredStandardHROnlyMode = Self.standardHROnlyModeAfterOfflineSync(
            modeBeforeSync: offlineHistoricalSyncPreviousStandardHROnlyMode
        )
        applyStandardHROnly(enabled: restoredStandardHROnlyMode,
                            persist: false,
                            reconnect: false,
                            reason: "offline_sync_complete_preserve_live_radio")
        if peripheral?.state == .connected {
            // History and standard HR share one physical connection, but a
            // terminal/timeout callback does not prove that 2A37's CCCD is
            // still active. Restore that subscription on every generation-
            // matching exit before touching the optional proprietary stream.
            // The helper preserves an already-healthy lease and only repairs a
            // missing/non-notifying characteristic, so completion cannot create
            // another live-data gap by toggling a working subscription.
            reassertHeartRateNotificationsIfConnected(
                reason: "offline_sync_terminal_\(reason)"
            )
            if txCharacteristic != nil {
                armRealtime()
            } else {
                peripheral?.discoverServices(discoveryServicesForCurrentMode)
            }
        }

        guard completedDrain,
              let restorationPeripheral = peripheral,
              restorationPeripheral.state == .connected else {
            finalizeOfflineHistoricalSyncAfterLiveRestoration(
                reason: reason,
                generation: generation,
                rows: rows,
                newRows: newRows,
                rawOnlyGapFingerprint: rawOnlyGapFingerprint,
                gapFingerprint: gapFingerprint,
                requestedWindowMetricProgress: requestedWindowMetricProgress,
                ledgerCoverageResolved: ledgerCoverageResolved,
                terminalAndLiveRestored: false,
                resumePendingSync: resumePendingSync
            )
            return
        }

        let restorationPeripheralID = restorationPeripheral.identifier
        let restorationEpoch = bleCallbackEpochFence.epoch
        let restorationRequestedAt = Date()
        postHistoryLiveRestorationGeneration = generation
        UserDefaults.standard.set("awaiting_post_history_live_sample",
                                  forKey: OfflineSyncDefaults.lastStatus)
        AtriaDebugLog("ATRIADBG offline_sync status=awaiting_live_restore reason=%@ generation=%llu epoch=%llu peripheral=%@ timeout_s=%.0f action=withhold_completion_and_gap_clear",
                      reason,
                      generation,
                      restorationEpoch,
                      restorationPeripheralID.uuidString,
                      postHistoryLiveRestorationTimeout)
        postHistoryLiveRestorationTask?.cancel()
        postHistoryLiveRestorationTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let deadline = restorationRequestedAt.addingTimeInterval(
                self.postHistoryLiveRestorationTimeout
            )
            var restored = false
            var repairReasserted = false
            while !Task.isCancelled, Date() < deadline {
                let samePeripheral = self.peripheral?.identifier == restorationPeripheralID
                let sameEpoch = self.bleCallbackEpochFence.epoch == restorationEpoch
                let connected = self.peripheral?.state == .connected
                    && self.status == .connected
                if samePeripheral,
                   sameEpoch,
                   connected,
                   let acceptedAt = self.lastAcceptedHRAt,
                   acceptedAt > restorationRequestedAt {
                    restored = true
                    break
                }
                guard samePeripheral, sameEpoch, connected else { break }
                if !repairReasserted,
                   Date().timeIntervalSince(restorationRequestedAt) >= 5 {
                    repairReasserted = true
                    self.reassertHeartRateNotificationsIfConnected(
                        reason: "offline_sync_live_restore_retry_\(reason)"
                    )
                }
                try? await Task.sleep(for: .milliseconds(250))
            }
            guard !Task.isCancelled,
                  self.postHistoryLiveRestorationGeneration == generation else { return }
            self.postHistoryLiveRestorationTask = nil
            self.postHistoryLiveRestorationGeneration = nil
            self.finalizeOfflineHistoricalSyncAfterLiveRestoration(
                reason: reason,
                generation: generation,
                rows: rows,
                newRows: newRows,
                rawOnlyGapFingerprint: rawOnlyGapFingerprint,
                gapFingerprint: gapFingerprint,
                requestedWindowMetricProgress: requestedWindowMetricProgress,
                ledgerCoverageResolved: ledgerCoverageResolved,
                terminalAndLiveRestored: restored,
                resumePendingSync: resumePendingSync
            )
        }
    }

    private func finalizeOfflineHistoricalSyncAfterLiveRestoration(
        reason: String,
        generation: UInt64,
        rows: Int,
        newRows: Int,
        rawOnlyGapFingerprint: String?,
        gapFingerprint: String?,
        requestedWindowMetricProgress: Bool,
        ledgerCoverageResolved: Bool,
        terminalAndLiveRestored: Bool,
        resumePendingSync: Bool
    ) {
        lastCompletedHistoricalSyncGeneration = generation
        lastCompletedHistoricalSyncReachedTerminal = terminalAndLiveRestored
            && offlineHistoricalSyncReachedTerminal
        let onboardingTransportAuthority = Self
            .onboardingHistoryTransportAuthorityIsValid(
                terminalReceived: offlineHistoricalSyncReachedTerminal,
                durableTerminalAuthority: durableTerminalAuthorityGeneration == generation,
                verifiedEmptyCursor: verifiedEmptyHistoryCursorGeneration == generation
            )
        lastCompletedHistoricalSyncHasOnboardingAuthority = terminalAndLiveRestored
            && onboardingTransportAuthority
        let rawOnlyGapArchived = rawOnlyGapFingerprint != nil
            && newRows > 0
            && terminalAndLiveRestored
        let completionStatus = !terminalAndLiveRestored && newRows > 0
            ? "partial_live_restore_unverified"
            : rawOnlyGapArchived
            ? "raw_gap_archived_awaiting_transaction_validation"
            : Self.historicalSyncCompletionStatus(
                newRows: terminalAndLiveRestored ? newRows : 0,
                requestedWindowMetricProgress: terminalAndLiveRestored
                    && requestedWindowMetricProgress,
                ledgerCoverageResolved: terminalAndLiveRestored
                    && ledgerCoverageResolved
            )
        let forwardCursorCaughtUp = reason.hasSuffix("_cursor_caught_up")
        let effectiveCompletionStatus = forwardCursorCaughtUp
            ? "strap_cursor_caught_up_older_gaps_retained"
            : completionStatus
        let defaults = UserDefaults.standard
        if let rawOnlyGapFingerprint, rawOnlyGapArchived {
            defaults.set(rawOnlyGapFingerprint,
                         forKey: OfflineSyncDefaults.rawArchivedGapFingerprint)
            defaults.set(Date().timeIntervalSince1970,
                         forKey: OfflineSyncDefaults.rawArchivedGapAt)
        }
        let noRowsForDurableGap = terminalAndLiveRestored
            && (offlineHistoricalSyncReachedTerminal
                || verifiedEmptyHistoryCursorGeneration == generation)
            && newRows == 0
            && gapFingerprint != nil
        if let gapFingerprint, noRowsForDurableGap {
            defaults.set(gapFingerprint, forKey: OfflineSyncDefaults.noRowsGapFingerprint)
            defaults.set(Date().timeIntervalSince1970, forKey: OfflineSyncDefaults.noRowsGapAt)
        }
        let publishedCompletionStatus = noRowsForDurableGap
            ? "no_rows_gap_retained"
            : effectiveCompletionStatus
        defaults.set(publishedCompletionStatus, forKey: OfflineSyncDefaults.lastStatus)
        defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
        let rangeLossResolved = terminalAndLiveRestored
            && reconcileRangeLossBackfillPendingWithArchive(
                reason: reason,
                newRows: newRows,
                requestedWindowMetricProgress: requestedWindowMetricProgress,
                ledgerCoverageResolved: ledgerCoverageResolved
            )
        if rangeLossResolved {
            defaults.removeObject(forKey: OfflineSyncDefaults.noRowsGapFingerprint)
            defaults.removeObject(forKey: OfflineSyncDefaults.noRowsGapAt)
            defaults.removeObject(
                forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
            )
            defaults.removeObject(
                forKey: OfflineSyncDefaults.historyStartTimeoutGapAt
            )
            defaults.removeObject(
                forKey: OfflineSyncDefaults.historyStartTimeoutProfileVersion
            )
        }
        if terminalAndLiveRestored && offlineHistoricalSyncReachedTerminal {
            if activeFullDrainEventIdentity?.transportGeneration == generation
                || activeHistoricalRequestBinding?.transportGeneration == generation {
                historicalConsumerReceiptRequiredGenerations.insert(generation)
            }
            scheduleFullDrainConsumerMaterialization(transportGeneration: generation)
            schedulePendingConsumerFollowupScanMaterialization(
                transportGeneration: generation
            )
            scheduleTerminalConsumerMaterializationIfAuthorized(
                transportGeneration: generation
            )
        }
        if !rangeLossResolved && !rawOnlyGapArchived && !forwardCursorCaughtUp && !noRowsForDurableGap {
            scheduleRangeLossBackfillRetry(reason: reason)
        }
        AtriaDebugLog("ATRIADBG offline_sync status=%@ reason=%@ generation=%llu rows=%d new_rows=%d live_restored=%d action=%@",
                      publishedCompletionStatus,
                      reason,
                      generation,
                      rows,
                      newRows,
                      terminalAndLiveRestored ? 1 : 0,
                      terminalAndLiveRestored
                        ? "publish_after_fresh_hr"
                        : "retain_gap_retry_realtime")
        if resumePendingSync,
           let pending = takePendingOfflineHistoricalSyncRequest() {
            requestOfflineHistoricalSyncIfNeeded(
                reason: pending.reason,
                force: pending.force,
                explicitResearchRequest: pending.explicitRequest
            )
        }
        resumeWorkoutMotionLeaseAfterHistoricalSync(
            reason: "offline_sync_terminal_\(reason)"
        )
        onHistoricalTransportOwnershipReleased?("offline_sync_terminal_\(reason)")
    }

    private func interruptOfflineHistoricalSyncForTransportLoss(reason: String) {
        guard offlineHistoricalSyncInProgress else {
            cancelHistoryOnlyProbe(reason: reason)
            return
        }
        let interruptedGeneration = offlineHistoricalSyncGeneration
        historyFailureReconnectReissuePending = true
        offlineHistoricalSyncReachedTerminal = false
        AtriaDebugLog("ATRIADBG offline_sync status=interrupted reason=%@ generation=%llu action=cancel_probe_retain_gap_retry_after_reconnect",
                      reason,
                      interruptedGeneration)
        finishOfflineHistoricalSync(
            reason: "\(offlineHistoricalSyncReason)_\(reason)",
            generation: interruptedGeneration,
            resumePendingSync: false
        )
    }

    @discardableResult
    private func reconcileRangeLossBackfillPendingWithArchive(reason: String,
                                                             newRows: Int = 0,
                                                             requestedWindowMetricProgress: Bool = false,
                                                             ledgerCoverageResolved: Bool = false) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return true }
        // A successful offload is not proof that it covered every live outage.
        // The durable gap ledger retires intervals only from metric-usable rows
        // spanning every expected bucket in their exact timestamp ranges.
        guard !AtriaHistoricalGapLedger.hasPendingWindows(defaults: defaults) else {
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_retained reason=%@ detail=missing_windows_not_covered windows=%d",
                          reason,
                          AtriaHistoricalGapLedger.windows(defaults: defaults).count)
            return false
        }
        let archiveDiagnostics = HistoricalArchive.diagnostics()
        let archiveAlreadyMetricReady = archiveDiagnostics.parseOK
            && archiveDiagnostics.metricUsableRows > 0
            && archiveDiagnostics.currentSessionUsableRows > 0
        // Global archive readiness says nothing about the newly missing range.
        // The gym failure had an old, healthy archive yet no rows covering the
        // workout; clearing on `archiveAlreadyMetricReady` silently discarded the
        // recovery request. Only rows appended by this sync can acknowledge it.
        let hasRequestedWindow = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart) != nil
            && defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd) != nil
        guard Self.rangeLossBackfillCanClear(newRows: newRows,
                                             hasRequestedWindow: hasRequestedWindow,
                                             requestedWindowMetricProgress: requestedWindowMetricProgress,
                                             ledgerCoverageResolved: ledgerCoverageResolved) else { return false }
        defaults.set(false, forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.removeObject(forKey: OfflineSyncDefaults.recoveryWindowStart)
        defaults.removeObject(forKey: OfflineSyncDefaults.recoveryWindowEnd)
        defaults.set(Date().timeIntervalSince1970, forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt)
        assignIfChanged(\.rangeLossBackfillPending, false)
        AtriaDebugLog("ATRIADBG offline_sync status=range_loss_backfill_cleared reason=%@ new_rows=%d metric_ready=%d metric_rows=%d current_rows=%d",
                      reason,
                      newRows,
                      archiveAlreadyMetricReady ? 1 : 0,
                      archiveDiagnostics.metricUsableRows,
                      archiveDiagnostics.currentSessionUsableRows)
        return true
    }

    private func markRangeLossBackfillRequired(reason: String) {
        let defaults = UserDefaults.standard
        let alreadyPending = defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        if !alreadyPending || defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) == nil {
            defaults.set(Date().timeIntervalSince1970, forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt)
        }
        defaults.set(true, forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.set(reason, forKey: OfflineSyncDefaults.rangeLossBackfillReason)
        assignIfChanged(\.rangeLossBackfillPending, true)
        retainPendingOfflineHistoricalSyncRequest(
            reason: reason,
            force: false,
            explicitRequest: false
        )
        AtriaDebugLog("ATRIADBG offline_sync status=pending_range_loss_backfill reason=%@ action=sync_after_reconnect already_pending=%d",
              reason,
              alreadyPending ? 1 : 0)
    }

    private func preserveLongWearRangeLossRecovery(reason: String) {
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        persistActiveSessionJournalIfNeeded(reason: "\(reason)_continuity_checkpoint", force: true)
        guard longWearModeEnabled || activeExplicitWorkout else {
            // Balanced/on-demand mode still receives transient link drops. Keep
            // its live session durable and let the standard 90-second sample-gap
            // gate decide whether the reconnect belongs to a new segment.
            AtriaDebugLog("ATRIADBG active_session_journal status=checkpoint_requested reason=%@ mode=unexpected_disconnect_grace samples=%d",
                          reason,
                          session.count)
            return
        }
        // Off-wrist long-wear disconnects do not represent recoverable HR. A
        // user-started workout is still tracked from the disconnect instant if
        // its first accepted sample has not arrived yet.
        if activeExplicitWorkout || hasContact {
            let missingStart = lastAcceptedHRAt ?? Date()
            _ = AtriaHistoricalGapLedger.beginGap(at: missingStart,
                                                  reason: activeExplicitWorkout
                                                    ? "explicit_workout_disconnect"
                                                    : reason)
        }
        guard activeExplicitWorkout
                || hasContact
                || AtriaHistoricalGapLedger.hasPendingWindows() else {
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_skipped reason=%@ detail=off_wrist_no_recoverable_gap action=preserve_realtime_only",
                          reason)
            return
        }
        guard !offlineHistoricalSyncInProgress else {
            // A disconnect inside an opportunistic sync is still a missing range.
            // Mark it now; finishOfflineHistoricalSync will clear it only when
            // that same attempt actually appended rows.
            markRangeLossBackfillRequired(reason: activeExplicitWorkout
                                          ? "explicit_workout_range_loss"
                                          : "long_wear_range_loss")
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_marked reason=%@ detail=sync_in_progress explicit_workout=%d action=reconcile_on_sync_finish",
                          reason,
                          activeExplicitWorkout ? 1 : 0)
            return
        }
        let backfillReason = activeExplicitWorkout
            ? "explicit_workout_range_loss"
            : (strapStreamState == .lowBatteryShutoff
            ? "strap_low_battery_broadcast_off"
            : "long_wear_range_loss")
        markRangeLossBackfillRequired(reason: backfillReason)
        if status == .connected {
            scheduleRangeLossBackfillIfNeeded(reason: reason)
        }
    }

    private func scheduleRangeLossBackfillIfNeeded(reason: String) {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.enabled) else { return }
        guard !deferInterruptedFullDrainForCurrentLiveConnection else {
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            defaults.set("deferred_interrupted_full_drain_live_priority",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_interrupted_full_drain_live_priority reason=%@ action=hold_until_next_connection_or_explicit_diagnostic",
                          reason)
            return
        }
        scheduleStaleArmedRangeLossBackfillReconciliation(reason: reason)
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return }
        guard !offlineHistoricalSyncInProgress else { return }
        let verifiedPeripheralID = defaults.string(forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID)
        let currentPeripheralID = peripheral?.identifier.uuidString
        let previouslyVerified = currentPeripheralID != nil
            && currentPeripheralID == verifiedPeripheralID
        let rawHistoryVerified = Self.supportsVerifiedHistoricalRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified
        )
        let transactionRecoveryVerified = Self.supportsVerifiedHistoricalTransactionRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified,
            fullDrainGapRecoveryEnabled:
                Self.productionHistoricalFullDrainGapRecoveryEnabled
        )
        if rawHistoryVerified,
           !transactionRecoveryVerified,
           peripheral?.state == .connected {
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            defaults.set("gap_retained_transaction_unverified",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=gap_retained_transaction_unverified reason=%@ detail=decoder_ready_exact_range_or_clock_unverified action=suppress_automatic_connected_handoff_keep_gap_and_realtime",
                          reason)
            return
        }
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = Task { @MainActor in
            try? await Task.sleep(for: .seconds(8))
            guard !Task.isCancelled else { return }
            guard UserDefaults.standard.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return }
            guard status != .poweredOff else { return }
            let backfillReason = UserDefaults.standard.string(forKey: OfflineSyncDefaults.rangeLossBackfillReason) ?? reason
            let now = Date()
            let protectedLiveStream = shouldProtectLiveStreamForOfflineSync()
            let automaticConnectedHandoff = automaticConnectedHistoricalHandoffIsEligible(
                now: now
            )
            let forceStaleBackfill = (!protectedLiveStream || automaticConnectedHandoff)
                && shouldForceStaleRangeLossBackfill(now: now)
            let forceReadyBackfill = (!protectedLiveStream || automaticConnectedHandoff)
                && shouldForceReadyRangeLossBackfill(now: now)
            let forceBackfill = automaticConnectedHandoff || forceStaleBackfill || forceReadyBackfill
            let action = automaticConnectedHandoff
                ? "automatic_connected_handoff"
                : forceBackfill
                ? (forceStaleBackfill ? "force_stale_backfill" : "force_ready_backfill")
                : (protectedLiveStream ? "defer_live_stream" : "sync_when_available")
            AtriaDebugLog("ATRIADBG offline_sync status=requesting_range_loss_backfill reason=%@ trigger=%@ action=%@ live_protected=%d stale_force=%d ready_force=%d",
                  backfillReason,
                  reason,
                  action,
                  protectedLiveStream ? 1 : 0,
                  forceStaleBackfill ? 1 : 0,
                  forceReadyBackfill ? 1 : 0)
            let syncStarted = requestOfflineHistoricalSyncIfNeeded(
                reason: backfillReason,
                force: forceBackfill,
                allowConnectedAutomaticHandoff: automaticConnectedHandoff
            )
            let stillPending = UserDefaults.standard.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending)
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_backfill_request_result reason=%@ started=%d pending=%d force=%d action=%@",
                          backfillReason,
                          syncStarted ? 1 : 0,
                          stillPending ? 1 : 0,
                          forceBackfill ? 1 : 0,
                          action)
            if !syncStarted, stillPending {
                scheduleRangeLossBackfillRetry(reason: reason)
            }
        }
    }

    func schedulePendingHistoricalRecovery(reason: String) {
        assignIfChanged(\.rangeLossBackfillPending,
                        UserDefaults.standard.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending))
        scheduleRangeLossBackfillIfNeeded(reason: reason)
    }

    private func scheduleRangeLossBackfillRetry(reason: String) {
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = Task { @MainActor in
            let delay = rangeLossBackfillRetryDelay()
            AtriaDebugLog("ATRIADBG offline_sync status=retry_scheduled reason=%@ delay_s=%.0f ready_force_after_s=%.0f",
                          reason,
                          delay,
                          rangeLossBackfillReadyForceInterval)
            try? await Task.sleep(for: .seconds(delay))
            guard !Task.isCancelled else { return }
            scheduleRangeLossBackfillIfNeeded(
                reason: Self.stableRangeLossBackfillRetryReason(reason)
            )
        }
    }

    /// Timers are not a reliable wake source after iOS backgrounds a locked
    /// phone. Each accepted 2A37 sample is an observed execution opportunity,
    /// so use it to admit the existing safe handoff as soon as the current
    /// connection has reached its stability window. This does not loosen any
    /// policy gate and sends no command itself; the normal request path still
    /// journals the boundary and performs the single audited cutover.
    private func attemptQualifiedRangeLossBackfillAfterAcceptedHRIfNeeded(
        now: Date
    ) {
        guard !foregroundInteractiveMode,
              !deferInterruptedFullDrainForCurrentLiveConnection,
              UserDefaults.standard.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
              ),
              !offlineHistoricalSyncInProgress,
              automaticConnectedHistoricalHandoffIsEligible(now: now) else {
            return
        }
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = nil
        let reason = UserDefaults.standard.string(
            forKey: OfflineSyncDefaults.rangeLossBackfillReason
        ) ?? "accepted_hr_qualified_range_loss"
        AtriaDebugLog("ATRIADBG offline_sync status=accepted_hr_qualified_handoff reason=%@ action=admit_current_epoch_without_timer_dependency",
                      reason)
        _ = requestOfflineHistoricalSyncIfNeeded(
            reason: reason,
            force: true,
            allowConnectedAutomaticHandoff: true
        )
    }

    private func scheduleStaleArmedRangeLossBackfillReconciliation(reason: String,
                                                                   now: Date = Date()) {
        let defaults = UserDefaults.standard
        let lastStatus = defaults.string(forKey: OfflineSyncDefaults.lastStatus) ?? ""
        let clearableStatuses = ["armed", "archived", "archive_metric_ready", "throttled", "no_rows"]
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              clearableStatuses.contains(lastStatus),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double,
              let startedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt) as? Double,
              now.timeIntervalSince1970 - requestedAt >= rangeLossBackfillArmedTimeout else {
            return
        }
        guard !powerThermalGovernor.shouldDeferNonEssentialAnalysis else { return }
        let minimumInterval: TimeInterval = 2 * 60
        guard Self.shouldScheduleStaleRangeLossReconciliation(
            inFlight: staleRangeLossReconciliationInFlight,
            lastAttemptAt: lastStaleRangeLossReconciliationAttemptAt,
            now: now,
            minimumInterval: minimumInterval
        ) else { return }
        staleRangeLossReconciliationInFlight = true
        lastStaleRangeLossReconciliationAttemptAt = now
        // Do not clear from global archive readiness. That proves only that some
        // historical range decoded in the past, not that the requested outage is
        // present. Keep the durable request armed; didConnect / the retry state
        // machine will run another bounded sync and only `newRows > 0` may ack it.
        staleRangeLossReconciliationInFlight = false
        AtriaDebugLog("ATRIADBG offline_sync status=stale_armed_retained reason=%@ last_status=%@ requested_age_s=%.0f armed_age_s=%.0f action=retry_until_new_rows",
                      reason,
                      lastStatus,
                      now.timeIntervalSince1970 - requestedAt,
                      now.timeIntervalSince1970 - startedAt)
    }

    nonisolated static func shouldRestoreProtectedLongWearRadioInBackground(
        activeExplicitWorkout: Bool
    ) -> Bool {
        !activeExplicitWorkout
    }

    /// Preserve the radio mode that the launch safety policy persisted. A
    /// background edge must never silently undo protected standard-HR mode and
    /// re-enable a proprietary stream that failed the physical stability soak.
    /// `userSelectedBatterySaver` remains part of the signature for migration
    /// compatibility, but production safety is represented by the persisted
    /// mode itself.
    nonisolated static func shouldUseStandardHROnlyInProtectedBackground(
        userSelectedBatterySaver: Bool,
        persistedStandardHROnly: Bool
    ) -> Bool {
        _ = userSelectedBatterySaver
        return persistedStandardHROnly
    }

    /// Session durability, workout analysis and link recovery are independent
    /// of whether the proprietary full protocol or Battery Saver HR-only radio
    /// mode is active. The radio-mode parameter is intentionally retained so a
    /// regression test covers the full-protocol case that previously stalled.
    nonisolated static func shouldRunLongWearSupervisor(
        longWearEnabled: Bool,
        standardHROnlyMode: Bool
    ) -> Bool {
        _ = standardHROnlyMode
        return longWearEnabled
    }

    nonisolated static func isBLEContinuityRelevant(
        longWearEnabled: Bool,
        activeExplicitWorkout: Bool
    ) -> Bool {
        longWearEnabled || activeExplicitWorkout
    }

    /// A live workout that retained both its in-memory samples and connected
    /// strap link across an app switch needs only a cheap subscription
    /// health check. Journal restore, supervisor reconstruction, range-loss
    /// reconciliation, scanning, and service rediscovery are recovery work for
    /// missing state—not prerequisites for the first returning frame.
    nonisolated static func shouldUseFastWorkoutForegroundResume(
        activeExplicitWorkout: Bool,
        hasLiveSession: Bool,
        linkConnected: Bool
    ) -> Bool {
        activeExplicitWorkout && hasLiveSession && linkConnected
    }

    nonisolated static func shouldPreserveSessionOnUnexpectedDisconnect(
        longWearEnabled: Bool,
        activeExplicitWorkout: Bool,
        userRequestedDisconnect: Bool
    ) -> Bool {
        _ = longWearEnabled
        _ = activeExplicitWorkout
        return !userRequestedDisconnect
    }

    private func rangeLossBackfillRetryDelay(now: Date = Date()) -> TimeInterval {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double else {
            return rangeLossBackfillRetryInterval
        }
        let pendingAge = max(0, now.timeIntervalSince1970 - requestedAt)
        guard pendingAge < rangeLossBackfillReadyForceInterval else {
            return min(rangeLossBackfillRetryInterval, 30)
        }
        return min(rangeLossBackfillRetryInterval,
                   max(15, rangeLossBackfillReadyForceInterval - pendingAge))
    }

    private func shouldForceStaleRangeLossBackfill(now: Date = Date()) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double else {
            return false
        }
        return now.timeIntervalSince1970 - requestedAt >= rangeLossBackfillRetryInterval
    }

    private func shouldForceReadyRangeLossBackfill(now: Date = Date()) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double else {
            return false
        }
        return now.timeIntervalSince1970 - requestedAt >= rangeLossBackfillReadyForceInterval
    }

    private func offlineHistoricalSyncMinimumInterval(for reason: String) -> TimeInterval {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else {
            return offlineHistoricalSyncMinimumInterval
        }
        let pendingReason = defaults.string(forKey: OfflineSyncDefaults.rangeLossBackfillReason) ?? ""
        guard reason == pendingReason || reason.contains("range_loss") || reason.contains("long_wear_range_loss") else {
            return offlineHistoricalSyncMinimumInterval
        }
        return rangeLossBackfillRetryInterval
    }

    private func shouldProtectLiveStreamForOfflineSync(now: Date = Date()) -> Bool {
        Self.shouldProtectConnectedLinkForOfflineSync(
            connected: peripheral?.state == .connected,
            connectedAt: connectedAt,
            hasContact: hasContact,
            acceptedSampleCount: session.count,
            lastAcceptedHRAt: lastAcceptedHRAt,
            now: now,
            minimumSamples: autoSaveMinSamples,
            acceptedFreshnessWindow: offlineSyncLiveAcceptedHRProtectionWindow
        )
    }

    private func resumeForegroundScanIfNeeded(reason: String) {
        recomputeConnectionStatus(reason: "\(reason)_foreground_resume")
        guard peripheral == nil else { return }
        if hasSavedStrap, status == .connecting {
            _ = reconnectToSavedPeripheralIfPossible(reason: "\(reason)_resume_known_strap")
            return
        }
        guard status == .disconnected || status == .poweredOff else { return }
        startScan(reason: "\(reason)_resume")
    }

    private func applyStandardHROnly(enabled: Bool, persist: Bool, reconnect: Bool, reason: String) {
        let previous = standardHROnlyMode
        proprietaryNotifyFallbackTask?.cancel()
        proprietaryNotifyFallbackTask = nil
        activeProprietaryNotifyUUIDs.removeAll()
        strapStream5NotifyConfirmed = false
        standardHROnlyMode = enabled
        standardHROnlyEnabled = enabled
        if enabled {
            stopR10LivenessWatchdog(reason: "standard_hr_only_\(reason)")
        }
        if persist {
            UserDefaults.standard.set(enabled, forKey: RadioDefaults.standardHROnly)
        }
        if enabled {
            realtimeStartRetries = 0
            forceFreshScanOnRestore = true
        }
        AtriaDebugLog("ATRIADBG radio_mode mode=%@ persist=%d reconnect=%d reason=%@",
              enabled ? "protected_r10_minimal" : "full_protocol",
              persist ? 1 : 0,
              reconnect ? 1 : 0,
              reason)
        recordRadioMode(enabled ? "protected_r10_minimal" : "full_protocol", reason: reason)
        guard reconnect, previous != enabled, let peripheral else { return }
        txCharacteristic = nil
        heartRateCharacteristic = nil
        dbgTxReady = false
        realtimeArmed = false
        dbgLast = enabled ? "stable HR + R10 pending reconnect" : "full protocol pending reconnect"
        cancelPeripheralConnection(peripheral, reason: "radio_mode_\(reason)")
    }

    private static func currentSampleStatusAndReason() -> (status: String, reason: String) {
        let defaults = UserDefaults.standard
        return (evidenceToken(defaults.string(forKey: SampleDefaults.lastStatus) ?? "none"),
                evidenceToken(defaults.string(forKey: SampleDefaults.lastReason) ?? "none"))
    }

    private static func sampleFields(for saved: SavedSession) -> String {
        let sample = currentSampleStatusAndReason()
        return String(format: "hr_raw_2a37=%d hr_accepted=%d hr_zero=%d hr_artifact_held=%d hr_artifact_dropped=%d hr_raw_gaps=%d hr_accepted_gaps=%d hr_max_raw_gap_s=%.1f hr_max_accepted_gap_s=%.1f hr_sample_last_status=%@ hr_sample_last_reason=%@",
                      saved.hrRaw2A37Value,
                      saved.hrAcceptedValue,
                      saved.hrZeroValue,
                      saved.hrArtifactHeldValue,
                      saved.hrArtifactDroppedValue,
                      saved.hrRawGapsValue,
                      saved.hrAcceptedGapsValue,
                      saved.hrMaxRawGapValue,
                      saved.hrMaxAcceptedGapValue,
                      sample.status,
                      sample.reason)
    }

    private func workoutCaptureEvidence(for saved: SavedSession,
                                        readiness: WorkoutReadiness) -> WorkoutCaptureEvidence {
        let sample = Self.currentSampleStatusAndReason()
        let sampleFields = Self.sampleFields(for: saved)
        guard !readiness.ready else {
            return WorkoutCaptureEvidence(diagnosis: "candidate_valid",
                                          action: "save_or_validate_workout",
                                          sampleFields: sampleFields)
        }
        if saved.hrZeroValue > 0 || sample.status == "zero_contact" || sample.reason == "hr_zero" || sample.reason == "zero_contact" {
            return WorkoutCaptureEvidence(diagnosis: "contact_loss",
                                          action: "keep_learning_check_fit_contact",
                                          sampleFields: sampleFields)
        }
        let droppedFraction = readiness.duration > 0 ? readiness.droppedGapSeconds / readiness.duration : 0
        if readiness.streamCoveragePercent < 75
            || readiness.maxSampleGap > SavedSession.workoutContinuityGapLimit
            || droppedFraction >= 0.25 {
            return WorkoutCaptureEvidence(diagnosis: "stream_gaps",
                                          action: "keep_learning_reconnect_or_keep_phone_near",
                                          sampleFields: sampleFields)
        }
        if (saved.hrArtifactHeldValue + saved.hrArtifactDroppedValue) > 0 && readiness.thresholdGapBPM > 0 {
            return WorkoutCaptureEvidence(diagnosis: "artifact_filtering_or_motion",
                                          action: "inspect_raw_hr_artifacts",
                                          sampleFields: sampleFields)
        }
        if readiness.thresholdGapBPM > 0 {
            return WorkoutCaptureEvidence(diagnosis: "received_hr_below_threshold",
                                          action: "compare_reference_hr_before_profile_change",
                                          sampleFields: sampleFields)
        }
        if readiness.hrDistributionBelowWorkoutBand {
            return WorkoutCaptureEvidence(diagnosis: "wrist_hr_distribution_below_workout_band",
                                          action: "validate_wrist_hr_underreporting_or_profile_before_more_workouts",
                                          sampleFields: sampleFields)
        }
        if readiness.observedDuration < 10 * 60 {
            return WorkoutCaptureEvidence(diagnosis: "too_short",
                                          action: "keep_collecting",
                                          sampleFields: sampleFields)
        }
        return WorkoutCaptureEvidence(diagnosis: Self.evidenceToken(readiness.primaryBlocker),
                                      action: "keep_learning",
                                      sampleFields: sampleFields)
    }

    private func recordLinkAttempt(reason: String, peripheral: CBPeripheral?) {
        let defaults = UserDefaults.standard
        let attempts = defaults.integer(forKey: LinkDefaults.attempts) + 1
        defaults.set(attempts, forKey: LinkDefaults.attempts)
        defaults.set("connecting", forKey: LinkDefaults.lastStatus)
        defaults.set(reason, forKey: LinkDefaults.lastReason)
        refreshOfficialAppCoexistenceRisk(reason: "link_attempt")
        AtriaDebugLog("ATRIADBG ble_link status=connecting reason=%@ attempts=%d disconnects=%d failures=%d name=%@",
              reason,
              attempts,
              defaults.integer(forKey: LinkDefaults.disconnects),
              defaults.integer(forKey: LinkDefaults.failures),
              peripheral?.name ?? deviceName)
    }

    private func markPendingKnownReconnect(reason: String) {
        pendingKnownReconnectStartedAt = Date()
        pendingKnownReconnectReason = reason
    }

    private func clearPendingKnownReconnect(reason: String) {
        guard pendingKnownReconnectStartedAt != nil || !pendingKnownReconnectReason.isEmpty else { return }
        pendingKnownReconnectStartedAt = nil
        pendingKnownReconnectReason = ""
        AtriaDebugLog("ATRIADBG ble_link pending_known_reconnect status=cleared reason=%@", reason)
    }

    private func recordLinkConnected(peripheral: CBPeripheral) {
        clearPendingKnownReconnect(reason: "did_connect")
        let defaults = UserDefaults.standard
        // Remember this strap so we can re-arm a standing pending connection to it
        // on every launch / drop without scanning. "Connect once, stay connected."
        defaults.set(peripheral.identifier.uuidString, forKey: LinkDefaults.savedPeripheralUUID)
        let successes = defaults.integer(forKey: LinkDefaults.successes) + 1
        defaults.set(successes, forKey: LinkDefaults.successes)
        defaults.set("connected", forKey: LinkDefaults.lastStatus)
        defaults.set("did_connect", forKey: LinkDefaults.lastReason)
        defaults.set("none", forKey: LinkDefaults.lastError)
        persistOfficialAppCoexistenceRisk(.cleared, reason: "atria_connected")
        AtriaDebugLog("ATRIADBG ble_link status=connected successes=%d attempts=%d disconnects=%d failures=%d mtu=%d name=%@",
              successes,
              defaults.integer(forKey: LinkDefaults.attempts),
              defaults.integer(forKey: LinkDefaults.disconnects),
              defaults.integer(forKey: LinkDefaults.failures),
              dbgMTU,
              peripheral.name ?? deviceName)
        scheduleRangeLossBackfillIfNeeded(reason: "did_connect")
    }

    private func recordLinkObservedConnected(reason: String, peripheral: CBPeripheral) {
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: LinkDefaults.lastStatus) != "connected" else { return }
        let successes = defaults.integer(forKey: LinkDefaults.successes) + 1
        defaults.set(successes, forKey: LinkDefaults.successes)
        defaults.set("connected", forKey: LinkDefaults.lastStatus)
        defaults.set(reason, forKey: LinkDefaults.lastReason)
        defaults.set("none", forKey: LinkDefaults.lastError)
        persistOfficialAppCoexistenceRisk(.cleared, reason: "atria_observed_connected")
        AtriaDebugLog("ATRIADBG ble_link status=connected reason=%@ successes=%d attempts=%d disconnects=%d failures=%d name=%@",
              reason,
              successes,
              defaults.integer(forKey: LinkDefaults.attempts),
              defaults.integer(forKey: LinkDefaults.disconnects),
              defaults.integer(forKey: LinkDefaults.failures),
              peripheral.name ?? deviceName)
    }

